// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 파괴
// 전사 · 화염술사 · 권사 · 폭파공 · 대검사
// 파괴: 부르는 것을 끊고, 끌고 가는 손을 부순다 — 누가 보고 있는 어둠 속에서
// ==========================================

// ------------------------------------------
// 전사 · 무력
// ------------------------------------------
kJob('warrior', 'A', [

{ at:'A', t:'복도 — 맨 뒤에서 부르는 목소리',
  x:`복도가 길다. 불은 앞사람 손에만 있다. 맨 뒤에는 늘 무기를 든 사람이 선다.<br><br>
    뒤에서 누가 이쪽 이름을 부른다. 동료 목소리다. 그 동료는 지금 이쪽 바로 앞에서 걷고 있다.<br>
    목소리는 서두르지 않는다. 한 번 부르고 한참 쉬고 또 부른다. 대답을 기다리는 틈이다.<br><br>
    무기를 쥔 손이 먼저 돌아서려 한다. 소리가 나면 그쪽을 치는 손이다. 오래 그렇게 살았다.`,
  o:[
    { l:'① 돌아서서 소리 나는 데를 친다.', k:'break', dc:22,
      doom:{ title:'뒤에서 부르던 것', what:'무기째 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`돌아서며 휘둘렀다. 날이 허공을 지난다. 아무것도 안 걸린다.<br><br>이름이 다시 불린다. 이번엔 바로 앞에서. 입김이 귀에 닿을 거리다.<br>무기 자루를 무엇이 쥐었다. 이쪽 손 바로 위를. 손가락이 차고 길다. 당긴다. 천천히.<br><br>손을 펴면 된다. 손이 안 펴진다. 무기를 놓는 법을 이 손은 배운 적이 없다. 발뒤꿈치가 바닥에 끌린다. 복도 반대쪽 어둠으로.`,
        dieText:`앞사람들이 돌아봤을 때 맨 뒤가 비어 있었다.<br><br>불을 비추자 복도 끝에 무기 하나가 서 있다. 벽에 반듯하게 기대 놓였다. 누가 맡겨 두고 간 것처럼.<br>그 뒤로 일행은 맨 뒤에 아무도 세우지 않았다. 그래도 누가 이름을 부른다.` },
      ok:`돌아서되 휘두르지 않았다. 무기를 가슴 앞에 세우고 어둠을 마주 봤다.<br><br>목소리가 멈췄다. 얼굴을 마주 보는 것 앞에서는 부르지 않는다. 등을 보일 때만 부른다.<br>한참 그대로 섰다가 뒷걸음으로 걸었다. 일행을 따라. 등을 한 번도 안 보였다.<br><br>복도가 끝날 때까지 이름은 다시 불리지 않았다. 목덜미가 땀으로 젖었다.`,
      win:{ exp:20, dream:3 } },
    { l:'② 돌아보지 않는다 — 무기를 거꾸로 메어 날을 뒤로 둔다.', k:'steady', dc:22, wake:1,
      ok:`무기를 등에 거꾸로 멨다. 날이 뒤를 본다. 손은 앞에 두고 걸었다.<br><br>목소리가 가까워진다. 이름. 쉼. 이름. 그러다 등 뒤에서 쇳소리가 났다. 날에 무엇이 닿았다. 그리고 조용해졌다.<br>돌아보지 않았다. 볼 필요가 없었다.<br><br>뒤를 맡는다는 게 돌아서는 일인 줄 알았다. 날이 뒤를 보면 몸은 앞을 봐도 된다. 등이 하나의 자세가 됐다. 어깨가 그 무게를 금방 외웠다.`,
      ng:`날을 뒤로 메는 사이 이름이 귓바퀴 바로 뒤에서 불렸다.<br><br>몸이 굳었다. 대답하지는 않았다. 입술이 저절로 달싹였을 뿐이다.<br>앞사람이 돌아보며 이쪽 얼굴을 살핀다. 방금 무슨 말을 했느냐고 묻는다. 아무 말도 안 했다. 했는지도 모른다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 앞사람 어깨에 손을 얹고 걷는다.', k:'bond', dc:21,
      ok:`앞사람 어깨에 왼손을 얹었다. 오른손에는 무기.<br><br>어깨가 따뜻하다. 진짜 동료다. 이름이 다시 불렸다. 같은 목소리. 그런데 어깨 밑의 사람은 입을 다물고 있다.<br>어느 쪽이 진짜인지 손이 안다. 손을 떼지 않고 끝까지 걸었다.<br><br>복도 끝에서 앞사람이 그제야 말했다. 아까부터 누가 자기 이름을 불렀다고. 이쪽 목소리로.`,
      ng:`어깨에 손을 얹었다. 차다.<br><br>앞사람이 돌아본다. 동료 얼굴이다. 그런데 웃고 있다. 그 동료는 여기 와서 한 번도 웃지 않았다.<br>손을 떼고 물러섰다. 다시 보니 동료가 울상으로 이쪽을 보고 있다. 왜 그러느냐고. 아까 그 얼굴이 무엇이었는지 끝내 말하지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A1', t:'의상실 — 칼을 든 삐뚤이',
  x:`의상실 구석에 인형탈 하나가 서 있다. 걸린 게 아니라 서 있다. 삐뚤이다. 한 손에 스펀지 칼을 들었다.<br><br>
    칼을 든 자세가 낯익다. 발 너비, 팔꿈치 높이, 칼끝이 기운 각도. 무기를 쥔 이쪽 자세 그대로다.<br>
    이쪽이 발을 옮기자 삐뚤이 발도 옮겨진다. 거울처럼이 아니다. 반 박자 먼저.<br><br>
    벽에 큐시트가 붙어 있다. 오늘의 코너 — 칼싸움 놀이. 그 밑에 작게. 이긴 친구는 무대로.`,
  o:[
    { l:'① 먼저 들어가 칼 든 손을 친다.', k:'break', dc:23,
      ok:`칼을 노리지 않았다. 칼을 쥔 손목을 쳤다. 장갑 손이 통째로 떨어져 바닥에 굴렀다. 손가락 넷이 오므라든다.<br><br>삐뚤이가 빈 소매를 내려다본다. 칼이 없다. 손이 없다. 칼싸움은 칼이 있어야 한다.<br>스피커에서 박수가 나오려다 멈췄다. 이긴 사람이 없으면 박수도 없다.<br><br>탈은 그대로 섰다. 지나가는 동안 머리만 이쪽을 따라 돌았다. 아주 천천히.`,
      ng:`손목을 노렸는데 삐뚤이가 반 박자 먼저 비켰다. 이쪽이 칠 데를 이쪽보다 먼저 안다.<br><br>스펀지 칼이 이쪽 정수리를 톡 친다. 가볍다. 그런데 머릿속까지 차가워진다.<br>스피커에서 웃음이 터진다. 아이들 웃음이다. 녹음이다. 그 웃음이 끝나기를 서서 기다렸다. 손이 떨렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 무기를 내린다 — 져 준다.', k:'steady', dc:22, wake:1,
      ok:`무기 끝을 바닥으로 내렸다. 어깨 힘을 뺐다. 싸움 앞에서 처음 해 보는 자세다.<br><br>삐뚤이 칼이 이쪽 어깨를 톡 친다. 스피커가 말한다. 아쉬워요, 다음에 또 도전해요. 탈이 제자리로 걸어가 섰다. 무대 쪽 문은 안 열렸다.<br><br>내린 칼끝에서 손이 이상한 걸 알았다. 내린 칼끝은 어디로든 올라간다. 들고 있던 칼보다 빠르게. 내린 자세도 자세다. 그걸 이제 몸이 안다.`,
      ng:`내리는데 손이 말을 안 듣는다. 내리다 말고 반쯤 다시 든다. 버릇이다.<br><br>삐뚤이가 그 틈을 친다. 스펀지 칼인데 무겁다. 손목이 꺾였다.<br>스피커가 말한다. 아직 끝나지 않았어요. 탈이 한 발 다가선다. 뒷걸음으로 문까지 갔다. 문이 닫히고서야 무기가 아직 손에 있는 걸 봤다.`,
      win:{ exp:22, dream:3, spirit:6 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'교실동 — 물속에서 무거운 무기',
  x:`교실동 복도는 물이 허리까지다. 걸을 때마다 물이 무기를 잡아당긴다.<br><br>
    물속에서 무기는 두 배로 무겁다. 휘두르면 날이 물을 밀다가 멈춘다. 땅 위에서 한 번 칠 동안 여기서는 반 번이다.<br>
    다리 사이로 무엇이 스친다. 물풀이라고 생각하기로 했다. 물풀은 발목을 한 바퀴 돌지 않는다.<br><br>
    교실 안에서 분필 소리가 난다. 또각. 그리고 출석부 넘기는 소리.`,
  o:[
    { l:'① 무기를 바닥에 박고 기대어 선다.', k:'steady', dc:22, wake:1,
      ok:`날을 거꾸로 해서 복도 바닥 타일 틈에 박았다. 자루를 두 손으로 쥐고 몸을 기댔다.<br><br>발목에 감기던 것이 당긴다. 몸이 기운다. 무기가 버틴다. 박힌 쇠는 물이 못 뺀다.<br>한참 당기다 놓았다. 물속에서 아쉬운 듯 거품이 하나 올라왔다.<br><br>무기는 휘두르는 것이었다. 박으면 말뚝이 된다. 손이 벌써 박을 자리를 고르며 걷는다. 한 걸음, 박고. 한 걸음, 박고.`,
      ng:`박으려는데 타일이 단단하다. 날이 미끄러져 옆으로 누웠다.<br><br>그 순간 발목이 당겨졌다. 무릎이 꺾이며 얼굴이 물에 닿았다. 차다. 바닥에 작은 손자국들이 찍혀 있는 게 보였다.<br>일행이 등덜미를 잡아 일으켰다. 입에 물이 들어갔다. 비린 맛이 오래 남는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 발목 쪽 물을 내리찍는다.', k:'break', dc:23,
      doom:{ title:'물 밑의 자루', what:'무기를 쥔 채 물 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`무기를 거꾸로 쥐고 발목 옆 물을 찍었다. 물이 느리다. 날이 반쯤 내려가다 멈춘다.<br><br>멈춘 날을 물속에서 무엇이 쥐었다. 작은 손 여럿이다. 날을, 자루를, 손목을. 꼭 쥔다. 놓지 않는 쥠새가 이쪽과 똑같다.<br>당긴다. 아래로. 타일 깨진 데로 물이 더 깊다. 거기서 출석 부르는 소리가 올라온다.<br><br>무기를 놓으면 된다. 손이 안 펴진다. 고개가 물에 잠긴다.`,
        dieText:`복도 물 위로 거품이 한참 올라왔다. 고르게.<br><br>교실에서 출석부 넘기는 소리가 났다. 이름 하나가 불렸다. 이쪽 이름이다. 대답이 물 밑에서 올라왔다. 네.<br>무기는 끝내 떠오르지 않았다. 쇠는 가라앉는다. 쥐고 있는 사람과 같이.` },
      ok:`찍지 않았다. 찍는 척 날을 물에 넣고 그대로 멈췄다.<br><br>무엇이 날을 쥐려 다가온다. 물이 그쪽만 조금 무겁다. 그 무게 쪽으로 날을 비틀어 올렸다. 물 위로. 차가운 것이 날에서 미끄러져 떨어진다.<br>발목이 풀렸다. 물을 헤쳐 일행 쪽으로 갔다. 등 뒤에서 물이 한참 소용돌이쳤다.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 무력을 쓴다 — 무기를 머리 위로 들고 물을 밀며 간다.', k:'evade', dc:22, cost:{ might:28 },
      ok:`무기를 머리 위로 올렸다. 물에서 빼니 무게가 반으로 준다. 무력을 다리에 몰아 물을 밀었다.<br><br>허벅지로 물을 가르며 걸었다. 발목에 감기던 것이 속도를 못 따라온다. 돌아보지 않았다.<br>복도 끝 계단에 올라섰다. 다리가 후들거린다. 바짓단에 물풀이 감겨 있다. 물풀이 아니다. 머리카락이다. 털어 냈다.`,
      ng:`무력을 몰았는데 물이 이쪽보다 셌다. 물이 아니라 물속 것이.<br><br>한 발이 붙잡혀 넘어졌다. 무기를 든 팔만 물 위에 남고 몸은 잠겼다. 무기를 놓을 수 없어 한 팔로 헤쳤다.<br>겨우 계단을 짚었다. 팔이 떨려서 무기가 몇 번이나 계단을 쳤다. 그 소리가 복도 끝까지 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16, might:-5 } }
  ] },

{ at:'A', t:'쉬는 자리 — 자루에 감긴 머리카락',
  x:`쉬는 틈에 자루에 감은 천을 풀었다. 새로 감으려고.<br><br>
    천 밑 맨 나무에 머리카락이 감겨 있다. 길고 검다. 젖었다. 이쪽 머리카락이 아니다. 일행 누구 것도 아니다.<br>
    손이 쥐는 자리만 골라서 감겼다. 쥘 때마다 같이 쥐어졌을 것이다.<br><br>
    끝을 잡아 당기자 감긴 것이 조인다. 저쪽 끝을 누가 쥐고 있는 것처럼.`,
  o:[
    { l:'① 날로 한 가닥씩 끊는다.', k:'break', dc:22,
      ok:`날을 머리카락 밑에 넣고 한 가닥씩 끊었다. 끊길 때마다 작은 소리가 난다. 숨을 들이켜는 소리 같다.<br><br>마지막 가닥이 끊기자 무기가 가벼워졌다. 손이 놀랄 만큼. 그동안 무엇이 같이 들려 있었다.<br>끊은 머리카락이 바닥에서 저절로 한쪽으로 쓸려 갔다. 어둠 쪽으로. 새 천을 단단히 감았다.`,
      ng:`날이 젖은 머리카락에 미끄러져 엄지를 벴다. 피가 자루에 번진다.<br><br>머리카락이 피를 먹고 조인다. 손가락 사이로 파고든다. 놓으려는데 자루가 손에서 안 떨어진다.<br>한참 손을 흔들었다. 겨우 떨어졌을 때 손바닥에 가는 자국이 패어 있었다. 고리 모양으로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 무력을 쓴다 — 머리카락째 움켜쥐어 짓이긴다.', k:'steady', dc:22, cost:{ might:26 },
      ok:`천을 다시 감지 않았다. 머리카락째 자루를 쥐었다. 무력을 손바닥에 몰았다.<br><br>쥐는 힘이 저쪽 끝까지 간다. 저쪽에서 쥐던 것이 먼저 놓는다. 머리카락이 맥없이 풀려 자루에 붙었다. 그냥 젖은 털이다.<br>그 위로 천을 감았다. 쥐는 손이 이겼다. 손이 원래 하던 일이다.`,
      ng:`쥐었다. 저쪽도 쥐었다. 같은 힘으로. 한 치도 안 진다.<br><br>무력이 빠져나가는 동안 손가락 마디가 하얘졌다. 먼저 놓은 쪽은 이쪽이었다.<br>놓고 나서 보니 손등에 손가락 자국이 넷 있다. 이쪽 손가락이 아니다. 굵기가 다르다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, mind:-16, might:-5 } }
  ] },

{ at:'A1', t:'방청석 — 박수 표지판',
  x:`방청석 위 천장에 표지판이 사슬로 매달려 있다. 박수. 글자에 전구가 박혀 있다.<br><br>
    표지판에 불이 들어오면 빈 의자들이 손뼉을 친다. 아무도 없는데 친다. 늘 같은 길이로.<br>
    불이 켜진 동안 손뼉을 안 치는 사람이 있으면 바람잡이가 마이크로 가리킨다. 저기 친구!<br><br>
    무기를 쥔 손으로 손뼉을 치려면 무기를 내려놔야 한다. 표지판이 깜빡인다. 곧 켜진다.`,
  o:[
    { l:'① 표지판 사슬을 쳐서 떨어뜨린다.', k:'break', dc:23,
      ok:`의자 등받이를 밟고 올라 사슬을 쳤다. 한 번. 고리 하나가 벌어진다. 표지판이 기울다 떨어졌다. 전구가 다 깨졌다.<br><br>박수가 반쯤 나오다 멈췄다. 방청석이 조용하다. 다들 숨을 죽였다.<br>그 조용한 데서 한 사람 몫의 박수가 천천히 난다. 짝. 짝. 어디서 치는지 모른다. 그 소리가 그치기 전에 방청석을 빠져나왔다.`,
      ng:`사슬을 쳤는데 날이 튕긴다. 표지판이 흔들리며 불이 켜진다. 박수. 박수. 박수.<br><br>빈 의자들이 한꺼번에 친다. 아까보다 길게. 의자 위에 선 이쪽만 손이 비었다. 보이지 않는 손들이 이쪽 손목을 잡아 마주 붙인다.<br>짝. 짝. 손바닥이 얼얼할 때까지 쳐졌다. 내려와서도 손이 저절로 몇 번 더 마주쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 무기를 무릎 밑에 끼우고 같이 손뼉을 친다.', k:'hide', dc:22,
      ok:`의자에 앉아 무기를 무릎 밑에 눕혔다. 표지판이 켜지자 손뼉을 쳤다. 빈 의자들과 같이. 같은 길이로.<br><br>굳은살 박인 손바닥은 소리가 크다. 일부러 손을 오므려 작게 쳤다. 다른 박수들처럼 가볍게.<br>바람잡이 사진 얼굴이 방청석을 훑고 지나갔다. 이쪽에서 멈추지 않았다. 표지판이 꺼지자 박수도 꺼졌다. 손바닥이 따끔거렸다.`,
      ng:`손뼉을 쳤다. 굳은살 박인 손바닥이 딱딱 울린다. 다른 박수와 소리가 다르다.<br><br>바람잡이가 마이크를 든다. 박수 소리가 아주 씩씩한 친구가 있네요! 사진 얼굴이 이쪽을 향한다.<br>무릎 밑 무기를 쥐고 고개를 숙였다. 표지판이 꺼질 때까지 그 얼굴이 이쪽을 봤다. 꺼진 뒤에도 한동안 목덜미가 따가웠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A2', t:'기숙사 — 하나 남는 침대',
  x:`기숙사 호실이다. 바닥에 물이 발목까지 고였다. 철제 침대 다리가 물에 잠겼다.<br><br>
    밤 아홉 시 종이 물 밑에서 울린다. 복도로 열쇠 소리가 지나간다. 찰랑, 찰랑. 호실마다 문을 열고 센다.<br>
    빈 침대가 일행 수보다 하나 많다. 시트가 다 반듯하게 접혔다. 누울 사람을 기다린다.<br><br>
    무기를 쥔 사람은 누우면 무기를 몸 옆에 둔다. 철제 침대는 몸 옆자리가 한 뼘이다.`,
  o:[
    { l:'① 눕지 않는다 — 문 옆에 서서 먼저 친다.', k:'break', dc:23,
      doom:{ title:'취침 시간', what:'침대 밑 물속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`문 옆 벽에 붙어 섰다. 무기를 들었다. 열쇠 소리가 문 앞에서 멈춘다. 손잡이가 돈다.<br><br>문이 열리는 순간 쳤다. 문틈에 아무도 없다. 열쇠 꾸러미만 허공에 떠서 찰랑인다.<br>등 뒤에서 물이 일어선다. 침대 밑에서 손들이 나와 발목을, 무릎을, 허리띠를 잡는다. 취침 시간에 서 있는 학생은 눕혀야 한다.<br><br>당겨진다. 침대 밑 어둠으로. 발목 물이 거기서는 깊다.`,
        dieText:`<span style="color:#8fb3bf;">"이상 없음."</span><br><br>열쇠 소리가 다음 호실로 갔다. 침대마다 이불이 사람 모양으로 부풀어 있다.<br>남는 침대는 없다. 문 옆 벽에 무기가 기대 서 있다. 젖은 손자국이 자루를 따라 위로 찍혀 있다.` },
      ok:`문이 열리는 순간 쳤다. 사람 대신 열쇠 꾸러미를. 꾸러미가 물에 떨어져 가라앉는다.<br><br>복도에서 무엇이 멈춘다. 열쇠가 없으면 셀 수가 없다. 한참 물 위를 더듬는 소리가 나다가 멀어졌다. 다른 열쇠를 가지러 가는 걸음이다.<br>이 호실은 세어지지 않았다. 세어지지 않은 방에서 아침까지 서서 버텼다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 무기를 이불 속에 안고 침대 가장자리에 눕는다.', k:'steady', dc:22,
      ok:`무기를 이불 속에 넣고 안았다. 날이 침대 바깥쪽을 향하게. 몸과 물 사이에 쇠를 뒀다.<br><br>문이 열리고 센다. 하나, 둘. 침대 밑에서 손이 올라와 매트리스 가장자리를 더듬는다. 손끝이 날에 닿았다. 멈춘다. 천천히 물러간다.<br>세는 소리가 이쪽을 지나갔다. 아침까지 날 쪽으로 몸을 붙이고 누워 있었다. 거의 못 잤다.`,
      ng:`가장자리가 좁다. 무기를 안자 몸이 침대 밖으로 반쯤 나왔다.<br><br>손이 올라와 날이 아니라 팔꿈치를 잡는다. 차고 작다. 당긴다. 이불을 움켜쥐고 버텼다.<br>세는 소리가 이쪽 침대에서 오래 멈췄다. 손이 놓은 건 종이 그친 뒤였다. 팔꿈치가 퍼렇다. 손가락 넷 자국.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 남는 침대에 무기를 눕히고 이불을 덮는다.', k:'luck', dc:22,
      ok:`남는 침대에 무기를 눕혔다. 베개에 자루 끝을 얹고 이불을 덮었다. 사람 모양은 아니다. 길다.<br><br>문이 열리고 센다. 침대마다 하나씩. 무기를 눕힌 침대에서 대답이 났다. <span style="color:#8fb3bf;">"네."</span> 이쪽 목소리였다.<br>아침에 이불을 걷었다. 무기가 차다. 자루 천에 실로 이름이 수놓여 있다. 이쪽 이름이다. 학년 반 칸은 비었다.`,
      ng:`눕혔는데 세는 손이 무기를 안 세고 지나간다. 사람이 아니다.<br><br>세는 소리가 멈춘다. 하나가 모자란다. 물이 출렁인다. 침대 밑에서 손들이 나와 남는 침대의 이불을 걷는다. 무기를 물속으로 끌어 내린다.<br>뛰어들어 자루를 잡아 빼냈다. 손등에 손톱자국이 줄줄이 났다. 그 밤은 아무도 눕지 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'계단 — 하나 더 많은 발소리',
  x:`계단을 내려간다. 일행이 한 줄이다. 발소리를 세는 건 맨 뒤의 일이다.<br><br>
    다섯 사람이면 발소리가 다섯 박자다. 지금은 여섯 박자다. 하나가 사이에 끼었다. 넷째와 다섯째 사이.<br>
    돌아보면 아무도 없다. 다시 걸으면 여섯 박자다.<br><br>
    전사는 박자를 안다. 휘두르는 것도 박자다.`,
  o:[
    { l:'① 끼어든 박자에 맞춰 친다.', k:'break', dc:23, wake:1,
      ok:`세었다. 하나, 둘, 셋, 넷, 그리고 그 사이. 다음 바퀴에 그 사이로 무기를 넣었다. 보지 않고.<br><br>무엇이 맞았다. 계단 난간이 울린다. 발소리가 다섯으로 돌아왔다. 아래쪽 어둠에서 무엇이 굴러떨어지는 소리가 오래 났다.<br><br>눈으로 치는 줄 알았다. 귀로 쳤다. 박자와 박자 사이에 날을 넣는 법을 손이 알았다. 보이지 않는 것에도 틈은 있다. 틈은 박자로 온다.`,
      ng:`그 사이를 노렸는데 박자가 바뀌었다. 끼어든 것이 이쪽이 세는 걸 알았다.<br><br>날이 앞사람 등 바로 뒤를 지났다. 한 뼘 차이다. 앞사람이 얼어붙었다.<br>그때부터 발소리가 일곱이다. 둘이 끼었다. 계단 끝까지 아무도 말하지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 모두 세우고 귀를 연다.', k:'sense', dc:22,
      ok:`앞사람 어깨를 잡아 세웠다. 다들 섰다. 발소리가 멈췄다. 하나만 안 멈췄다.<br><br>한 걸음, 또 한 걸음. 이쪽 줄 사이에서 빠져나가 아래로 내려간다. 아무것도 안 보인다. 계단만 운다.<br>그 소리가 멀어진 뒤에 걸었다. 다섯 박자다. 다들 몇 번이고 뒤를 돌아봤다.`,
      ng:`세웠다. 다 멈췄다. 여섯째도 멈췄다. 숨소리까지.<br><br>그대로 한참 서 있었다. 누가 먼저 걸어야 한다. 아무도 못 걷는다.<br>결국 이쪽이 먼저 걸었다. 바로 뒤에서 한 걸음이 따라왔다. 이쪽이 맨 뒤인데.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'복도 끝 거울 — 먼저 든 무기',
  x:`복도 끝 벽에 큰 거울이 붙어 있다. 일행이 비친다. 이쪽도 비친다.<br><br>
    거울 속 이쪽이 무기를 들고 있다. 치기 직전의 자세로. 이쪽 무기는 아직 내려가 있다.<br>
    거울 속 날끝이 겨누는 데는 이쪽이 아니다. 이쪽 바로 뒤에 선 동료의 목이다.<br><br>
    동료는 거울을 안 본다. 지도를 보고 있다.`,
  o:[
    { l:'① 거울을 친다.', k:'break', dc:22,
      ok:`거울 속 날이 움직이기 전에 쳤다. 유리가 한가운데서 갈라진다. 거울 속 이쪽이 조각조각 나뉜다.<br><br>조각마다 이쪽이 무기를 들고 있다. 그러다 하나씩 내린다. 마지막 조각까지 다 내렸다. 그제야 숨을 쉬었다.<br>동료가 지도에서 고개를 든다. 무슨 소리냐고. 깨진 걸 보고 아무 말도 안 했다.`,
      ng:`쳤는데 유리가 안 깨진다. 날이 튕겨 나왔다.<br><br>그 순간 거울 속 날이 내려온다. 거울 속 동료 목에. 이쪽 어깨가 화끈하다. 셔츠가 베였다. 거울 속에서 친 자리가 이쪽 몸에 났다.<br>동료를 끌어당겨 거울에서 떼었다. 어깨에서 피가 흐른다. 거울 속 이쪽은 아무 데도 안 다쳤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, spirit:-20 } },
    { l:'② 날끝이 가는 길을 읽고 그 사이에 선다.', k:'gaze', dc:22,
      ok:`거울 속 날끝을 봤다. 동료 목을 겨눈다. 그 사이로 몸을 옮겼다. 거울 속에서 날끝이 이쪽 가슴에 닿는다. 거기서 멈췄다.<br><br>거울 속 이쪽이 이쪽을 본다. 제 날끝을 막고 선 사람을. 무기가 천천히 내려간다.<br>동료를 데리고 거울을 지났다. 등 뒤로 무기 내려놓는 소리가 났다. 쇠가 유리 안쪽에 닿는 소리.`,
      ng:`사이로 들어서는데 거울 속 날끝도 따라 움직인다. 동료 목에서 이쪽 눈으로.<br><br>눈앞이 하얘졌다. 한참 아무것도 안 보였다. 동료가 이쪽 팔을 잡고 끌어냈다.<br>눈은 멀쩡하다. 다만 한쪽 눈에 계속 거울이 비친다. 깜빡이면 사라진다. 다시 뜨면 있다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-26 } },
    { l:'③ 무력을 쓴다 — 거울 속과 똑같이 들고 마주 겨눈다.', k:'steady', dc:23, cost:{ might:27 },
      ok:`무력을 끌어올려 무기를 들었다. 거울 속 자세 그대로. 발 너비, 팔꿈치, 날끝. 이쪽 날끝도 거울을 겨눴다.<br><br>둘이 서로 겨눈다. 한 치도 안 움직였다. 팔이 떨려도 안 내렸다. 먼저 내리는 쪽이 진다.<br>거울 속 이쪽이 먼저 떨었다. 무기가 내려간다. 거울 속 얼굴이 처음으로 이쪽과 다르게 지쳐 보였다.`,
      ng:`같은 자세를 잡는 순간 거울 속 이쪽이 자세를 바꿨다. 이쪽이 아는 어떤 자세보다 빠르게.<br><br>무력이 팔에서 엉켰다. 무기가 손에서 돌았다. 놓치지는 않았다. 손목이 나갔다.<br>거울 속 날끝은 여전히 동료를 겨눈다. 동료를 거울 밖으로 밀어낼 때까지 그 날끝이 따라왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18, might:-5 } }
  ] },

{ at:'A1', t:'분장실 — 출연 십 분 전',
  x:`분장실 전구 거울 앞에 의자가 하나 비어 있다. 전구가 전부 켜졌다. 거울 밑 선반에 분첩과 붓이 놓였다.<br><br>
    붓이 저 혼자 분통에 몸을 담근다. 꺼내서 털고, 다시 담근다. 앉을 사람을 기다리며.<br>
    의자 등받이에 종이가 붙어 있다. 오늘의 친구 — 분장. 출연 십 분 전.<br><br>
    스피커가 센다. 십 분이 남았다고. 의자가 아주 조금 이쪽으로 돌았다.`,
  o:[
    { l:'① 의자를 부순다.', k:'break', dc:23,
      doom:{ title:'분장', what:'분첩이 얼굴을 덮어 숨이 막힙니다', dc:18, sec:45,
        text:`의자를 내리쳤다. 다리가 부러지고 등받이가 날아갔다. 분통이 엎어진다. 하얀 가루가 방 안을 채운다.<br><br>가루가 얼굴에 붙는다. 숨을 쉬면 가루가 들어온다. 분첩들이 떠올라 이쪽 얼굴로 온다. 하나가 아니다. 선반에 있던 것 전부.<br>분첩이 코와 입을 덮는다. 꼭꼭 누른다. 화장을 고르게 먹이듯이. 숨이 하얗게 막힌다.<br><br>붓 하나가 입꼬리에서 귀 쪽으로 천천히 선을 긋는다.`,
        dieText:`전구 거울에 얼굴 하나가 비친다. 하얗다. 입꼬리가 귀까지 그려졌다. 고르게.<br><br>스피커가 말했다. 출연 준비 끝.<br>부서진 의자 옆에 무기가 놓여 있다. 무기를 들고 무대에 나가는 친구는 없으니까.` },
      ok:`의자를 내리쳤다. 부서진다. 가루가 일기 전에 소매로 입과 코를 막고 문 쪽으로 물러났다.<br><br>분첩들이 떠올랐다가 앉을 데를 잃고 바닥에 떨어진다. 붓이 분통 가장자리에서 한참 떨다가 쓰러졌다.<br>스피커가 센다. 십 분. 십 분. 십 분. 넘어가지 않는다. 앉을 의자가 없으면 시간도 안 간다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 앉는다 — 눈을 감고 무기를 무릎에 가로로 놓는다.', k:'steady', dc:22,
      ok:`앉았다. 무기를 무릎에 가로로 놓고 두 손으로 쥐었다. 눈을 감았다.<br><br>붓이 볼에 닿는다. 차다. 분이 발린다. 붓이 내려가다 무기에 닿았다. 멈춘다. 한참 쇠를 두드린다. 툭, 툭.<br>붓이 물러갔다. 눈을 떴다. 거울 속 얼굴은 반만 하얗다. 무기를 든 친구는 출연할 수 없다. 큐시트 어디에도 그런 친구는 없다.`,
      ng:`눈을 감는데 무릎 위 무기가 미끄러진다. 붓이 손등을 쓸어 손을 펴게 만든다. 간지럽게.<br><br>손이 펴졌다. 무기가 바닥에 떨어졌다. 그사이 붓이 입꼬리에 선을 긋는다. 놀라서 일어섰다.<br>거울 속 입꼬리에 하얀 선이 한 줄 남았다. 문질러도 안 지워진다. 웃는 쪽으로 반 치 올라가 있다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A2', t:'수영장 — 발목에 감긴 레인 줄',
  x:`수영장 물 위로 공기가 한 줄 남았다. 레인 줄이 수면 바로 밑에 떠 있다. 플라스틱 부표가 줄줄이 꿰어졌다.<br><br>
    동료 하나가 레인 줄을 건너다 발목이 감겼다. 줄이 저절로 감긴다. 한 바퀴, 또 한 바퀴.<br>
    줄 양끝은 물속 벽에 박혀 있다. 그런데 줄이 팽팽해진다. 누가 반대쪽에서 감고 있다.<br><br>
    동료 머리가 수면을 들락거린다.`,
  o:[
    { l:'① 레인 줄을 끊는다.', k:'break', dc:23,
      ok:`물속으로 날을 넣어 줄을 그었다. 물이 느리다. 두 번, 세 번. 네 번째에 줄이 끊어졌다.<br><br>끊어진 줄이 반대쪽으로 빠르게 빨려 간다. 부표들이 물 위를 줄줄이 미끄러져 사라진다. 끝에서 무엇이 아쉬운 듯 물을 한 번 친다.<br>동료가 숨을 몰아쉬며 떠올랐다. 발목에 부표 자국이 동그랗게 남았다.`,
      ng:`날이 물을 못 이긴다. 줄을 긁기만 한다. 그사이 줄이 날을 감는다. 팔까지.<br><br>동료와 같이 줄에 감겼다. 당겨지는 줄을 맨손으로 붙잡고 버텼다. 다른 일행이 줄을 잘랐다. 둘이 같이 떠올랐다.<br>팔에 줄 자국이 감겨 있다. 부표 하나하나에 숫자가 쓰여 있다. 출석 번호다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-22 } },
    { l:'② 날 쪽을 쥐고 자루를 내민다.', k:'bond', dc:22, wake:1,
      ok:`무기를 거꾸로 쥐었다. 날 바로 밑을. 자루를 동료 쪽으로 내밀었다. 잡아.<br><br>동료가 자루를 잡는다. 당겼다. 줄이 반대로 당긴다. 날 밑을 쥔 손이 베인다. 놓지 않았다. 줄이 먼저 졌다. 감긴 데가 풀리며 동료가 이쪽으로 왔다.<br><br>무기는 남을 치려고 쥐는 것이었다. 거꾸로 쥐면 남을 잡는 손잡이가 된다. 손이 그 쥠을 알았다. 자루를 내미는 쥠. 베인 손바닥이 그 자리를 기억한다.`,
      ng:`자루를 내밀었는데 동료 손이 미끄러진다. 젖은 나무는 잘 안 잡힌다.<br><br>동료가 다시 잡으려 손을 뻗는다. 그 손을 물속에서 다른 손이 먼저 잡았다. 작은 손이다.<br>뛰어들어 동료 허리를 안고 끌어올렸다. 둘 다 물을 먹었다. 동료 손에 작은 손이 쥐여 준 것이 있다. 수영 모자다. 이름이 쓰였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'③ 무력을 쓴다 — 물에 들어가 줄째 들어 올린다.', k:'steady', dc:23, cost:{ might:30 },
      ok:`물에 뛰어들어 레인 줄 밑에 어깨를 넣었다. 무력을 등에 몰았다. 들어 올렸다.<br><br>줄이 물 위로 나온다. 부표가 물을 흘리며 들린다. 물 밖에서는 줄이 감기지 못한다. 동료가 감긴 발목을 풀어 냈다.<br>줄을 놓았다. 줄이 물속으로 들어가자마자 다시 팽팽해진다. 아무도 없는 레인을 감는다.`,
      ng:`어깨를 넣었는데 줄이 무겁다. 줄이 아니라 줄에 매달린 것이.<br><br>무력을 다 써도 반만 들렸다. 들린 반쪽에서 물이 아니라 손들이 흘러내린다. 놓쳤다. 줄이 이쪽 어깨를 누르며 가라앉는다.<br>일행이 끌어올렸다. 어깨가 제자리에 없다. 맞춰 넣는 동안 숨을 열 번 참았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-16, might:-5 } }
  ] },

{ at:'A', t:'문 — 안에서 따라 두드리는 문',
  x:`닫힌 문 앞이다. 손잡이가 없다. 무기 자루로 두드려 봤다. 셋.<br><br>
    안에서 두드린다. 셋. 같은 세기로. 같은 간격으로.<br>
    넷을 두드렸다. 안에서 넷. 다섯. 다섯. 그러다 안에서 먼저 두드린다. 여섯.<br><br>
    이쪽이 일곱을 두드리면 문을 열어 줄 것 같다. 그런 소리다.`,
  o:[
    { l:'① 안에서 두드리는 바로 그때 문을 친다.', k:'break', dc:23, wake:1,
      ok:`안에서 일곱째를 두드리려 할 때를 기다렸다. 그 순간에 맞춰 문을 쳤다. 이쪽 힘과 저쪽 힘이 한 점에서 만났다.<br><br>문이 안쪽으로 터졌다. 두드리던 것이 같이 날아갔다. 안은 비었다. 문짝 안쪽에 주먹 자국이 수백 개 찍혀 있다. 크기가 다 다르다.<br><br>혼자 치는 힘보다 맞받아 치는 힘이 크다. 저쪽이 미는 때를 이쪽 손이 알았다. 그때에 넣으면 저쪽 힘까지 이쪽 것이 된다.`,
      ng:`맞추려다 반 박자 늦었다. 저쪽이 먼저 두드리고 이쪽이 문을 쳤다. 문이 안 열렸다. 저쪽에서 손바닥을 문에 대는 소리가 났다.<br><br>이쪽 손바닥에도 무엇이 닿았다. 문을 사이에 두고. 차다. 문이 얇아진 것 같다. 손을 떼는 데 한참 걸렸다.<br>떼고 보니 손바닥이 하얗다. 핏기가 다 빠졌다. 피가 돌아오는 데 반나절이 걸렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 두드리지 않고 문에 등을 대고 기다린다.', k:'steady', dc:22,
      ok:`일곱째를 두드리지 않았다. 문에 등을 대고 섰다.<br><br>안에서 여섯을 다시 두드린다. 또 여섯. 이쪽 차례를 기다린다. 한참 뒤에 두드림이 그쳤다. 문 밑 틈으로 바람이 한 번 나왔다. 한숨 같았다.<br>문은 끝내 안 열렸다. 다른 길로 돌아갔다. 멀었다. 등이 문 모양으로 차다.`,
      ng:`기다리는데 등 뒤 문에서 두드림이 난다. 등뼈 하나하나를. 하나, 둘, 셋, 넷.<br><br>일곱째가 오기 전에 문에서 떨어졌다. 등이 저렸다. 한동안 등에서 두드림이 계속 느껴졌다.<br>잠들 때마다 등뼈에서 여섯까지 세어졌다. 일곱은 안 왔다. 아직은.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A1', t:'스튜디오 — 빨간 불이 켜진 카메라',
  x:`스튜디오에 카메라가 셋이다. 바퀴 달린 받침대 위에 섰다. 맨 위에 빨간 불이 있다. 지금 찍는 카메라에만 켜진다.<br><br>
    빨간 불이 켜진 카메라 앞에 선 사람은 방송에 나간다. 모니터에 얼굴이 뜬다. 그러면 세트 쪽에서 하얀 장갑들이 손짓한다. 이리 와.<br>
    가운데 카메라에 불이 들어왔다. 렌즈가 이쪽을 향한다. 받침대 바퀴가 아주 조금 굴렀다.<br><br>
    스피커가 센다. 오 분.`,
  o:[
    { l:'① 카메라를 부순다.', k:'break', dc:23,
      doom:{ title:'오늘의 친구', what:'하얀 장갑들에게 세트로 끌려 나갑니다', dc:18, sec:45,
        text:`달려가 가운데 카메라를 내리쳤다. 렌즈가 깨진다. 빨간 불이 꺼진다.<br><br>옆 카메라에 빨간 불이 켜진다. 처음부터 이쪽을 향해 있었다. 모니터에 이쪽 얼굴이 뜬다. 웃고 있지 않은데 화면 속 얼굴은 웃는다.<br>세트 쪽에서 장갑들이 온다. 손가락 넷짜리. 소매를 잡고 손목을 잡고 허리를 감는다. 박수가 쏟아진다.<br><br>발이 세트 쪽으로 끌린다. 동산 그림 앞으로. 거기에 빈자리가 하나 표시돼 있다.`,
        dieText:`모니터에 방글 동산이 나온다. 해님 얼굴이 웃는다. 그 옆에 오늘의 친구가 앉아 있다.<br><br>친구는 무릎에 손을 모으고 있다. 손가락이 넷이다. 웃는다. 박수가 길게 나온다. 늘 같은 길이로.<br>깨진 카메라 앞 바닥에 무기가 놓여 있다. 그 위로 바퀴 자국이 지나갔다.` },
      ok:`내리치기 전에 옆 카메라를 봤다. 렌즈가 이쪽을 향하려 돈다. 둘을 차례로 쳤다. 가운데 것, 오른쪽 것. 숨 한 번에.<br><br>빨간 불이 두 개 꺼졌다. 남은 카메라가 불을 켜려다 깜빡인다. 모니터에 아무도 안 나온다. 빈 무대만.<br>장갑들이 세트 앞에서 멈춰 섰다. 손짓할 사람이 화면에 없다. 스피커가 센다. 오 분. 그대로 오 분.`,
      win:{ exp:23, dream:3 } },
    { l:'② 카메라 셋이 다 못 보는 데로 숨는다.', k:'hide', dc:22,
      ok:`카메라 셋의 렌즈 방향을 봤다. 셋이 다 겹치지 않는 데가 있다. 크레인 기둥 뒤. 거기로 숨었다.<br><br>빨간 불이 이 카메라 저 카메라로 옮겨 다닌다. 모니터에 빈 바닥만 나온다. 장갑들이 손짓할 데를 못 찾는다.<br>숨이 길었다. 무기가 기둥에 닿지 않게 손으로 날을 감쌌다. 손바닥이 차다.`,
      ng:`기둥 뒤로 들어갔는데 무기 끝이 밖으로 삐져나왔다. 너무 길다.<br><br>모니터에 날끝이 나온다. 빨간 불이 켜진다. 장갑들이 그 날끝을 향해 손짓한다. 날을 잡아당긴다.<br>무기를 끌어안고 버텼다. 장갑들이 놓아준 건 다른 카메라 불이 켜진 뒤였다. 날에 장갑 실밥이 걸려 있다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-20 } },
    { l:'③ 무기를 세워 렌즈 앞을 막는다.', k:'steady', dc:22, wake:1,
      ok:`무기를 몸 앞에 세웠다. 날의 넓은 면을 렌즈 쪽으로. 얼굴이 날 뒤에 들어간다.<br><br>모니터에 쇠만 나온다. 번들거리는 날. 그 날에 스튜디오 조명이 비친다. 얼굴은 없다. 장갑들이 손을 들었다가 내린다. 쇠한테는 손짓하지 않는다.<br><br>막는 것은 칼을 막는 일인 줄 알았다. 눈도 막을 수 있다. 무기를 몸 앞에 세우는 자세 하나에 쓰임이 하나 더 붙었다. 팔이 그 높이를 기억한다.`,
      ng:`세웠는데 날에 이쪽 얼굴이 비쳤다. 날이 거울이다. 모니터에 날이 나오고 날 속에 얼굴이 나온다.<br><br>장갑들이 손짓한다. 이리 와. 발이 반 걸음 저절로 나갔다. 다른 일행이 뒤에서 허리띠를 잡았다.<br>날을 옆으로 눕혀 겨우 얼굴을 지웠다. 그 반 걸음을 돌아오는 데 온몸에 땀이 났다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'식당 — 이름 붙은 식판',
  x:`식당은 물이 가슴까지다. 긴 식탁이 물속에 줄지어 있다. 식탁 위로만 물이 얕다.<br><br>
    식판이 차려져 있다. 밥, 국, 반찬 둘. 김이 오른다. 물 위로. 식판마다 이름표가 꽂혔다.<br>
    하나에 이쪽 이름이 있다. 일행 이름도 있다. 자리가 정해졌다.<br><br>
    배가 고프다. 무기를 휘두르는 몸은 금방 빈다.`,
  o:[
    { l:'① 이쪽 이름 식판을 엎는다.', k:'break', dc:22,
      ok:`이름표 꽂힌 식판을 무기 자루로 쳐서 엎었다. 밥이 물에 흩어진다. 김이 꺼진다. 냄새가 사라지자 배고픔이 조금 덜하다.<br><br>엎은 식판 밑에 깡통 하나가 붙어 있다. 기름종이로 싸 두었다. 누가 숨겨 둔 것이다. 열어 보니 말린 고기다. 물에 젖지 않았다.<br>일행 식판도 차례로 엎었다. 엎을 때마다 물 밑에서 숟가락 내려놓는 소리가 났다.`,
      ng:`식판을 쳤는데 안 엎어진다. 식탁에 붙었다. 국이 출렁여 이쪽 손등에 튄다. 뜨겁지 않다. 차다.<br><br>튄 국 냄새가 손에서 안 떠난다. 배가 더 고프다. 손등을 핥고 싶어진다. 이를 악물고 손을 물에 담갔다.<br>물속에서 누가 이쪽 손을 쥐고 식판 쪽으로 당겼다. 뿌리쳤다. 손등에 숟가락 모양 멍이 들었다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-22, mind:-20 } },
    { l:'② 무력을 쓴다 — 물 위로 나온 저장고 문을 비틀어 연다.', k:'break', dc:23, cost:{ might:26 },
      ok:`식당 벽 높은 데에 저장고 문이 있다. 물 위로 반쯤 나왔다. 걸쇠가 녹슬어 붙었다. 무력을 손목에 몰아 걸쇠째 비틀었다.<br><br>문이 열렸다. 안이 마르다. 선반 위에 소금 단지가 있다. 굳어서 덩이가 됐다. 물이 여기까지는 못 왔다.<br>소금 덩이를 품에 넣었다. 남의 이름이 붙은 밥보다 이게 낫다.`,
      ng:`걸쇠를 비트는 사이 문이 안쪽에서 밀렸다. 열리는 게 아니라 터졌다. 안에 물이 차 있었다.<br><br>물이 한꺼번에 쏟아져 이쪽을 식탁 위로 밀어붙였다. 식판들이 엎어진다. 김이 오르는 밥이 얼굴에 붙는다.<br>뱉었다. 몇 알은 넘어갔다. 그 뒤로 한동안 출석 부르는 소리가 더 가깝게 들렸다.`,
      win:{ exp:20, dream:2, item:'소금 덩이' }, lose:{ hp:-28, spirit:-20, might:-5 } }
  ] },

{ at:'A', t:'잠자리 — 손가락을 펴는 손',
  x:`불침번이 끝나고 누웠다. 무기를 쥔 채로.<br><br>
    반쯤 잠들었을 때 무엇이 손가락을 하나씩 편다. 새끼손가락부터. 아주 살살. 잠든 아이 손에서 장난감을 빼 가듯이.<br>
    새끼손가락이 펴졌다. 약지를 만진다. 손이 차다. 아이 손만 하다.<br><br>
    눈을 뜨면 안 될 것 같다. 뜨면 그것도 안다.`,
  o:[
    { l:'① 눈을 감은 채 손가락마다 따로 힘을 준다.', k:'steady', dc:23, wake:1,
      ok:`펴진 새끼손가락을 다시 접었다. 약지에 힘을 줬다. 그것이 중지로 옮겨 가면 중지에. 하나씩 따로.<br><br>한 손가락이 펴져도 나머지가 쥔다. 다섯이 따로 쥔다. 작은 손이 오래 애쓰다가 그만뒀다. 한숨 같은 바람이 귀를 스쳤다.<br><br>쥐는 건 손 전체로 하는 줄 알았다. 손가락은 하나씩 따로 쥘 수 있다. 하나를 빼앗겨도 넷이 남는다. 아침에 무기를 쥐는데 손 모양이 달라져 있었다.`,
      ng:`약지에 힘을 줬는데 그것이 엄지를 잡았다. 엄지가 펴지면 다 펴진다. 그것도 안다.<br><br>엄지가 펴졌다. 무기가 손에서 빠져나간다. 천천히. 바닥에 끌리며 멀어진다. 눈을 떴다. 무기가 문간에 있다. 아무도 없다.<br>무기를 가지러 문간까지 걸어가는 열 걸음이 이 방에서 제일 길었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 눈을 뜨고 그 손을 친다.', k:'break', dc:22,
      ok:`눈을 뜨며 자루로 그 손을 쳤다. 손이 움찔 물러난다. 손의 주인이 보였다.<br><br>일행 하나다. 눈을 감고 있다. 잠든 채로 이쪽 손가락을 펴고 있었다. 입술이 움직인다. 줘. 줘.<br>어깨를 흔들어 깨웠다. 동료는 아무것도 기억 못 했다. 손이 차갑다며 겨드랑이에 끼웠다. 남은 밤 둘 다 안 잤다.`,
      ng:`손을 쳤다. 아무것도 안 맞았다. 자루가 바닥만 때렸다. 소리에 다들 깼다.<br><br>손가락에는 아직 차가운 손자국이 남았다. 넷.<br>다시 누웠는데 이번엔 반대쪽 손가락이 펴지기 시작한다. 새끼손가락부터. 남은 밤 내내 앉아서 무기를 쥐고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 무력을 쓴다 — 무기를 바닥에 박아 두고 손목에 묶는다.', k:'fix', dc:22, cost:{ might:25 },
      ok:`일어나 무기를 바닥 틈에 깊이 박았다. 무력을 실어서. 자루에 감은 천을 풀어 손목에 묶었다.<br><br>다시 누웠다. 손가락이 펴져도 무기는 바닥에 있다. 손목은 묶였다. 작은 손이 한참 천을 만지작거리다 갔다.<br>아침에 보니 무기 박힌 자리 둘레에 작은 손톱자국이 빙 둘러 나 있다. 밤새 파 보려고 했다.`,
      ng:`박는데 바닥이 무르다. 무기가 너무 깊이 들어갔다. 반쯤 잠겼다. 빼려니 안 빠진다.<br><br>무기를 붙잡고 당기는 사이 바닥 밑에서 누가 같이 당긴다. 아래로.<br>무력을 다 써서 겨우 뽑았다. 날 끝에 젖은 흙과 가는 머리끈 하나가 걸려 나왔다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-24, mind:-16, might:-5 } }
  ] },

{ at:'A', t:'통로 — 끌려가는 동료',
  x:`앞에서 동료가 넘어졌다. 넘어진 게 아니다. 발목이 어둠 쪽으로 당겨졌다.<br><br>
    동료가 바닥을 손톱으로 긁으며 미끄러진다. 소리를 못 지른다. 입이 열려 있는데 소리가 안 나온다.<br>
    당기는 것은 안 보인다. 어둠만 길게 이어진다. 끝이 어디인지 모른다.<br><br>
    무기를 든 손과 빈손. 어느 손을 먼저 뻗을지 몸이 정해야 한다.`,
  o:[
    { l:'① 빈손으로 동료 손목을 잡고 버틴다.', k:'bond', dc:23,
      doom:{ title:'같이 끌려간 손', what:'동료와 함께 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`몸을 던져 동료 손목을 잡았다. 버텼다. 발뒤꿈치로 바닥을 밀었다.<br><br>당기는 힘이 늘어난다. 둘 몫을 당긴다. 이쪽 발이 미끄러진다. 무기를 쥔 손이 바닥을 긁는다. 걸리는 데가 없다.<br>둘이 같이 끌려간다. 동료 눈이 이쪽을 본다. 놓으라는 눈이다. 손이 안 펴진다. 놓는 법을 이 손은 모른다.<br><br>어둠이 발목을 넘어 무릎을 넘는다. 차다.`,
        dieText:`뒤따라온 일행이 불을 들고 통로 끝까지 갔다.<br><br>통로는 막다른 벽이다. 벽에 손톱자국이 두 줄 나 있다. 바닥에서 위로.<br>벽 밑에 무기가 하나 떨어져 있다. 쥔 자리에 다른 손 자국이 겹쳐 있었다.` },
      ok:`동료 손목을 잡는 동시에 무기를 바닥에 내리찍었다. 날이 돌 틈에 박혔다. 그 자루를 쥐고 버텼다.<br><br>당기는 힘이 둘을 끌다가 박힌 쇠에서 멈춘다. 한참 팽팽하다. 동료 발목에서 무엇이 미끄러지듯 놓았다.<br>동료를 끌어안고 뒤로 굴렀다. 동료 발목에 손자국이 둘. 하나는 크고 하나는 작다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 무력을 쓴다 — 날끝을 바닥 틈에 걸고 동료를 끌어당긴다.', k:'break', dc:22, cost:{ might:30 },
      ok:`날끝을 바닥 돌 틈에 걸었다. 무력을 팔에 몰았다. 한 손은 자루, 한 손은 동료 허리띠.<br><br>당겼다. 저쪽도 당긴다. 무기가 사이에서 운다. 쇠가 휘는 소리. 무력을 한 번 더 끌어올렸다. 동료가 이쪽으로 왔다.<br>어둠 속에서 무엇이 손을 놓친 소리를 냈다. 혀 차는 소리 같았다. 날이 조금 휘었다. 쓸 만큼만.`,
      ng:`날끝이 틈에서 빠졌다. 그 반동에 동료가 한 길 더 끌려간다.<br><br>뛰어가 다리를 붙들었다. 무력이 다 빠진 팔로. 겨우 버텼다. 당기던 것이 놓은 건 일행이 다 같이 붙은 다음이었다.<br>동료 발목이 퍼렇다. 이쪽 팔도 떨려서 한동안 무기를 못 들었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18, might:-5 } },
    { l:'③ 어둠 속 당기는 쪽을 친다.', k:'break', dc:23,
      ok:`동료 발목에서 어둠으로 이어진 데를 겨눴다. 당기는 것은 안 보인다. 동료 바짓단이 팽팽하게 당겨진 방향은 보인다. 그 끝을 쳤다.<br><br>날이 무엇에 걸렸다. 무르다. 젖은 천 같다. 당기던 힘이 끊겼다. 동료가 제자리에 엎어졌다.<br>날을 보니 끝에 긴 머리카락 한 움큼이 감겨 있다. 털어 내도 한 가닥이 계속 남는다.`,
      ng:`쳤는데 날이 허공을 지났다. 당기는 것은 거기 없다. 동료 발목 바로 위에서 당기고 있다.<br><br>그사이 동료가 한 길 더 끌려갔다. 다들 달려들어 동료를 붙잡았다. 겨우 멈췄다.<br>동료가 일어서며 이쪽을 봤다. 날이 자기 발목 한 치 옆을 지나갔다고. 그 말을 할 때 동료 목소리가 떨렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다',
  x:`놀이 세트에 공 바다가 있다. 울타리 안에 알록달록한 공이 허리 높이로 찼다. 건너편 출구로 가려면 지나야 한다.<br><br>
    공들이 가끔 움직인다. 바닥 쪽에서 무엇이 지나가는 것처럼. 한 줄로 공이 들썩인다.<br>
    공 바다 한가운데서 아이 목소리가 난다. 찾아봐. 나 여기 있다.<br><br>
    울타리에 그림판이 걸려 있다. 공 바다에서 친구를 찾아요! 찾은 친구는 같이 놀아요.`,
  o:[
    { l:'① 무기로 공을 헤쳐 바닥을 짚으며 간다.', k:'break', dc:22,
      ok:`무기를 앞으로 내밀어 공을 쓸어냈다. 바닥이 보이면 한 걸음, 쓸어내고 한 걸음.<br><br>공이 무기 양옆으로 갈라진다. 갈라진 바닥에 작은 손자국이 찍혀 있다. 공 밑에서 누가 줄곧 기어 다녔다.<br>찾아봐. 목소리가 무기 끝 바로 앞에서 난다. 찾지 않았다. 출구 울타리를 넘었다. 뒤에서 공들이 한꺼번에 가라앉는 소리가 났다.`,
      ng:`쓸어내는데 무기가 공 밑에서 무엇에 걸린다. 무겁다. 끌어올리니 공들 사이로 장갑 손이 하나 딸려 올라온다. 손가락이 넷이다. 무기를 쥐고 있다.<br><br>찾았다! 목소리가 기뻐한다. 장갑이 당긴다. 무기를 비틀어 겨우 빼냈다.<br>공 바다 밖으로 굴러 나왔다. 손목에 공 하나가 붙어 있다. 떼어 보니 공 안쪽에 이쪽 이름이 적혀 있다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 울타리 위에 무기를 가로로 걸고 매달려 건넌다.', k:'steady', dc:22, wake:1,
      ok:`무기를 울타리 양쪽에 가로질러 걸었다. 자루 끝이 한쪽, 날 끝이 다른 쪽. 거기 매달려 손으로 옮겨 갔다. 발은 공에 안 닿게.<br><br>밑에서 공들이 들썩인다. 손이 공 위로 올라와 허공을 더듬는다. 발이 없다. 찾을 게 없다.<br><br>무기가 다리가 됐다. 들고 싸우던 것이 걸치면 건너는 것이 된다. 무기 길이를 몸이 다시 쟀다. 휘두르는 길이가 아니라 걸치는 길이로.`,
      ng:`무기를 걸었는데 울타리 폭이 무기보다 한 뼘 넓다. 날 끝이 미끄러졌다.<br><br>공 바다에 떨어졌다. 공이 목까지 찬다. 공 밑에서 손들이 다리를 잡는다. 찾았다, 찾았다. 아이들 목소리가 여럿이다.<br>일행이 무기 자루를 잡고 끌어냈다. 신발 한 짝이 공 밑에 남았다. 찾으러 들어가지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-20 } }
  ] },

{ at:'A2', t:'강당 — 수놓이는 이름',
  x:`강당 관람석 맨 윗줄은 물 밖이다. 마른 나무 의자가 줄지어 있다. 그 아래로는 천장 밑까지 물이다.<br><br>
    맨 윗줄 의자 등받이 하나에 명찰이 꽂혀 있다. 바늘이 저 혼자 오르내리며 이름을 수놓는다. 이쪽 이름이다. 받침 하나가 남았다.<br>
    무기를 쥐는 사람은 자루에 이름을 새긴다. 잃어버려도 돌아오라고. 이쪽 자루에도 이름이 있다.<br><br>
    바늘이 한 땀 갈 때마다 자루의 이름이 조금씩 흐려진다.`,
  o:[
    { l:'① 명찰을 꿴 실을 끊는다.', k:'break', dc:23,
      ok:`날을 들어 명찰 실을 그었다. 실이 끊어지며 명찰이 등받이에서 떨어진다. 바늘도 같이 떨어졌다. 둘 다 아래 물로 굴러갔다.<br><br>명찰이 가라앉는다. 수놓던 이름이 물속에서 풀린다. 실이 한 가닥씩 빠져 흩어진다.<br>자루를 봤다. 이름이 다시 진하다. 손톱으로 긁어 봤다. 새긴 자리가 그대로다.`,
      ng:`실을 그었는데 실이 날을 감는다. 안 끊어진다. 명찰 실은 질기게 꼰 것이다.<br><br>바늘이 빨라진다. 마지막 받침을 수놓는다. 자루의 이름이 다 지워졌다. 손에 쥔 무기가 잠깐 남의 것 같다.<br>일행이 실을 함께 끊었다. 명찰이 떨어졌다. 이름은 다 수놓인 채였다. 자루에 이름을 다시 새기는 동안 손이 떨렸다.`,
      win:{ exp:20, dream:3, spirit:6 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 자루의 이름을 날로 깎아 낸다.', k:'fix', dc:22,
      ok:`자루에 새긴 이름을 날로 깎아 냈다. 나무 부스러기가 무릎에 떨어진다.<br><br>바늘이 멈췄다. 수놓을 이름이 어디에도 없다. 바늘이 명찰 위에서 한참 망설이다 실을 끊고 떨어졌다. 명찰에는 받침 하나가 빈 이름이 남았다. 다 못 쓴 이름은 이름이 아니다.<br>이름 없는 무기를 쥐었다. 손에는 똑같다. 손이 이름을 쥐는 게 아니다.`,
      ng:`깎는데 바늘이 더 빨라진다. 이쪽이 지우는 속도보다 빠르다.<br><br>마지막 한 땀이 들어갔다. 이쪽 이름이 다 수놓였다. 명찰이 등받이에서 빠져 물 위에 내려앉았다. 이쪽 앞으로 떠 온다.<br>집지 않았다. 명찰은 한참 발밑 물가에 떠 있다가 물살에 밀려 갔다. 무대 쪽으로.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 무거워진 무기',
  x:`쉬다가 무기를 들었다. 무겁다. 아까보다 한 줌만큼.<br><br>
    전사는 제 무기 무게를 안다. 아침 무게, 피가 묻은 무게, 젖은 무게. 이건 그 어느 것도 아니다.<br>
    날끝 쪽이 무겁다. 작은 것이 걸터앉은 만큼.<br><br>
    날끝을 봤다. 아무것도 없다. 무게가 자루 쪽으로 한 뼘 옮겨 왔다.`,
  o:[
    { l:'① 크게 한 번 휘둘러 털어 낸다.', k:'break', dc:22,
      ok:`일어나 빈 데를 향해 크게 휘둘렀다. 끝까지. 날끝이 바닥을 스칠 만큼.<br><br>휘두르는 끝에서 무게가 떨어져 나갔다. 날아가 벽에 부딪히는 소리. 작은 것이 바닥에 구르는 소리. 그리고 달려가는 소리. 맨발이다.<br>무기가 원래 무게로 돌아왔다. 손이 안다. 벽에 작은 손바닥 자국이 하나 찍혀 있었다.`,
      ng:`휘둘렀는데 무게가 안 떨어진다. 더 꽉 붙는다. 날을 끌어안은 것처럼.<br><br>휘두른 힘이 그대로 어깨로 돌아왔다. 어깨가 빠질 듯 당겨진다. 무기를 놓쳤다. 바닥에 떨어진 무기가 저절로 반 바퀴 돈다. 날끝이 이쪽을 향한다.<br>한참 아무도 못 줍겠다고 했다. 결국 주웠다. 무게가 자루 바로 위까지 와 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 무게가 손에 닿기 전에 내려놓고 물러선다.', k:'sense', dc:22,
      ok:`무게가 자루 쪽으로 오는 걸 손바닥으로 느꼈다. 한 뼘. 또 한 뼘. 손에 닿기 전에 무기를 바닥에 눕히고 손을 뗐다.<br><br>한 발 물러섰다. 무기가 바닥에서 조금 기운다. 무게가 자루 끝에서 내려간다. 바닥으로. 발소리는 없다.<br>숨 열을 센 뒤에 무기를 다시 들었다. 원래 무게다. 자루 끝이 조금 따뜻했다.`,
      ng:`내려놓으려는 순간 무게가 손등으로 뛰어올랐다. 차다. 작다. 손등에서 손목으로, 팔꿈치로.<br><br>팔을 털었다. 소매 안으로 들어간다. 겨드랑이까지. 일행이 옷을 벗기는 걸 도왔다. 아무것도 없다.<br>그 뒤로 한동안 왼팔이 오른팔보다 무거웠다. 한 줌만큼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'문턱 — 가지런한 신발 한 켤레',
  x:`문턱 앞에 신발 한 켤레가 놓였다. 가지런하다. 코가 문 안쪽을 향했다.<br><br>
    크기가 이쪽 발에 꼭 맞을 것 같다. 굽이 닳은 모양까지 이쪽 걸음새다. 무기 든 쪽으로 기울어 닳았다.<br>
    문턱 너머 바닥에 하얀 줄이 그어져 있다. 신발을 신고 넘는 줄 같다.<br><br>
    이쪽 신발 끈이 저절로 풀려 있다.`,
  o:[
    { l:'① 신발을 비켜 맨발로 넘는다.', k:'evade', dc:22,
      ok:`제 신발을 벗어 들었다. 놓인 신발을 밟지 않고 비켜 맨발로 문턱을 넘었다.<br><br>바닥이 차다. 하얀 줄을 넘을 때 발바닥이 따끔했다. 그뿐이다. 놓인 신발은 신을 사람을 잃었다.<br>넘고 나서 제 신발을 다시 신었다. 끈을 두 번 묶었다. 돌아보니 놓인 신발 코가 이제 이쪽을 향해 있다. 기다리겠다는 듯이.`,
      ng:`비켜 넘는데 무기 끝이 놓인 신발을 건드렸다. 신발이 한 칸 움직여 이쪽 발밑에 들어왔다.<br><br>발이 그 안으로 들어갔다. 꼭 맞는다. 따뜻하다. 발이 저절로 하얀 줄 쪽으로 간다. 한 걸음.<br>무기 자루로 신발 뒤축을 쳐서 벗겨 냈다. 발뒤꿈치 살갗이 같이 벗겨졌다. 신발은 다시 가지런히 놓였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 무력을 쓴다 — 신발째 문턱을 부순다.', k:'break', dc:23, cost:{ might:27 },
      ok:`무력을 팔에 몰아 문턱을 내리쳤다. 신발째. 나무가 쪼개지고 신발이 튀었다. 하얀 줄도 반으로 갈라졌다.<br><br>문턱이 없으면 넘을 것도 없다. 쪼개진 틈을 그냥 걸어 지났다.<br>튀어 나간 신발 한 짝이 벽에 맞고 떨어졌다. 안에 쪽지가 들어 있다. 이쪽 발 치수가 적혀 있다. 누가 재 두었다.`,
      ng:`문턱이 생각보다 단단하다. 무기가 튕겨 나왔다. 손목이 시큰하다.<br><br>신발이 그 울림에 한 칸 다가왔다. 이쪽 발끝에 닿는다. 신발 안에서 따뜻한 김이 나온다. 발이 저절로 들어가려 한다.<br>일행이 이쪽 어깨를 잡아 끌어냈다. 다른 길로 돌아갔다. 무력도 시간도 다 썼다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, might:-5 } }
  ] },

{ at:'A', t:'마지막 방 — 한 번 남은 팔',
  x:`마지막 방이다. 천장이 높다. 그 높은 데서 무엇이 내려온다. 사람 키의 세 배다. 길다. 손이 많다.<br><br>
    이쪽 팔은 지쳤다. 무기를 들 수는 있다. 크게 휘두를 힘은 한 번쯤 남았다.<br>
    그것이 일행 쪽으로 손을 뻗는다. 손가락 하나하나가 이름을 부르듯 하나씩 펴진다.<br><br>
    한 번이다. 어디에 쓸지 정해야 한다.`,
  o:[
    { l:'① 한 번을 아껴 둔다 — 제일 가까이 올 때 친다.', k:'break', dc:23, wake:1,
      ok:`무기를 낮게 내렸다. 지친 팔을 쉬게 했다. 그것이 내려온다. 손 하나가 동료 머리 위에 닿기 직전.<br><br>그때 쳤다. 남은 힘을 한 번에 접어 넣었다. 그것의 손목이 꺾였다. 손이 많은 것이 처음으로 소리를 냈다. 천장으로 물러났다.<br><br>힘이 남았을 때 치는 줄 알았다. 힘이 하나 남았을 때 치는 법이 따로 있다. 기다리는 동안 팔은 쉬고 날은 무거워진다. 몸이 그 한 번을 셀 줄 알게 됐다.`,
      ng:`기다렸는데 그것이 오지 않는다. 내려오다 멈춘다. 이쪽이 기다리는 걸 안다.<br><br>기다리는 사이 팔이 식었다. 굳었다. 그것이 갑자기 내려온다. 들어 올린 무기가 반만 올라갔다. 그것의 손이 어깨를 쓸고 지나갔다.<br>쓰러진 채로 숨을 골랐다. 어깨에 손가락 자국이 길게 났다. 그것은 다시 천장으로 올라가 다음을 기다린다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26 } },
    { l:'② 무력을 쓴다 — 남은 무력을 전부 끌어올려 먼저 친다.', k:'break', dc:24, cost:{ might:35 },
      doom:{ title:'마지막 한 번', what:'쓰러진 것 밑에 깔렸습니다', dc:19, sec:40,
        text:`무력을 바닥까지 긁어 올렸다. 뛰어올라 그것의 몸통을 쳤다. 정확히.<br><br>그것이 무너진다. 이쪽으로. 길고 무거운 것이 한꺼번에 내려온다. 무력은 이미 다 썼다. 다리가 안 움직인다.<br>깔렸다. 손이 많은 것의 무게가 등 위에 얹힌다. 그 많은 손이 아직 조금씩 움직인다. 이쪽 등을 토닥인다.<br><br>숨이 짧아진다.`,
        dieText:`일행이 무너진 것을 들어 올렸을 때 그 밑은 조용했다.<br><br>무기는 그것의 몸통에 박힌 채였다. 끝까지 쥐고 있었다.<br>한 번을 썼다. 정확히 썼다. 그다음이 없었다.` },
      ok:`무력을 바닥까지 긁어 올려 뛰어올랐다. 몸통이 아니라 천장에 걸린 쪽을 쳤다. 매달린 데를.<br><br>그것이 떨어진다. 이쪽이 아니라 앞으로. 뛰어오른 반동으로 뒤로 굴렀다. 길고 무거운 것이 바닥을 울리며 눕는다. 손들이 한참 바닥을 긁다가 멎었다.<br>일어나지 못했다. 무력이 하나도 없다. 동료가 일으켜 줬다. 일으켜지는 것도 오랜만이다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 일행 앞에 서서 무기를 가로로 들고 받는다.', k:'steady', dc:23,
      ok:`일행 앞에 섰다. 무기를 가로로 들어 머리 위로. 휘두르지 않고 받기만 한다.<br><br>손들이 내려온다. 무기에 닿는다. 하나, 둘, 다섯. 무게가 쌓인다. 무릎이 꺾이려 한다. 안 꺾였다. 손들이 일행에게 닿지 못한다.<br>그것이 물러났다. 받기만 하는 것과는 셈이 안 된다는 듯이. 팔이 떨려서 무기를 내리는 데 한참 걸렸다.`,
      ng:`가로로 들었다. 손들이 무기에 닿는다. 다섯, 여덟. 무겁다. 무릎이 꺾였다.<br><br>손 하나가 무기 밑으로 들어와 이쪽 얼굴을 만졌다. 이름을 부르듯이 볼을 톡톡 친다.<br>일행이 뒤에서 이쪽을 끌어냈다. 볼에 손가락 자국 셋이 차갑게 남았다. 그것은 다시 천장으로 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-20 } }
  ] }

]);

// ------------------------------------------
// 화염술사 · 마력
// ------------------------------------------
kJob('pyro', 'A', [

{ at:'A', t:'복도 — 기우는 손바닥 불',
  x:`손바닥에 불을 띄우고 걷는다. 주먹만 한 불이다. 불을 다루는 사람이 제일 처음 배우는 불이다.<br><br>
    바람이 없는데 불이 기운다. 왼쪽 어둠으로. 불은 공기가 빨려 가는 쪽으로 눕는다. 숨 쉬는 것이 있으면 그쪽으로 눕는다.<br>
    어둠 속은 아무것도 안 보인다. 불만 안다.<br><br>
    불이 조금씩 더 눕는다. 가까워진다는 뜻이다.`,
  o:[
    { l:'① 불이 눕는 각도로 거리를 잰다.', k:'gaze', dc:22, wake:1,
      ok:`불끝을 봤다. 눕는 각도가 숨 한 번에 한 번씩 달라진다. 들이쉴 때 눕고 내쉴 때 선다. 저쪽이 숨 쉬는 박자다.<br><br>박자를 세며 일행을 오른쪽 벽으로 붙였다. 불이 서는 순간마다 한 걸음. 저쪽이 내쉬는 동안은 듣지 못한다.<br>복도를 빠져나왔다. 불이 그제야 똑바로 섰다.<br><br>불은 비추는 것인 줄 알았다. 불은 듣기도 한다. 어둠 속 숨을 불끝이 먼저 듣는다. 손바닥이 불끝의 떨림을 읽는 법을 알았다. 눈보다 먼저.`,
      ng:`세다가 박자가 끊겼다. 불이 눕기만 한다. 저쪽이 숨을 안 내쉰다. 참고 있다.<br><br>참는 숨은 가깝다는 뜻이다. 불이 손바닥에서 미끄러질 만큼 누웠다. 불끝이 이쪽 소매에 닿았다. 소매가 그을렸다.<br>그대로 서 있었다. 한참 뒤에 불이 섰다. 그 숨을 다 내쉬고 갔다. 복도에 찬 김이 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 불이 눕는 쪽으로 불을 던진다.', k:'break', dc:23,
      doom:{ title:'불을 받은 것', what:'불꽃째 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`불을 던졌다. 불이 어둠 속으로 날아가다 멈춘다. 허공에서.<br><br>무엇이 받았다. 불이 손안에 쥐인 것처럼 작아진다. 그 불빛에 손가락이 보인다. 길다. 마디가 많다. 불을 쥔 손이 이쪽으로 뻗는다.<br>이쪽 손목을 잡았다. 차다. 불을 다룬 손에 그 찬 기운이 든다. 당긴다. 불빛이 멀어지는 쪽으로.<br><br>손바닥에 새 불을 피우려 했다. 안 핀다. 손이 너무 차다.`,
        dieText:`일행이 새 불을 켰을 때 복도는 비어 있었다.<br><br>멀리 복도 끝에서 작은 불빛 하나가 흔들린다. 주먹만 한 불이다. 들고 있는 손이 높다.<br>불빛은 다음 날에도 그다음 날에도 복도 끝에 있다. 가까이 가면 멀어진다.` },
      ok:`던지기 직전에 불을 셋으로 쪼갰다. 하나만 어둠으로 던지고 둘은 손에 쥐었다.<br><br>던진 불이 허공에서 멈춘다. 무엇이 받았다. 그 불빛에 손가락이 보였다. 길다. 손에 남은 불 둘을 크게 키웠다. 받은 손이 움찔 물러난다.<br>제 불을 쥐고 있는 쪽이 이긴다. 어둠 속 불빛이 꺼졌다. 받은 것이 쥐어 꺼 버렸다. 그 뒤로 불이 눕지 않았다.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 마력을 쓴다 — 불을 불씨로 줄여 손안에 감춘다.', k:'hide', dc:22, cost:{ mana:26 },
      ok:`불을 줄였다. 주먹에서 콩알로. 콩알에서 불씨로. 마력으로 감싸 손안에 쥐었다. 빛이 손가락 사이로도 안 샌다.<br><br>복도가 캄캄해졌다. 일행 손을 잡고 걸었다. 어둠 속에서 무엇이 이쪽을 찾는다. 불을 찾는다. 불이 없다.<br>복도를 나와 손을 폈다. 불씨가 살아 있다. 손바닥 가운데가 하얗게 데었다. 아프다. 살았으니 됐다.`,
      ng:`불씨로 줄이는데 마력이 흔들렸다. 불씨가 손가락 사이로 한 번 번쩍했다.<br><br>그 한 번이면 충분했다. 어둠 속에서 무엇이 이쪽으로 돈다. 바람이 이쪽으로 빨려 간다. 불씨가 손안에서 숨을 못 쉰다.<br>불씨가 꺼졌다. 손을 쥔 채 뛰었다. 등 뒤로 숨소리가 바짝 따라오다 복도 끝에서 멈췄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18, mana:-5 } }
  ] },

{ at:'A1', t:'의상실 — 온기를 찾는 탈들',
  x:`의상실 레일에 인형탈이 줄줄이 걸려 있다. 머리 없는 몸통이 축 늘어졌다. 등 지퍼가 열렸다.<br><br>
    탈들이 레일을 따라 아주 천천히 돈다. 덜, 덜. 그러다 한 칸씩 몸을 튼다. 따뜻한 쪽으로.<br>
    일행 중에 제일 따뜻한 몸은 이쪽이다. 손바닥 불을 꺼도 열이 남는다. 불을 다룬 몸은 그렇다.<br><br>
    탈 하나가 소매를 들어 이쪽으로 뻗는다. 털 끝이 그을음 냄새를 맡듯 떨린다.`,
  o:[
    { l:'① 마력을 쓴다 — 몸의 열을 바닥까지 내린다.', k:'hide', dc:22, cost:{ mana:28 },
      ok:`숨을 길게 내쉬며 열을 거뒀다. 손끝부터. 마력으로 몸 안쪽 불을 눌러 끄듯이. 입김이 하얗게 나온다.<br><br>탈들이 이쪽을 지나친다. 몸통이 다른 일행 쪽으로 튼다. 이번엔 일행이 더 따뜻하다. 일행을 이쪽 등 뒤로 몰아세웠다. 차가운 몸이 벽이 됐다.<br>건너편 문까지 갔다. 열을 돌리는 데 한참 걸렸다. 손가락이 얼었다 녹으며 쑤신다.`,
      ng:`열을 내리는데 끝까지 안 내려간다. 가슴 한가운데 불씨 하나가 남는다. 그건 끌 수가 없다.<br><br>탈들이 그 한 점을 찾아 몰려든다. 털 팔들이 가슴께에 얹힌다. 지퍼가 이쪽으로 벌어진다.<br>일행이 끌어냈다. 가슴에 털 자국이 남았다. 차갑다. 불씨가 한동안 안 살아났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24, mana:-5 } },
    { l:'② 레일째 불을 놓는다.', k:'break', dc:23,
      doom:{ title:'불붙은 레일', what:'불붙은 탈들 사이에 갇혔습니다', dc:18, sec:45,
        text:`손바닥 불을 레일 맨 앞 탈에 붙였다. 털이 금방 탄다. 불이 옆 탈로 옮는다. 레일을 따라 한 줄로.<br><br>탈들이 몸을 튼다. 불붙은 채로 이쪽으로. 이제 제일 따뜻한 것은 저것들인데도 온다. 불붙은 팔이 이쪽을 안으려 벌어진다.<br>뒤를 보니 문 쪽 레일에도 불이 옮았다. 연기가 천장에 깔린다. 숨이 매캐하다.<br><br>털 타는 연기 속에서 탈들이 이쪽을 빙 둘러선다.`,
        dieText:`불이 다 꺼진 뒤 의상실 레일에는 그을린 옷걸이만 남았다.<br><br>바닥 한가운데 재가 동그랗게 쌓였다. 그 둘레로 탈들의 재가 빙 둘러 있다. 안아 주려고 모인 모양 그대로.<br>다음 날 레일에 새 탈이 걸렸다. 불 냄새가 조금 났다.` },
      ok:`출구 반대편 레일 끝에서부터 불을 놓았다. 불이 그쪽에서 이쪽으로 오기까지 숨 스무 번.<br><br>탈들이 불 쪽으로 몸을 튼다. 이제 제일 따뜻한 건 불이다. 털 팔들이 불을 안는다. 하나씩 타 들어간다.<br>그사이 출구로 빠져나왔다. 문을 닫았다. 문틈으로 털 타는 냄새가 났다. 그 냄새는 오래 남는다.`,
      win:{ exp:23, dream:3 } },
    { l:'③ 빈 옷걸이 칸으로 몸을 낮춰 빠르게 지난다.', k:'evade', dc:22,
      ok:`레일에 옷걸이가 빈 칸이 있다. 거기로 몸을 낮춰 들어갔다. 탈들이 몸을 틀기 전에.<br><br>털 끝이 등을 쓴다. 이쪽 온기를 따라 털이 일어선다. 멈추지 않았다. 다음 빈 칸, 다음 빈 칸.<br>문에 닿았다. 돌아보니 탈들이 전부 이쪽을 향해 서 있다. 레일이 멈췄다. 따뜻한 것이 나간 문을 본다.`,
      ng:`빈 칸으로 들어갔는데 레일이 움직여 빈 칸이 닫혔다. 탈 둘 사이에 끼었다.<br><br>양쪽 탈이 이쪽을 안는다. 털 속이 덥다. 숨이 막힌다. 지퍼가 등 쪽에서 열리는 소리.<br>팔꿈치로 밀고 빠져나왔다. 손바닥 불이 저절로 일어 털 몇 가닥을 태웠다. 탈이 놓았다. 타는 냄새가 손에 뱄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A2', t:'보일러실 — 꺼지지 않은 불',
  x:`보일러실은 물이 가슴까지다. 그런데 물이 따뜻하다. 보일러 아궁이에 불이 타고 있다. 물속에서.<br><br>
    쇠문 틈으로 주황빛이 샌다. 물이 그 앞에서 일렁인다. 거품이 안 오른다. 불이 물을 끓이지 않는다. 그냥 탄다.<br>
    화염술사는 불을 보면 무엇을 먹고 타는지 안다. 장작, 석탄, 기름. 이 불은 그 어느 것도 아니다.<br><br>
    아궁이 앞 물속에 실내화 한 켤레가 가지런하다. 그 옆에 한 켤레 더. 또 한 켤레.`,
  o:[
    { l:'① 아궁이 문을 열고 불을 들여다본다.', k:'gaze', dc:23,
      doom:{ title:'아궁이', what:'아궁이 속으로 빨려 들어갑니다', dc:18, sec:45,
        text:`쇠문을 열었다. 주황빛이 쏟아진다. 불 속에 무엇이 타는지 봤다.<br><br>이름이다. 종이도 나무도 아니다. 이름이 탄다. 불꽃 하나하나가 글자 모양이다. 불이 이쪽을 보고 일렁인다. 새 이름을 본다.<br>아궁이가 물을 빨아들인다. 물살이 이쪽을 앞으로 민다. 쇠문 테두리를 잡았다. 뜨겁지 않다. 차다. 손이 미끄러진다.<br><br>불이 이쪽 이름을 읽는다. 한 글자씩.`,
        dieText:`보일러실 물은 다음 날에도 따뜻했다.<br><br>아궁이 앞에 실내화가 한 켤레 늘었다. 가지런하다. 크기가 다른 것보다 크다.<br>쇠문 틈으로 새는 불빛이 조금 밝아졌다. 한 사람 몫만큼.` },
      ok:`쇠문을 반만 열었다. 몸을 문 옆으로 비키고 불을 봤다. 정면으로 서지 않았다.<br><br>불 속에서 이름이 탄다. 글자 모양 불꽃들이다. 아궁이가 물을 빨아들인다. 정면에 섰으면 같이 빨렸다. 옆에 선 이쪽은 물살만 스쳤다.<br>쇠문을 닫았다. 불빛 사이로 한 글자를 읽었다. 이 학교 이름이다. 학교가 제 이름을 땐다. 다 탈 때까지 데우려고.`,
      win:{ exp:22, dream:3 } },
    { l:'② 마력을 쓴다 — 그 불 한 점을 손바닥에 옮겨 온다.', k:'fix', dc:23, cost:{ mana:30 }, wake:1,
      ok:`쇠문 틈에 손을 대고 마력을 흘렸다. 불을 달래듯이. 불 한 점이 틈으로 나와 손바닥에 앉는다.<br><br>물속인데 안 꺼진다. 손바닥 위에서 물을 밀어내고 탄다. 둘레 물만 따뜻하다. 다른 불을 배우는 건 오랜만이다.<br><br>불은 공기를 먹는 줄 알았다. 이 불은 다른 걸 먹는다. 먹는 것만 알면 물속에서도 탄다. 손바닥이 그 불의 결을 알았다. 마력이 그 결대로 흐르는 법을 배웠다. 물이 전처럼 무섭지 않다.`,
      ng:`불 한 점이 손바닥에 옮겨 앉았다. 그런데 이쪽 마력을 먹는다. 빨리. 굶은 것처럼.<br><br>손을 털었다. 안 떨어진다. 마력이 다 빠져나가고 나서야 불이 저 혼자 꺼졌다. 손바닥에 글자 모양 화상이 남았다.<br>무슨 글자인지 아무도 못 읽었다. 이쪽은 읽었다. 이쪽 이름 첫 글자다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24, mana:-5 } },
    { l:'③ 실내화를 치우고 아궁이 문을 막는다.', k:'break', dc:22,
      ok:`아궁이 앞 실내화를 한 켤레씩 들어 옆 선반에 올렸다. 물 위로. 열두 켤레.<br><br>마지막 켤레를 치우고 쇠문 손잡이를 쇠막대로 꿰어 막았다. 불빛이 조금 어두워졌다. 기다리는 사람이 없으면 불도 덜 탄다.<br>선반 위 실내화에서 물이 떨어진다. 한 켤레 안에 꿀단지가 들어 있었다. 매점 것이다. 누가 숨겨 두었다. 아직 달다.`,
      ng:`실내화를 드는데 무겁다. 물이 아니라 발이 들어 있는 무게다.<br><br>실내화가 손에서 빠져나가 제자리로 돌아간다. 가지런히. 아궁이 앞 물살이 이쪽 다리를 감는다.<br>선반을 붙들고 버텼다. 물이 한참 당기다 놓았다. 다리에 덴 자국이 남았다. 뜨거운 데 닿은 적이 없는데.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 하나 더 많은 그림자',
  x:`쉬는 자리에 불을 피웠다. 작게. 일행이 둘러앉았다.<br><br>
    벽에 그림자가 비친다. 사람 수대로. 그런데 하나가 더 있다. 이쪽 그림자와 옆 사람 그림자 사이에.<br>
    그 그림자는 불을 보고 앉아 있지 않다. 일행 쪽을 보고 앉아 있다.<br><br>
    불을 피운 사람은 불이 만드는 그림자도 맡는다.`,
  o:[
    { l:'① 불을 크게 일으켜 그늘을 지운다.', k:'break', dc:22,
      ok:`장작 위에 손을 펴고 불을 일으켰다. 한꺼번에. 천장까지. 방 안에 그늘이 다 사라졌다.<br><br>그림자들이 벽에서 옅어진다. 일행 것은 옅어지다 남는다. 하나는 안 남았다. 그늘이 없는 데서는 서 있을 자리가 없다.<br>불을 다시 줄였다. 그림자가 사람 수대로 돌아왔다. 다들 불 가까이 붙어 앉았다. 등 뒤가 없도록.`,
      ng:`불을 일으켰다. 그림자들이 옅어진다. 하나만 진해진다. 불이 밝을수록 진하다.<br><br>그것이 벽에서 일어선다. 일행 그림자들 머리 위로 손을 얹는다. 한 명씩. 머리를 쓰다듬는다.<br>불을 꺼 버렸다. 캄캄한 데서 한참 숨을 죽였다. 다시 불을 켰을 때 그림자는 사람 수대로였다. 다들 머리가 차갑다고 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 한 사람씩 손을 들게 해 그림자를 맞춰 본다.', k:'gaze', dc:22,
      ok:`한 사람씩 손을 들어 보라고 했다. 벽의 그림자가 하나씩 손을 든다. 넷째까지 맞는다.<br><br>남은 그림자가 손을 든다. 아무도 안 들었는데. 그림자 손가락이 넷이다.<br>그 그림자가 앉은 자리 바닥을 봤다. 불빛이 거기만 덜 닿는다. 그 자리에 불씨 하나를 던져 두었다. 그림자가 일어나 벽을 따라 나갔다. 뒷모습이 아이만 하다.`,
      ng:`손을 들라고 했다. 그림자들이 손을 든다. 하나씩. 다섯. 일행은 넷이다. 그런데 넷째 손을 든 그림자가 둘이다.<br><br>어느 쪽이 동료 그림자인지 모른다. 동료가 손을 내렸다. 그림자 하나는 내리지 않았다.<br>그 그림자는 밤새 손을 든 채였다. 다들 불을 등지지 못했다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-18, spirit:-26 } },
    { l:'③ 마력을 쓴다 — 불에서 빛을 거두고 열만 남긴다.', k:'fix', dc:23, cost:{ mana:27 }, wake:1,
      ok:`불에 손을 대고 마력을 비틀었다. 불꽃의 빛을 거뒀다. 열만 남기고. 불이 거의 안 보인다. 붉은 아지랑이만.<br><br>그림자가 다 사라졌다. 빛이 없으면 그림자도 없다. 그래도 따뜻하다. 일행이 손을 녹인다.<br><br>불은 빛과 열이 한 몸인 줄 알았다. 떼어 낼 수 있다. 빛만 거두는 손목의 비틀림을 손이 외웠다. 보이지 않는 불은 어둠 속에서 들키지 않는다.`,
      ng:`빛을 거두는데 열까지 같이 빠졌다. 불이 꺼졌다. 캄캄하다.<br><br>캄캄한 데서 무엇이 불 자리로 다가와 앉는다. 재를 만지는 소리. 따뜻했던 자리를 쓰다듬는다.<br>다시 불을 켜는 데 마력이 두 배 들었다. 불이 켜졌을 때 재에 작은 손자국이 찍혀 있었다.`,
      win:{ exp:22, dream:3, hp:6 }, lose:{ hp:-22, spirit:-24, mana:-5 } }
  ] },

{ at:'A1', t:'테이프 보관실 — 이름 칸이 빈 회차',
  x:`테이프 보관실 선반에 방송 테이프가 회차대로 꽂혔다. 등에 날짜와 제목. 방글 동산 — 오늘의 친구.<br><br>
    맨 끝 테이프는 등이 비었다. 날짜도 없다. 꺼내 보니 따뜻하다. 방금 녹화를 마친 것처럼.<br>
    케이스 안 종이에 출연자 이름 칸이 있다. 이쪽 일행 이름이 적혀 있다. 연필로. 아직 흐리다.<br><br>
    손가락이 저절로 데워진다. 필름은 잘 탄다.`,
  o:[
    { l:'① 빈 테이프를 태운다 — 글씨만 골라서.', k:'break', dc:23, wake:1,
      ok:`테이프를 바닥에 놓고 손끝을 댔다. 필름이 오그라들며 탄다. 냄새가 독하다. 불꽃이 파랗다.<br><br>타는 동안 스피커에서 박수가 났다. 끊겼다. 다시 났다. 끊겼다. 아이들 목소리가 몇 마디 나오다 거꾸로 감겼다.<br>종이 쪽에는 손끝만 스쳤다. 종이는 그대로고 연필 이름만 지워졌다. 열기에 날아갔다.<br><br>불은 물건을 태우는 줄 알았다. 이 불은 적힌 것을 태웠다. 무엇을 태울지 손끝이 골랐다. 종이는 남기고 글씨만. 한 번 한 것은 다시 된다.`,
      ng:`손끝을 대는데 필름이 녹으며 손가락에 달라붙는다. 뜨겁다. 이쪽 불인데 이쪽을 덴다.<br><br>녹은 필름이 손등까지 감긴다. 그 안에 화면이 비친다. 작게. 무대 위에 이쪽이 앉아 있다. 웃고 있다.<br>떼어 내는 데 살갗이 같이 떨어졌다. 테이프는 반만 탔다. 이름 칸 연필 글씨가 조금 진해졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 테이프 등을 훑어 회차 규칙을 찾는다.', k:'sense', dc:22,
      ok:`테이프 등을 처음부터 훑었다. 날짜가 매주 하나씩. 출연자 이름은 회마다 다르다. 한 회에 한 명.<br><br>그런데 출연자는 다음 회에도 나온다. 그다음 회에도. 방청석 칸에. 한 번 나온 친구는 계속 방청객이다.<br>빈 테이프를 맨 앞 칸에 꽂았다. 제일 오래된 회차 앞에. 순서가 꼬이면 녹화도 꼬인다. 선반 쪽에서 테이프 감기는 소리가 났다. 거꾸로.`,
      ng:`훑다 보니 테이프 등 날짜가 계속 늘어난다. 이쪽이 보는 사이에도. 선반 끝이 멀어진다.<br><br>끝을 찾아 걸었다. 걸어도 끝이 안 온다. 일행이 이쪽 이름을 불러 세웠다. 돌아보니 몇 걸음 안 왔다.<br>머리가 지끈거린다. 손에 테이프 하나를 쥐고 있었다. 언제 뽑았는지 모른다. 등에 오늘 날짜.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'세면장 — 김 서린 거울',
  x:`세면장 물은 무릎까지다. 거울이 벽에 줄지어 붙었다. 다 뿌옇다. 물때가 아니라 김이다. 차가운 김.<br><br>
    거울 하나에 손가락 글씨가 써져 있다. 안쪽에서. 거꾸로 된 글씨다. 반만 남았다.<br>
    김은 데우면 더 서린다. 더 서리면 손가락 자국이 더 잘 보인다. 불 쓰는 손은 그걸 안다.<br><br>
    옆 거울 김 위로 손가락 하나가 새로 긋기 시작한다. 안쪽에서.`,
  o:[
    { l:'① 손바닥 불로 거울을 데워 글씨를 끝까지 읽는다.', k:'gaze', dc:22,
      ok:`거울 앞에 손을 펴고 데웠다. 김이 고르게 서린다. 안쪽 글씨가 또렷해진다. 거꾸로 읽었다.<br><br>세면장 다음 문은 잠겼음. 열쇠는 사감실. 사감은 밤 아홉 시에 비움.<br>쓰다 만 글씨 끝에 한 줄. 나는 늦었다. 그 밑에 번호. 17.<br><br>손을 거두자 김이 걷혔다. 거울 속에 이쪽 얼굴만 있다. 그 뒤가 비었다. 다행이다.`,
      ng:`데웠다. 김이 짙어진다. 글씨가 아니라 손바닥 자국이 떠오른다. 거울마다. 안쪽에서 대고 있다.<br><br>그 손바닥들이 이쪽 손바닥과 마주 닿는 높이다. 이쪽 손이 저절로 거울로 간다. 마주 대려고.<br>일행이 손목을 잡아챘다. 거울에 닿기 한 치 전. 손바닥이 얼음처럼 시리다. 닿지도 않았는데.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 거울을 뜨겁게 달궈 김을 다 걷는다.', k:'break', dc:23,
      ok:`손바닥을 거울에 바짝 대고 열을 올렸다. 김이 한 번에 걷혔다. 유리가 쩍 소리를 낸다.<br><br>쓰던 손가락이 멈췄다. 긋던 줄이 날아갔다. 쓸 데가 없다. 거울마다 김을 걷었다. 맑은 거울에는 안쪽에서 아무것도 못 쓴다.<br>거울 줄 끝까지 지나갔다. 마지막 거울 유리에 금이 갔다. 금이 글씨 모양으로 났다. 읽지 않았다.`,
      ng:`달구는데 거울이 터졌다. 유리 조각이 물에 쏟아진다.<br><br>터진 거울 뒤 벽에서 차가운 물이 뿜어 나온다. 얼굴을 친다. 손가락이 그 물줄기를 타고 나와 이쪽 볼에 긋는다. 한 줄.<br>볼에 긁힌 자국이 남았다. 일행이 들여다봤다. 거꾸로 된 글자 한 자다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'계단 — 따라오는 촛불',
  x:`계단을 내려가는데 뒤에 불빛이 따라온다. 촛불 하나만 하다. 사람 허리 높이에 떠 있다.<br><br>
    이쪽 불이 아니다. 이쪽 불은 손바닥에 있다. 일행 중에 촛불을 든 사람도 없다.<br>
    따라오는 불은 기울지 않는다. 바람이 불어도. 불이 아닌 것이 불 모양을 하고 있다.<br><br>
    화염술사는 남의 불을 보면 손이 근질거린다. 그 불이 이쪽 손바닥 불을 보고 있다.`,
  o:[
    { l:'① 그 불을 손바닥으로 받아 제 불로 삼킨다.', k:'break', dc:23, wake:1,
      ok:`돌아서서 손바닥을 내밀었다. 이쪽 불을 끄고 빈손으로. 따라오던 불이 다가온다. 손바닥 위에 내려앉는다.<br><br>쥐었다. 마력을 오므려 그 불을 안으로 말아 넣었다. 차갑다. 불인데 차다. 손안에서 한참 버둥거리다가 이쪽 불이 됐다.<br><br>남이 피운 불을 받아 제 불로 삼는 법이 있다. 불끼리는 섞인다. 섞이면 센 쪽 것이 된다. 손이 그걸 알았다. 이쪽 불이 조금 파래졌다. 그 빛이 오래 안 빠진다.`,
      ng:`손바닥을 내밀었다. 불이 내려앉는다. 쥐려는데 그 불이 이쪽 손바닥 불을 먼저 먹었다.<br><br>손이 얼었다. 마력이 손목에서 빠져나간다. 따라오던 불이 이쪽 불만큼 커졌다. 그대로 떠올라 앞쪽 어둠으로 간다. 일행보다 앞에.<br>그 불이 길을 비춘다. 이쪽이 가려던 길이 아니다. 따라가지 않았다. 손이 한참 안 녹았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 불을 끄고 어둠 속에서 비켜선다.', k:'evade', dc:22,
      ok:`손바닥 불을 껐다. 일행을 벽에 붙였다. 다 같이 숨을 죽였다.<br><br>따라오던 불이 계단을 내려온다. 일행 옆을 지난다. 기울지 않는다. 그 불빛에 비친 손이 있다. 촛불을 든 손. 손만 있다.<br>불이 아래층으로 내려갔다. 한참 뒤에 다시 불을 켰다. 계단 난간에 촛농이 한 방울 떨어져 있었다. 차다.`,
      ng:`불을 끄고 비켜섰다. 따라오던 불이 일행 앞에서 멈춘다. 이쪽 앞에서.<br><br>불빛에 이쪽 얼굴만 비친다. 불이 오래 이쪽을 들여다본다. 손바닥이 저절로 데워져 불이 다시 켜지려 한다. 주먹을 쥐어 눌렀다. 손톱이 살을 팠다.<br>불이 떠났다. 주먹을 펴니 손바닥에 피가 뱄다. 다들 이쪽 얼굴이 하얗다고 했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'잠자리 — 식어 가는 손끝',
  x:`잠들기 전에 손끝을 봤다. 늘 따뜻한 손이다. 불을 다룬 손은 밤에도 데워져 있다.<br><br>
    오늘은 손끝이 식는다. 하나씩. 무엇이 손가락을 잡고 있다. 차고 작은 손. 이쪽 온기를 마신다.<br>
    손끝 다음은 손바닥이다. 손바닥 다음은 손목이다.<br><br>
    옆에 누운 동료는 춥다며 이쪽으로 붙는다. 동료 손도 차다.`,
  o:[
    { l:'① 손끝에 불을 올려 잡은 손을 떼어 낸다.', k:'break', dc:22,
      ok:`손끝에 불을 올렸다. 아주 조금. 데지 않을 만큼만. 차가운 손이 움찔한다. 그래도 안 놓는다. 조금 더 올렸다.<br><br>차가운 손이 놓았다. 뜨거운 데 데인 아이처럼 손을 빼는 기척. 그리고 울먹이는 숨소리 하나. 멀어진다.<br>손끝이 다시 따뜻해졌다. 동료 손을 쥐어 데워 줬다. 동료는 그대로 잠들었다. 이쪽은 반만 잤다.`,
      ng:`불을 올렸는데 차가운 손이 그 불까지 마신다. 불이 손끝에서 꺼진다. 마력이 빨려 나간다.<br><br>손목까지 시리다. 팔꿈치까지. 일어나 앉아 팔을 문질렀다. 아무것도 없다. 손가락만 하얗다.<br>그 뒤로 한참 손바닥 불이 안 붙었다. 붙어도 금방 꺼졌다. 손끝이 아직 무엇을 쥐고 있는 것 같다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-18 } },
    { l:'② 동료 손을 같이 쥐고 둘의 열을 합친다.', k:'bond', dc:22,
      ok:`동료 손을 쥐었다. 이쪽 손에 남은 열과 동료 손의 체온을 한데 모았다. 둘이 쥔 손 가운데가 따뜻하다.<br><br>차가운 손이 그 가운데를 더듬는다. 들어올 틈이 없다. 두 사람 손바닥이 꼭 붙었다. 한참 더듬다가 다른 데로 갔다.<br>아침에 동료가 손을 놓으며 말했다. 밤새 손이 셋이었다고. 하나는 아주 작았다고.`,
      ng:`동료 손을 쥐려는데 동료 손이 이쪽 손을 먼저 쥔다. 세다. 너무 세다.<br><br>동료는 자고 있다. 잠든 채로 이쪽 손을 쥐고 온기를 마신다. 동료 손이 아니라 동료 손 안의 무엇이.<br>억지로 떼어 냈다. 동료가 깨서 영문을 몰랐다. 이쪽 손등에 손톱자국이 넷 남았다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 마력을 쓴다 — 온몸에 불을 돌려 화로가 된다.', k:'steady', dc:23, cost:{ mana:28 },
      ok:`마력을 배에 모아 온몸으로 돌렸다. 살갗 밑까지 불을 깔았다. 몸 전체가 화로가 됐다.<br><br>차가운 손이 놓는다. 너무 뜨거워 쥘 수가 없다. 일행이 이쪽으로 모여 누웠다. 다들 따뜻해서 금방 잠들었다.<br>밤새 불을 돌렸다. 아침에 보니 이쪽이 누운 둘레로 바닥 물기가 다 말라 있다. 그 바깥에 작은 발자국이 빙 둘렀다.`,
      ng:`온몸에 불을 돌리는데 한 군데가 안 데워진다. 왼손. 거기 차가운 손이 붙어 있다.<br><br>불을 더 세게 돌렸다. 다른 데가 너무 뜨거워진다. 셔츠 등이 그을렸다. 왼손은 끝까지 차다.<br>마력이 다 떨어지자 차가운 손이 천천히 놓고 갔다. 다 마셨다는 듯이. 그 밤 내내 떨었다.`,
      win:{ exp:20, dream:3, hp:8 }, lose:{ hp:-26, spirit:-22, mana:-5 } }
  ] },

{ at:'A1', t:'방청석 — 핀 조명',
  x:`방청석 천장에 핀 조명이 달렸다. 동그란 빛 하나가 빈 의자들 위를 천천히 옮겨 다닌다.<br><br>
    빛이 멈춘 자리에서 누가 일어서면 무대로 불려 나간다. 오늘의 친구! 스피커가 외친다. 아무도 안 일어나면 빛은 다음 자리로 간다.<br>
    빛이 일행 쪽으로 온다. 두 줄 앞이다.<br><br>
    빛을 만드는 손이다. 남이 만든 빛 밑에 서 본 적은 별로 없다.`,
  o:[
    { l:'① 마력을 쓴다 — 이쪽 불빛으로 핀 조명을 덮는다.', k:'fix', dc:23, cost:{ mana:30 }, wake:1,
      ok:`손바닥에 불을 키웠다. 크게. 핀 조명보다 밝게. 일행 둘레가 이쪽 불빛으로 찼다.<br><br>핀 조명이 이쪽 자리에 닿는다. 그런데 동그란 빛이 안 보인다. 더 밝은 빛 안에서는 묻힌다. 조명이 거기 멈춘 줄 아무도 모른다. 스피커가 조용하다.<br>빛이 지나갔다. 불을 줄였다.<br><br>불빛은 어둠을 쫓는 것인 줄 알았다. 다른 빛도 덮는다. 센 빛 안에서 약한 빛은 지워진다. 손바닥이 그 세기를 쟀다. 얼마나 밝으면 무엇이 지워지는지. 처음 재 본 눈금이다.`,
      ng:`불을 키웠는데 핀 조명이 이쪽 불빛을 따라온다. 밝은 쪽으로. 무대 조명은 밝은 데를 찾는다.<br><br>동그란 빛이 이쪽 위에 멈췄다. 오늘의 친구! 박수가 쏟아진다. 무릎이 저절로 펴지려 한다. 일행이 어깨를 눌러 앉혔다.<br>불을 꺼 버렸다. 빛이 한참 이쪽 머리 위에 머물다 갔다. 머리카락 끝이 그을렸다. 이쪽 불에 그을린 게 아니다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-24, mana:-5 } },
    { l:'② 핀 조명 전구를 터뜨린다.', k:'break', dc:23,
      doom:{ title:'캄캄한 방청석', what:'어둠 속에서 손에서 손으로 실려 갑니다', dc:18, sec:45,
        text:`손끝을 튕겨 불꽃 하나를 조명에 날렸다. 전구가 터진다. 방청석이 캄캄해진다.<br><br>캄캄한 데서 박수가 난다. 빛이 없으면 누가 일어섰는지 모른다. 그러면 다 일어선 걸로 친다.<br>몸이 의자에서 들린다. 작은 손들이 등을, 다리를 받친다. 앞으로 넘긴다. 손에서 손으로.<br><br>손바닥에 불을 켜려 했다. 불이 켜지자 손들이 더 빨라진다. 이제 이쪽이 제일 밝은 데다.`,
        dieText:`새 전구가 켜졌다. 핀 조명이 무대를 비춘다.<br><br>무대 가운데 의자에 오늘의 친구가 앉아 있다. 손바닥 위에 작은 불을 띄우고 있다. 웃는다. 박수가 길다.<br>방청석 일행 자리에 그을린 자국이 하나 남았다. 손바닥만 한.` },
      ok:`터뜨리기 전에 손바닥 불을 켜 두었다. 전구가 터지는 순간 이쪽 불이 방청석을 비췄다. 캄캄해지지 않게.<br><br>빛이 바뀌었다. 이제 조명이 아니라 이쪽 불이다. 이쪽 불빛 안에서는 아무도 안 일어섰다. 다들 앉아 있다. 손들이 머뭇거리다 의자 밑으로 들어갔다.<br>불을 들고 방청석을 빠져나왔다. 등 뒤에서 깨진 전구 조각이 하나씩 떨어지는 소리가 났다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 불을 끄고 의자 밑으로 몸을 접는다.', k:'hide', dc:22,
      ok:`불을 껐다. 등받이 밑으로 몸을 접어 넣었다. 일행도 따라 했다.<br><br>동그란 빛이 이쪽 줄에 닿는다. 빈 의자들만 비춘다. 앉은 사람이 없다. 의자 밑은 빛이 안 든다.<br>빛이 다음 줄로 갔다. 숨을 쉬었다. 의자 밑 바닥에 사탕 껍질이 잔뜩 떨어져 있다. 다 새것이다.`,
      ng:`숙이는데 손바닥에 남은 열이 아지랑이처럼 올라온다. 빛이 그걸 본다.<br><br>동그란 빛이 이쪽 의자 등받이에 멈췄다. 비어 있는데. 스피커가 망설인다. 오늘의… 친구?<br>숨을 참았다. 열을 눌렀다. 빛이 오래 망설이다 지나갔다. 그동안 의자 밑에서 누가 이쪽 발목을 만지작거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A2', t:'물 밑 계단 — 숨에 넣은 불',
  x:`계단이 물속으로 이어진다. 다음 층으로 가려면 숨을 참고 잠수해야 한다. 열댓 칸.<br><br>
    물이 차다. 숨을 참으면 몸이 금방 식는다. 식으면 숨이 짧아진다.<br>
    물속 계단참마다 무엇이 앉아 있다. 보이지는 않는다. 물이 거기만 무겁다.<br><br>
    불은 물에 들어가면 꺼진다. 다들 그렇게 안다. 이쪽도 그렇게 알았다.`,
  o:[
    { l:'① 마력을 쓴다 — 불을 가슴 안에 피우고 잠수한다.', k:'steady', dc:23, cost:{ mana:30 }, wake:1,
      ok:`숨을 들이쉬면서 불을 삼키듯 가슴 안에 피웠다. 마력으로 감싸서. 갈비뼈 안쪽이 따뜻해진다.<br><br>잠수했다. 차가운 물이 살을 누른다. 안쪽 불이 버틴다. 몸이 안 식는다. 숨이 길다. 계단참을 지날 때 무거운 물이 이쪽을 훑는다. 손이 뻗다가 데인 듯 물러난다.<br><br>불은 손바닥에 피우는 줄 알았다. 몸 안에도 핀다. 숨 안에 불을 넣는 법을 가슴이 알았다. 한 번 더 들어가도 된다. 그 생각이 처음으로 무섭지 않다.`,
      ng:`가슴 안에 불을 피우는데 숨이 데워져 기침이 났다. 물속에서.<br><br>숨이 한꺼번에 빠져나갔다. 거품이 위로 쏟아진다. 계단참의 무거운 물이 일제히 이쪽을 향한다. 손이 발목을 잡는다.<br>위로 차고 올라 겨우 머리를 냈다. 가슴이 덴 것처럼 아프다. 발목에 손자국이 시퍼렇게 둘.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, mind:-18, mana:-5 } },
    { l:'② 물을 데워 계단참의 것들을 쫓아낸다.', k:'break', dc:23,
      doom:{ title:'데운 계단', what:'식은 물속으로 끌려 내려갑니다', dc:18, sec:50,
        text:`물에 두 손을 넣고 불을 밀었다. 물이 데워진다. 김이 오른다. 계단참의 무거운 물이 흩어진다.<br><br>마력이 바닥나기 시작했다. 물은 끝이 없다. 이쪽 손 둘레만 따뜻하다. 그 둘레 밖에서 차가운 손들이 기다린다. 데운 물이 식기를.<br>마력이 끊겼다. 물이 순식간에 식는다. 손들이 이쪽 손목을 잡는다. 따뜻한 손을 반긴다. 당긴다.<br><br>계단참 아래로. 한 칸, 두 칸. 물속 계단은 끝이 안 보인다.`,
        dieText:`계단참 물이 조금 따뜻하다. 한 칸만.<br><br>지나가는 사람마다 그 칸에서 발이 따뜻하다고 했다. 거기서 쉬고 싶다고.<br>쉬지 않고 지나간 사람만 다음 층에 닿았다.` },
      ok:`물을 다 데우지 않았다. 계단참 한 칸 한 칸 위로만 손을 스치며 불을 흘렸다. 지나갈 칸만 잠깐.<br><br>데운 칸의 무거운 물이 비켜난다. 데운 데는 앉아 있을 수가 없다. 그사이 일행이 한 칸씩 지났다. 지난 칸은 금방 식었다.<br>다음 층에 머리를 냈다. 손이 쭈글쭈글하다. 데운 물과 찬 물을 번갈아 만진 손이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'문틈 — 불을 눕히는 숨',
  x:`닫힌 문 밑 틈으로 바람이 들어온다. 찬 바람이다. 들어오다 멈추고, 다시 들어온다. 일정하다.<br><br>
    바람이 들어올 때마다 손바닥 불이 꺼질 듯 눕는다. 문 반대쪽으로. 바람이 들어오는 게 아니다. 문 안쪽에서 숨을 내쉬는 것이다.<br>
    내쉬고, 쉬고, 들이쉰다. 들이쉴 때는 불이 문 쪽으로 빨려 간다.<br><br>
    문 너머가 다음 길이다.`,
  o:[
    { l:'① 들이쉬는 순간 불을 문틈에 밀어 넣는다.', k:'break', dc:23,
      ok:`들이쉬는 박자를 기다렸다. 불이 문 쪽으로 기우는 순간 그 불을 키워 문틈에 밀었다.<br><br>안쪽이 불을 들이켰다. 컥, 하는 소리가 문 너머에서 났다. 숨이 끊겼다. 문이 덜컹 하더니 조금 열렸다. 안에 아무도 없다. 바닥에 그을린 자국이 길게 나 있다. 누워서 숨 쉬던 모양으로.<br>문을 지났다. 안은 그을음 냄새뿐이다.`,
      ng:`밀었는데 반 박자 늦었다. 안쪽이 이미 내쉬고 있었다. 불이 거꾸로 이쪽 얼굴로 왔다.<br><br>눈썹이 탔다. 앞머리도. 얼굴이 화끈하다. 이쪽 불에 이쪽이 데었다.<br>문 너머에서 웃음 같은 숨이 났다. 바람이 다시 들어왔다. 일정하게. 문은 안 열렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 불을 등 뒤로 감추고 숨에 맞춰 숨을 쉰다.', k:'steady', dc:22,
      ok:`불을 등 뒤로 돌렸다. 바람에 안 닿게. 그리고 문 너머 숨에 맞춰 이쪽도 숨을 쉬었다. 들이쉬고, 쉬고, 내쉰다.<br><br>박자가 맞자 문 너머 숨이 조금 느려진다. 이쪽도 느리게. 더 느리게. 문 너머가 잠드는 박자다.<br>숨이 아주 느려졌을 때 문을 살며시 밀었다. 열렸다. 안쪽 벽에 기대어 무엇이 자고 있다. 보지 않고 지났다.`,
      ng:`맞추는데 저쪽 숨이 자꾸 이쪽 것보다 길다. 따라가다 숨이 찼다. 머리가 핑 돈다.<br><br>무릎을 꿇었다. 등 뒤 불이 꺼졌다. 캄캄한 데서 문 너머 숨이 이쪽 귀 바로 옆에서 난다. 문이 열려 있다. 언제부터인지.<br>일행이 이쪽을 끌어냈다. 귓불이 차다. 한참 동안 귀에서 숨소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'인형극 무대 — 손짓하는 손 인형',
  x:`인형극 무대는 작다. 아이 키만 하다. 빨간 커튼 위로 손 인형들이 줄지어 고개를 내밀었다.<br><br>
    인형들이 손짓한다. 이리 와. 무대 밑 구멍으로 손을 넣어 보라고. 같이 놀자고.<br>
    손 인형은 안에 손이 들어가야 움직인다. 지금 다 움직인다. 커튼 밑 어둠에서 팔이 몇 개나 올라와 있는지 모른다.<br><br>
    인형들 몸은 펠트다. 펠트가 얼마나 빨리 타는지 이쪽 손끝이 안다.`,
  o:[
    { l:'① 맨 끝 인형 하나에만 불을 붙인다.', k:'break', dc:23,
      ok:`맨 끝 인형 하나에만 손끝 불을 붙였다. 펠트가 금방 오그라든다. 인형이 버둥댄다.<br><br>커튼 밑에서 팔 하나가 쑥 빠진다. 데인 손이다. 다른 인형들이 일제히 멈춘다. 손짓을 그친다. 다들 불붙은 인형을 본다.<br>그사이 무대 옆을 지나갔다. 탄 인형이 바닥에 떨어져 있다. 안은 빈 장갑이다. 손가락이 넷.`,
      ng:`불을 붙였는데 펠트가 젖어 있다. 연기만 난다. 인형이 연기 속에서 웃는다.<br><br>그 인형이 이쪽 손끝을 문다. 펠트 입인데 아프다. 손끝 불이 꺼졌다. 인형 입 안에서 무엇이 이쪽 손가락을 빤다. 열을.<br>뿌리쳐 빼냈다. 손끝이 하얗다. 무대 밑에서 팔들이 일제히 이쪽을 향해 흔들린다. 고맙다는 듯이.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 불빛을 낮춰 커튼 밑 팔을 센다.', k:'gaze', dc:22,
      ok:`손바닥 불을 낮게 들어 커튼 밑을 비췄다. 팔이 보인다. 하나, 둘, 일곱. 다 아이 팔이다. 소매가 같다. 하얀 셔츠에 파란 단.<br><br>인형은 아홉이다. 팔은 일곱. 둘은 빈 인형이다. 빈 인형 둘이 손짓을 제일 크게 한다. 거기 손을 넣을 친구를 찾는다.<br>빈 인형 둘을 커튼 뒤로 눕혀 놓았다. 손짓이 멈췄다. 나머지 일곱은 계속 놀았다. 자기들끼리.`,
      ng:`비추는데 커튼 밑 팔들이 불빛을 보고 일제히 이쪽으로 뻗는다. 불을 잡으려고.<br><br>손바닥 불을 거두지 못했다. 작은 손들이 불을 쥔다. 차다. 불이 꺼지고 손들이 이쪽 손가락을 쥔다. 당긴다. 무대 밑 구멍으로.<br>일행이 허리를 안아 당겼다. 손을 빼냈다. 손목에 펠트 보풀이 잔뜩 붙었다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'중정 온실 — 유리 밖의 손바닥',
  x:`중정 유리 온실은 물속에 잠겼는데 안은 비었다. 공기가 갇혔다. 화분이 줄지어 있다. 풀이 살아 있다.<br><br>
    유리 바깥이 물이다. 유리에 김이 서려 밖이 안 보인다. 김 위로 손바닥 자국이 하나씩 찍힌다. 밖에서.<br>
    화분에 약초가 자란다. 잎이 넓고 향이 짙다. 꺾어 가면 쓸 데가 있다.<br><br>
    손바닥 자국이 늘어난다. 유리가 조금씩 운다.`,
  o:[
    { l:'① 불을 켜지 않고 향으로 약초만 골라 꺾는다.', k:'heal', dc:22,
      ok:`불을 켜지 않았다. 김을 그대로 두었다. 김이 서려 있으면 밖도 안을 못 본다.<br><br>향으로 골랐다. 짙은 것, 쓴 것, 잎맥이 하얀 것. 한 아름 꺾어 묶었다. 상처에 쓰는 것과 열을 내리는 것.<br>나오는데 유리에 손바닥 자국이 빼곡하다. 다 바깥쪽이다. 하나도 안을 못 들여다봤다.`,
      ng:`고르다 화분 하나를 엎었다. 깨지는 소리.<br><br>유리 밖 손바닥들이 일제히 문지른다. 김이 지워진다. 동그랗게, 동그랗게. 그 동그라미마다 얼굴이 하나씩 붙는다. 유리에 코를 대고.<br>약초를 쥔 채 출구로 뛰었다. 얼굴들이 유리를 따라 같이 움직였다. 유리 금 가는 소리를 등으로 들었다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 유리를 데워 김을 걷고 밖을 본다.', k:'break', dc:23,
      ok:`유리에 손을 대고 데웠다. 김이 걷힌다. 밖이 보인다. 물속이다. 손바닥들이 유리에서 미끄러져 떨어진다. 데운 유리에는 못 붙는다.<br><br>물속에 아이들이 서 있다. 유리 둘레로 빙 둘러. 다들 온실 안 화분을 본다. 자기가 심은 것을 보는 눈이다.<br>유리를 식혔다. 김이 다시 서렸다. 화분 하나에서 산나물을 뜯었다. 이름표가 꽂혀 있다. 3학년 2반.`,
      ng:`데우는데 유리가 너무 뜨거워졌다. 금이 갔다. 금 사이로 물이 실처럼 샌다.<br><br>새는 물에 손가락이 섞여 들어온다. 가늘게. 물줄기처럼. 이쪽 손등을 만진다.<br>불을 거두고 물러났다. 금은 그 자리에서 멈췄다. 물은 계속 샌다. 한 방울씩. 세는 것처럼.`,
      win:{ exp:20, dream:3, item:'산나물' }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 등에 묻은 그을음',
  x:`쉬는 틈에 동료가 이쪽 등을 털어 준다. 그러다 손을 멈춘다.<br><br>
    등에 그을음이 묻었다. 손바닥 모양이다. 작다. 다섯 개. 어깨에서 허리까지 차례로.<br>
    불 쓰는 손에는 그을음이 묻는다. 그런데 이쪽 손은 제 등에 안 닿는다. 그을음 손을 가진 것이 이쪽 등을 짚으며 따라왔다.<br><br>
    맨 아래 손자국이 제일 진하다. 가장 최근이다.`,
  o:[
    { l:'① 그을음 결을 읽어 언제 어디서 묻었는지 짚는다.', k:'gaze', dc:22, wake:1,
      ok:`셔츠를 벗어 그을음을 봤다. 그을음은 불이 기운 쪽으로 결이 난다. 결마다 방향이 다르다.<br><br>첫 자국은 계단에서. 불이 위로 눕던 때. 둘째는 문 앞. 셋째, 넷째. 다섯째는 지금 앉은 자리다. 방금.<br>뒤를 봤다. 벽에 그을음 손자국이 하나 더 있다. 이쪽 앉은 높이에. 아직 따뜻하다.<br><br>그을음은 불이 남긴 일기 같은 것이다. 이쪽 불만이 아니라 남의 손에 묻은 불도. 손가락이 그을음 결을 쓸며 읽는 법을 알았다. 지나온 길이 거기 다 있다.`,
      ng:`결을 읽는데 그을음이 손가락에 묻는다. 묻은 그을음이 저절로 손등으로 번진다. 손 모양으로.<br><br>작은 손이 이쪽 손등을 쥔 모양이다. 털어도 안 털린다. 물로 씻어도 안 진다.<br>이쪽 손이 저절로 일행 등을 짚으려 한다. 주먹을 쥐어 참았다. 손등의 그을음은 한참 뒤에야 옅어졌다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 셔츠째 태워 그을음을 버린다.', k:'break', dc:22,
      ok:`셔츠를 벗어 바닥에 놓고 불을 붙였다. 그을음 손자국부터 탄다. 빨리. 자국이 먼저 오그라든다.<br><br>타는 연기가 위로 오르지 않고 옆으로 흐른다. 벽 쪽으로. 거기서 무엇이 연기를 맡는다. 제 손 타는 냄새를.<br>재를 흩었다. 맨살 등에 여벌 옷을 입었다. 그날 밤에는 아무도 등을 짚지 않았다.`,
      ng:`셔츠를 태웠다. 그을음이 타지 않는다. 셔츠가 다 타고 그을음 손자국만 재 위에 남았다. 다섯 개.<br><br>재 위의 손자국이 기어 온다. 이쪽으로. 발목에 닿았다. 발목에 그을음 손이 하나 찍혔다.<br>여섯 개가 됐다. 이번엔 발목이다. 걸을 때마다 발목이 무겁다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'통로 — 끌려가는 동료와 불',
  x:`동료가 어둠 쪽으로 끌려간다. 발목이 잡혔다. 바닥을 긁으며 미끄러진다.<br><br>
    당기는 것은 불빛 밖에 있다. 불을 들이대면 보일 것이다. 보이면 칠 수 있다. 다만 동료 바로 앞이다.<br>
    불은 앞에 있는 것을 다 태운다. 고르지 않는다.<br><br>
    동료가 이쪽 이름을 부른다. 진짜 동료 목소리다.`,
  o:[
    { l:'① 동료 발목 앞을 불로 가른다.', k:'break', dc:23,
      doom:{ title:'불 너머', what:'제 그림자에 잡혀 불길 너머로 끌려갑니다', dc:18, sec:50,
        text:`동료 발목과 어둠 사이 바닥에 불을 내리꽂았다. 불이 한 줄로 일어선다. 불 벽이다.<br><br>당기던 것이 불 너머에서 멈춘다. 동료가 이쪽으로 굴러왔다. 됐다. 그 순간 이쪽 발목이 당겨졌다. 불 벽 이쪽에서. 이쪽 그림자 속에서.<br>불이 밝을수록 그림자가 진하다. 진한 그림자 속에 손이 있다. 그 손이 이쪽 발목을 쥐고 불 벽 너머로 끈다.<br><br>불을 끄면 그림자도 없다. 불을 끄면 불 벽도 없다.`,
        dieText:`불 벽이 다 탔다. 바닥에 그을린 줄 하나만 남았다.<br><br>줄 이쪽에 동료가 앉아 있다. 줄 저쪽은 캄캄하다.<br>그 뒤로 불을 켜면 벽에 그림자가 하나 더 진다. 손바닥 위에 불을 띄운 그림자다.` },
      ok:`불을 낮고 얇게 갈랐다. 동료 발목과 어둠 사이에. 불이 서지 않고 바닥을 핥듯 지나갔다.<br><br>당기던 것이 데었다. 어둠 속에서 쉭 하는 소리. 발목이 풀렸다. 동료를 끌어당겼다. 불이 낮아서 그림자도 짧다. 이쪽 그림자에 손이 숨을 자리가 없다.<br>동료 바짓단이 그을렸다. 발목은 멀쩡하다. 동료가 이쪽 손을 오래 쥐었다. 뜨거운데도.`,
      win:{ exp:23, dream:3 } },
    { l:'② 마력을 쓴다 — 불을 어둠 깊이 던져 당기는 것을 비춘다.', k:'gaze', dc:22, cost:{ mana:28 },
      ok:`불을 크게 말아 어둠 깊이 던졌다. 불덩이가 날아가며 통로를 비춘다. 당기는 것이 보였다.<br><br>팔이다. 아주 긴 팔 하나. 어둠 끝 벽 구멍에서 나왔다. 그 팔이 불빛에 놀라 움츠러든다. 동료 발목을 놓고 구멍으로 쑥 들어간다.<br>구멍은 아이 머리 하나 들어갈 만하다. 그 크기로 저 팔이 나왔다. 동료를 일으켰다. 둘 다 구멍 쪽을 보지 않았다.`,
      ng:`불덩이를 던졌다. 날아가다 허공에서 꺼졌다. 무엇이 받아서 쥐어 껐다.<br><br>그사이 동료가 한 길 더 끌려갔다. 다들 뛰어가 동료를 붙들었다. 겨우 버텼다.<br>마력이 다 빠진 손이 떨린다. 동료 발목에 손자국 다섯. 하나는 그을린 손자국이다. 불을 받아 쥔 그 손이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, mana:-5 } },
    { l:'③ 불을 끄고 두 손으로 동료 손을 잡는다.', k:'bond', dc:23,
      ok:`불을 껐다. 두 손이 다 필요하다. 동료 손을 두 손으로 잡았다. 뒤로 몸을 눕혔다.<br><br>캄캄한 데서 당기는 힘이 온다. 버텼다. 일행이 이쪽 허리를 잡았다. 줄이 됐다. 당기던 것이 줄 끝까지 다 당겨 보고는 놓았다.<br>불을 다시 켰다. 동료 손을 너무 꽉 쥐어 손가락 자국이 났다. 동료가 그 자국을 보고 웃었다. 여기 와서 처음으로.`,
      ng:`불을 끄고 손을 잡았다. 캄캄하다. 잡은 손이 동료 손인지 모른다. 차다.<br><br>당긴다. 이쪽이 끌려간다. 다른 손이 이쪽 왼손을 잡는다. 따뜻하다. 동료 손이다. 그럼 이쪽 오른손이 잡은 건.<br>오른손을 놓았다. 불을 켰다. 동료는 왼쪽에 있다. 오른쪽 어둠으로 무엇이 미끄러져 가는 소리. 오른손에 차가운 손자국.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-28 } }
  ] },

{ at:'A1', t:'부조정실 — 모니터 속의 불',
  x:`부조정실 벽에 모니터가 빼곡하다. 화면마다 방송국 곳곳이 나온다. 복도, 계단, 분장실.<br><br>
    모니터 하나에 이 방이 나온다. 일행이 나온다. 이쪽 손바닥 불도 나온다.<br>
    화면 속 불은 이쪽 불보다 크다. 손바닥이 아니라 소매에 붙어 있다. 화면 속 이쪽이 불타고 있다. 그런데 웃는다.<br><br>
    화면 밑 글씨. 다음 회 예고.`,
  o:[
    { l:'① 불을 끄고 화면 속 불이 어떻게 되는지 본다.', k:'gaze', dc:22,
      ok:`손바닥 불을 껐다. 화면 속 불은 안 꺼진다. 화면 속 이쪽이 계속 탄다.<br><br>오래 봤다. 화면 속 불은 기울지 않는다. 연기가 없다. 그을음도 없다. 그건 불이 아니다. 불 그림이다. 화염술사는 그림 불에 데지 않는다.<br>모니터를 등졌다. 다음 회 예고는 끝까지 안 봤다. 볼 필요가 없었다.`,
      ng:`불을 껐다. 화면 속 불이 커진다. 이쪽 불이 꺼진 만큼.<br><br>화면 속 이쪽이 화면 밖을 본다. 이쪽을. 웃는다. 이쪽 소매가 뜨겁다. 보니 연기가 오른다. 불은 없는데.<br>소매를 물병에 담갔다. 쉬익. 화면 속 이쪽은 계속 탔다. 다음 회 예고가 끝날 때까지.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 모니터 뒤 전선 다발에 불을 흘린다.', k:'break', dc:23,
      ok:`모니터 뒤로 손을 넣어 전선 다발을 쥐었다. 불을 흘렸다. 피복이 녹는다. 화면이 하나씩 꺼진다.<br><br>이쪽이 나오던 화면이 마지막에 꺼졌다. 꺼지기 직전에 화면 속 이쪽이 고개를 돌렸다. 이쪽을 안 보고 뒤를 봤다. 부조정실 문 쪽을.<br>문 쪽을 봤다. 아무도 없다. 문이 조금 열려 있다. 아까는 닫혀 있었다. 다들 문에서 먼 쪽으로 붙어 나갔다.`,
      ng:`불을 흘렸는데 전선이 아니라 모니터가 터졌다. 유리가 튄다.<br><br>터진 화면 속에서 연기가 나온다. 화면 속 불의 연기다. 매캐하다. 진짜다. 눈이 따갑고 목이 탄다.<br>부조정실을 기어서 빠져나왔다. 기침이 한참 안 멎었다. 입안에 그을음 맛이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A2', t:'도서관 — 젖은 대출 카드',
  x:`도서관 서가는 물이 턱 밑까지다. 책들이 물에 불어 서가에 꽉 끼었다.<br><br>
    반납대 위만 물 밖이다. 책 한 권이 놓였다. 반납된 책이다. 안쪽 대출 카드가 젖어 글씨가 번졌다.<br>
    번진 칸 맨 아래에 새 칸 하나가 마른 채로 있다. 이름 칸이 비었다. 반납일 칸에 오늘.<br><br>
    젖은 종이는 말리면 된다. 낮은 불로 말리면 번진 글씨가 돌아오기도 한다.`,
  o:[
    { l:'① 카드를 손바닥 열로 말려 번진 이름을 읽는다.', k:'gaze', dc:22,
      ok:`카드를 두 손바닥 사이에 끼우고 아주 낮은 열로 말렸다. 종이가 마르며 번진 잉크가 제자리로 모인다.<br><br>이름들이 돌아왔다. 대출자, 반납일. 반납일이 다 같은 날이다. 물이 들어온 날. 마지막 대출자만 반납일이 비었다. 3학년 2반 17번.<br>17번만 책을 못 돌려줬다. 그래서 도서관이 기다린다. 카드를 책에 도로 꽂았다. 마른 새 칸에는 아무것도 안 썼다.`,
      ng:`말리는데 너무 뜨거웠다. 카드 가장자리가 그을었다. 그을린 데서 글씨가 새로 떠오른다.<br><br>이쪽 이름이다. 마른 새 칸에. 이쪽 글씨체로. 손이 쓴 적이 없는데.<br>카드를 물에 던졌다. 가라앉는다. 반납대 위에 같은 책이 또 놓여 있다. 카드가 꽂혀 있다. 마른 칸에 이쪽 이름.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 책째 태워 대출 기록을 없앤다.', k:'break', dc:23,
      ok:`책을 반납대 위에서 태웠다. 젖은 책은 잘 안 탄다. 불을 세게 넣었다. 책장이 한 장씩 말리며 탄다.<br><br>도서관 물이 출렁인다. 서가의 책들이 한꺼번에 조금씩 빠져나온다. 반납될 책이 하나 사라졌다. 도서관이 셈을 다시 한다.<br>재가 물에 떨어졌다. 마른 칸이 있던 카드도 같이 탔다. 기다릴 반납일이 없다.`,
      ng:`책을 태우는데 책장이 타면서 물이 나온다. 종이에서. 끝없이.<br><br>불이 꺼졌다. 책은 젖은 그대로다. 물이 반납대를 넘쳐 이쪽 손을 덮는다. 차다. 책 안에서 누가 이쪽 손을 쥐었다.<br>뿌리쳤다. 손가락에 잉크가 묻었다. 번진 이름 모양으로. 씻어도 한동안 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 이름을 튀기는 불',
  x:`작은 불을 피웠다. 장작이 탄다. 탁, 탁. 불이 튄다.<br><br>
    튀는 소리가 이상하다. 탁. 타닥. 탁. 박자가 있다. 듣다 보니 소리가 글자처럼 들린다. 이쪽 이름의 박자다.<br>
    이쪽이 피운 불이다. 그 불이 이쪽 이름을 부른다. 아니면 불 너머의 무엇이 불을 빌려 부른다.<br><br>
    일행은 듣지 못한다. 이쪽 귀에만 들린다.`,
  o:[
    { l:'① 불꽃을 손으로 쥐어 끈다.', k:'break', dc:22,
      ok:`불에 손을 넣어 불꽃을 한 줌 쥐었다. 불 다루는 손이라 안 덴다. 쥐어서 껐다.<br><br>탁 소리가 멎었다. 장작은 숯이 되어 조용히 빨갛다. 이름도 끊겼다.<br>불을 다시 피웠다. 이번엔 숯으로만. 튀지 않는 불이다. 숯불 앞에서 다들 손을 녹였다. 이쪽은 쥐었던 손을 오래 폈다 쥐었다 했다.`,
      ng:`쥐는 순간 불꽃이 손안에서 이름을 한 번 더 부른다. 손바닥 속에서. 뼈를 타고 들린다.<br><br>손을 폈다. 불이 다시 일어났다. 이번엔 일행에게도 들린다. 탁. 타닥. 다들 이쪽을 본다. 이쪽 이름이라는 걸 다들 안다.<br>불을 흙으로 덮었다. 덮은 흙 밑에서 한참 탁 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 불 박자 사이에 틀린 박자를 섞는다.', k:'fix', dc:22,
      ok:`손가락으로 장작 하나를 툭툭 쳤다. 불 박자 사이에 이쪽 박자를 넣었다. 탁, 툭, 타닥, 툭.<br><br>이름이 흐트러진다. 소리가 글자가 안 된다. 그냥 장작 소리다. 불 너머에서 무엇이 다시 맞추려 한다. 맞출 때마다 툭.<br>밤새 그렇게 쳤다. 손가락 끝이 까매졌다. 새벽에 불이 사그라들 때까지 이름은 한 번도 다 불리지 않았다.`,
      ng:`섞었는데 불이 이쪽 박자까지 먹는다. 탁, 툭, 타닥, 툭. 그게 다른 이름이 된다. 일행 하나의 이름이다.<br><br>그 동료가 고개를 든다. 들었다. 불을 보며 대답하려 한다. 동료 입을 손으로 막았다.<br>불을 꺼 버렸다. 동료가 한참 멍했다. 대답하려던 말을 삼킨 얼굴이다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'창 — 불빛에 모이는 얼굴',
  x:`복도 한쪽이 창이다. 창 밖은 캄캄하다. 손바닥 불을 들고 걷는다.<br><br>
    창에 얼굴이 하나 붙는다. 밖에서. 이쪽 불을 본다. 걸으면 같이 옮겨 온다. 둘이 된다. 다섯이 된다.<br>
    불은 멀리서도 보인다. 그걸 알면서도 불을 켠다. 안 보이는 것보다 낫다고 믿어 왔다.<br><br>
    창이 끝나는 데까지 스무 걸음. 얼굴은 지금 열둘이다.`,
  o:[
    { l:'① 불을 창 반대쪽 손으로 옮기고 몸으로 가린다.', k:'hide', dc:22,
      ok:`불을 창 반대쪽 손으로 옮겼다. 몸을 창 쪽으로 붙였다. 등이 불을 가린다. 창에서 보면 불빛이 이쪽 등 모양으로 막혔다.<br><br>얼굴들이 창을 따라오다 멈춘다. 불이 안 보인다. 여기저기 유리를 더듬는다.<br>스무 걸음을 다 갔다. 창이 끝났다. 뒤를 보니 얼굴들이 창에 빼곡하다. 이쪽 등 높이에 맞춰 줄을 섰다.`,
      ng:`옮기는데 불빛이 창에 한 번 번쩍 비쳤다. 얼굴들이 일제히 그쪽으로 몰린다. 유리가 운다.<br><br>얼굴 하나가 유리에 이마를 댄다. 유리가 그 자리만 물렁해진다. 이마가 조금 들어온다.<br>뛰었다. 창 끝까지. 등 뒤에서 유리가 툭 하고 원래대로 돌아오는 소리가 났다. 이마 자국이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 창마다 불을 바짝 대 얼굴을 떼어 낸다.', k:'break', dc:23,
      ok:`불을 크게 일으켜 창에 바짝 댔다. 유리가 데워진다. 얼굴 하나가 데인 듯 떨어져 나간다. 다음 창, 또 다음 창.<br><br>얼굴들이 물러난다. 불빛 닿는 데까지만. 그 바깥 어둠에서 기다린다. 불이 지나가면 다시 붙는다.<br>스무 걸음을 다 데우며 갔다. 창이 끝나자 뒤의 창마다 얼굴이 다시 붙었다. 데운 유리에 김이 서려 얼굴이 뿌옇다.`,
      ng:`불을 크게 일으켰다. 얼굴들이 물러나는 게 아니라 늘어난다. 더 밝으니 더 멀리서 보인다.<br><br>유리가 얼굴로 빼곡하다. 빈틈이 없다. 창이 안쪽으로 휜다. 금이 간다.<br>불을 꺼 버렸다. 캄캄한 데서 일행 손을 잡고 창 끝까지 기었다. 금 가는 소리가 쫓아왔다. 깨지지는 않았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A', t:'마지막 방 — 빛을 먹는 어둠',
  x:`마지막 방은 어둠이 짙다. 손바닥 불을 켜도 손바닥만 보인다. 빛이 한 뼘을 못 간다.<br><br>
    어둠이 빛을 먹는다. 불이 작아진다. 마력을 더 넣어도 밝아지지 않는다. 먹는 쪽이 더 빨리 먹는다.<br>
    방 한가운데서 무엇이 숨을 쉰다. 크다. 숨을 들이쉴 때마다 불이 그쪽으로 빨려 간다.<br><br>
    이쪽 불이 꺼지면 일행은 이 방에서 아무것도 못 본다.`,
  o:[
    { l:'① 마력을 쓴다 — 빛을 버리고 열만으로 그것을 찾는다.', k:'sense', dc:23, cost:{ mana:32 }, wake:1,
      ok:`빛을 버렸다. 불에서 빛을 떼어 내고 열만 남겼다. 어둠이 먹을 빛이 없다.<br><br>열을 넓게 펼쳤다. 방 안 공기가 데워진다. 데워지는 결이 손바닥에 닿는다. 일행 몸은 따뜻하다. 방 가운데 한 덩이만 차다. 크다. 거기다.<br>그 찬 덩이를 피해 벽을 따라 일행을 이끌었다. 출구도 열로 찾았다. 바깥 공기는 조금 덜 차다.<br><br>불은 눈을 위한 것인 줄 알았다. 빛 없는 불로도 본다. 손바닥이 열의 결을 읽는다. 어둠은 빛을 먹어도 열은 못 먹는다. 이제 캄캄한 데서도 이쪽에게는 불이 있다.`,
      ng:`빛을 떼어 내는데 열도 같이 빨려 나간다. 어둠은 빛만 먹는 게 아니다.<br><br>손바닥이 식는다. 방 가운데 찬 덩이가 숨을 들이쉰다. 이쪽 열을 들이쉰다. 몸이 떨린다.<br>일행이 이쪽을 부축해 벽을 더듬어 나왔다. 이가 딱딱 부딪친다. 불 다루는 손이 떤다. 한참 안 데워졌다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, spirit:-26, mana:-5 } },
    { l:'② 남은 마력을 다 넣어 그것에게 불을 쏟는다.', k:'break', dc:24,
      doom:{ title:'마지막 불', what:'불이 꺼진 어둠 속에서 숨이 얼어붙습니다', dc:19, sec:40,
        text:`마력을 남김없이 끌어올려 두 손으로 쏟았다. 불길이 방 가운데로 간다. 한 뼘, 두 뼘. 어둠이 먹는다. 그래도 쏟았다.<br><br>불이 그것에 닿았다. 잠깐 보였다. 크다. 얼굴이 없다. 입만 있다. 불을 마신다. 맛있게.<br>마력이 끊겼다. 불이 꺼졌다. 캄캄하다. 그것이 이번엔 숨을 내쉰다. 이쪽을 향해. 차다. 얼음보다.<br><br>숨이 목에서 언다. 손바닥 불을 켜려 해도 손가락이 안 움직인다.`,
        dieText:`일행이 다른 불을 켰을 때 방은 비어 있었다. 가운데에 서리가 동그랗게 깔렸다.<br><br>서리 한가운데 사람이 손을 내민 채 서 있다. 손바닥 위로 불을 띄우던 모양 그대로.<br>손바닥 위에 서리꽃이 피었다. 불꽃 모양으로.` },
      ok:`마력을 남김없이 쏟되 그것이 아니라 천장에 쏟았다. 불길이 천장을 핥으며 퍼진다. 어둠이 먹는 속도보다 넓게.<br><br>방 전체가 한 번에 밝아졌다. 숨 한 번 동안. 그것이 보였다. 얼굴 없이 입만 있다. 빛에 놀라 입을 닫았다.<br>그 한 번에 출구를 봤다. 다들 봤다. 불이 꺼진 뒤 캄캄한 데서 그 방향으로 달렸다. 손바닥이 텅 비었다. 마력이 하나도 없다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 불을 바닥에 놓고 일행을 등지게 둘러앉힌다.', k:'steady', dc:23,
      ok:`불을 바닥에 내려놓았다. 일행을 둘러앉혔다. 등을 바깥으로. 불은 안쪽에만 비친다.<br><br>어둠이 불을 먹으려면 일행 등을 지나야 한다. 사람 몸은 빛을 안 내보낸다. 먹을 게 새어 나가지 않는다. 불이 작지만 안 꺼진다.<br>그것이 한참 둘레를 돌다 숨을 거뒀다. 불이 조금 커졌다. 다들 등이 시렸다. 그래도 아무도 돌아보지 않았다.`,
      ng:`둘러앉혔는데 한 자리가 비었다. 그 틈으로 빛이 샌다. 어둠이 거기로 불을 먹는다.<br><br>불이 작아진다. 콩알만 해진다. 그것의 숨이 틈으로 들어와 불을 핥는다. 손을 펴서 틈을 막았다. 손이 얼었다.<br>불은 살렸다. 손등이 하얗게 얼었다. 녹을 때 살갗이 벗겨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-18 } }
  ] }

]);

// ------------------------------------------
// 권사 · 내공
// ------------------------------------------
kJob('fist', 'A', [

{ at:'A', t:'복도 — 주먹이 먼저 닿는 것',
  x:`권사는 무기를 안 든다. 치려면 닿아야 한다. 닿으면 안다. 뜨거운지 찬지, 단단한지 무른지.<br><br>
    복도가 캄캄하다. 불은 뒤에 있다. 맨 앞에서 손을 앞으로 내밀고 걷는다.<br>
    손끝에 바람이 닿는다. 앞에서 부는 바람이 아니다. 숨이다. 손 한 뼘 앞에서 누가 숨을 쉰다.<br><br>
    치면 닿는다. 닿으면 그것도 이쪽을 안다.`,
  o:[
    { l:'① 숨이 오는 한가운데로 곧장 지른다.', k:'break', dc:23,
      ok:`주먹을 허리에서 뽑아 곧장 질렀다. 숨이 오는 한가운데로.<br><br>닿았다. 차고 무르다. 젖은 천에 싼 무엇. 주먹이 반쯤 들어가다 멈췄다. 그것이 뒤로 밀려난다. 숨이 끊겼다. 발소리가 멀어진다. 맨발이다.<br>주먹을 폈다. 손등에 물기가 묻었다. 차다. 물기가 아니다. 서리다.`,
      ng:`질렀는데 숨이 옆으로 비켰다. 주먹이 허공을 지났다. 그 팔을 무엇이 잡았다. 손목을.<br><br>손가락이 손목을 한 바퀴 돌고도 남는다. 길다. 당긴다. 앞으로. 발을 버텨 뺐다. 손목 살갗이 쓸렸다.<br>손목에 손가락 자국이 감겨 있다. 손목을 다 감고도 엄지가 한 마디 더 남은 자국이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 주먹을 풀고 손바닥을 벽에 대 울림을 듣는다.', k:'sense', dc:22, wake:1,
      ok:`주먹을 풀고 손바닥을 벽에 댔다. 숨을 아랫배로 내리고 손바닥을 열었다. 벽이 운다. 아주 작게.<br><br>일행 발소리가 벽을 타고 온다. 그 사이에 다른 울림이 하나 있다. 가볍다. 앞쪽 다섯 걸음. 벽에 등을 기대고 서 있다. 숨 쉴 때마다 벽이 그만큼 운다.<br>반대쪽 벽으로 붙어 지나갔다. 울림이 따라오지 않았다.<br><br>치려고 단련한 손이 듣는다. 돌을 백 번 친 손바닥은 돌의 떨림을 안다. 손바닥이 귀가 되는 법을 알았다. 닿지 않고도 아는 법. 주먹이 처음 배운 다른 일이다.`,
      ng:`손바닥을 대는 순간 벽 저쪽에서도 손바닥이 닿았다. 같은 자리에. 벽 너머에서.<br><br>울림이 아니라 체온이 온다. 차다. 손을 떼려는데 벽이 손바닥을 놓지 않는다. 언 쇠에 살이 붙듯.<br>당겨 떼었다. 손바닥 살갗이 얇게 벗겨졌다. 벽에 이쪽 손바닥 자국이 남았다. 그 옆에 작은 손바닥 자국.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'③ 내공을 쓴다 — 마보로 서서 그것이 먼저 오기를 기다린다.', k:'steady', dc:22, cost:{ qi:26 },
      ok:`발을 넓게 딛고 무릎을 굽혔다. 내공을 아랫배에서 발바닥으로 내렸다. 땅에 뿌리가 내린다.<br><br>숨이 다가온다. 손가락 끝에 무엇이 닿았다. 그것이 이쪽을 민다. 밀어 넘어뜨려 보려는 듯. 안 밀렸다. 서 있는 것을 넘어뜨리려면 이쪽보다 무거워야 한다.<br>그것이 물러났다. 일행이 뒤에서 불을 들고 왔다. 앞에는 아무것도 없다. 바닥에 젖은 발자국만 뒷걸음친 모양으로 남았다.`,
      ng:`내공을 내리는데 숨이 먼저 왔다. 뿌리가 다 내리기 전에.<br><br>가슴을 밀었다. 한 손으로. 아이 손만 한데 무겁다. 뒤로 넘어졌다. 넘어진 이쪽 위로 무엇이 지나간다. 발이 가슴을 밟고 간다. 가볍게. 여럿이.<br>일어났다. 가슴에 작은 발자국이 찍혔다. 젖은 발자국. 숨이 한동안 얕았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18, qi:-5 } }
  ] },

{ at:'A1', t:'로비 — 팔을 벌린 뭉치',
  x:`로비 한가운데 뭉치 탈이 서 있다. 두 팔을 벌렸다. 안아 주려는 자세다.<br><br>
    지나갈 길이 탈 앞뿐이다. 다가가면 팔이 닫힌다. 아까 일행 중 하나가 멀리 돌아가려 하자 탈이 한 걸음 옮겨 섰다.<br>
    털옷이다. 솜이 두껍다. 주먹으로 치면 솜이 받는다. 겉을 쳐서는 안에 안 닿는다.<br><br>
    탈 안에서 숨소리가 난다. 아주 고르다.`,
  o:[
    { l:'① 내공을 쓴다 — 장으로 솜 너머 안을 친다.', k:'break', dc:23, cost:{ qi:28 }, wake:1,
      ok:`다가가 팔이 닫히기 직전에 손바닥을 탈 가슴에 붙였다. 숨을 내리꽂았다. 내공이 손바닥을 지나 솜을 지나 안으로 간다.<br><br>털옷은 멀쩡하다. 안에서 무엇이 꺾였다. 고른 숨이 끊겼다. 벌린 팔이 천천히 내려온다. 탈이 그대로 무릎을 꿇었다. 안에 든 것만 쓰러졌다.<br><br>겉을 치지 않고 속을 친다. 말로는 늘 알았다. 솜 두께만큼 내공이 기다렸다가 터지는 걸 손바닥이 느꼈다. 그 기다림의 길이를 이제 잰다. 두꺼운 것 너머에도 손이 닿는다.`,
      ng:`손바닥을 붙였는데 내공이 솜에서 흩어졌다. 너무 두껍다. 숨이 솜에 다 먹혔다.<br><br>팔이 닫혔다. 안겼다. 털 속이 덥다. 좀약 냄새. 안에서 누가 이쪽 등을 토닥인다. 잘 왔어.<br>팔꿈치로 탈 옆구리를 찍고 빠져나왔다. 가슴이 조였다 풀리며 숨이 쏟아졌다. 등에 토닥인 자리가 차다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22, qi:-5 } },
    { l:'② 팔이 닫히는 순간 밑으로 빠진다.', k:'evade', dc:22,
      ok:`정면으로 걸어갔다. 팔이 닫힌다. 그 순간 무릎을 꺾어 바닥에 몸을 붙였다. 팔이 이쪽 머리 위에서 저 자신을 안았다.<br><br>탈 다리 사이로 굴러 지나갔다. 뒤에서 털옷이 저를 꼭 끌어안고 서 있다. 안에서 아쉬운 숨이 났다.<br>일어나 무릎을 털었다. 일행도 하나씩 그렇게 지났다. 탈은 마지막 사람이 지날 때까지 팔을 풀지 않았다.`,
      ng:`몸을 낮췄는데 탈도 같이 낮아졌다. 무릎을 굽혀. 팔이 낮게 닫힌다. 어깨까지 안겼다.<br><br>털이 얼굴을 덮는다. 숨이 막힌다. 안에서 무엇이 귀에 대고 속삭인다. 이번엔 놓치지 않을게.<br>주먹으로 탈 옆구리를 세 번 쳤다. 솜만 들어간다. 일행이 뒤에서 잡아당겨 겨우 빠졌다. 귀에 그 목소리가 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-20 } },
    { l:'③ 서서 맞받는다 — 안기는 순간 버틴다.', k:'steady', dc:23,
      doom:{ title:'포옹', what:'뭉치 탈에 안긴 채 실려 갑니다', dc:18, sec:45,
        text:`버티고 섰다. 팔이 닫힌다. 안겼다. 팔꿈치로 밀었다. 털옷이 늘어나기만 한다.<br><br>탈이 이쪽을 안은 채 돌아선다. 발이 바닥에서 뜬다. 털 속에서 누가 이쪽 등을 토닥인다. 토닥, 토닥. 걷는다. 무대로 가는 계단 쪽으로.<br>소리를 지르려는데 털이 입을 막는다. 털 속은 따뜻하다. 너무 따뜻해서 눈이 감긴다.<br><br>주먹을 쥐려는데 손가락이 털에 감겨 안 쥐어진다.`,
        dieText:`로비 한가운데 뭉치 탈이 다시 섰다. 두 팔을 벌리고.<br><br>털이 아까보다 조금 부풀었다. 안에서 숨소리가 둘이다. 고르게.<br>로비 텔레비전에 방글 동산이 나온다. 뭉치가 손을 흔든다. 손가락이 넷인데 하나가 덜 접힌다.` },
      ok:`버티고 섰다. 팔이 닫히는 순간 두 팔꿈치를 바깥으로 벌렸다. 안기지 않고 끼었다. 탈 팔과 이쪽 팔꿈치가 맞섰다.<br><br>털 안의 팔은 세다. 그래도 팔꿈치가 뼈를 찾았다. 털 너머 단단한 데. 거기를 눌렀다. 탈 팔이 풀린다.<br>뒷걸음으로 빠졌다. 탈이 빈 팔을 벌린 채 서 있다. 다음 사람을 기다린다. 다들 멀리 돌아갔다. 이번엔 탈이 안 따라왔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'교실동 — 물을 건너는 장',
  x:`교실동 복도 물이 허리까지다. 물속에서 주먹은 느리다. 지르면 물이 주먹을 붙든다.<br><br>
    앞쪽 물이 일어선다. 사람 키만큼. 물인데 모양이 있다. 어깨, 머리. 그것이 이쪽으로 걸어온다. 물속을 걷는데 물결이 안 인다.<br>
    맨손으로 싸우는 사람은 다리로 친다. 다리가 물에 잠겼다.<br><br>
    그것과의 거리가 다섯 걸음이다.`,
  o:[
    { l:'① 내공을 쓴다 — 물에 손바닥을 대고 장을 흘려 보낸다.', k:'break', dc:23, cost:{ qi:30 }, wake:1,
      ok:`주먹을 지르지 않았다. 손바닥을 물에 대고 숨을 내리꽂았다. 내공이 손바닥에서 물로 간다.<br><br>물이 한 번 떨었다. 그 떨림이 줄을 그으며 앞으로 간다. 다섯 걸음. 일어선 물에 닿았다. 그것이 터지듯 무너졌다. 그냥 물이 됐다. 복도 물이 한 번 크게 출렁였다.<br><br>장은 손바닥으로 닿아야 하는 줄 알았다. 물이 이어져 있으면 물이 손바닥이다. 다섯 걸음 앞까지 손이 닿았다. 내공이 물을 타는 길을 손이 기억한다. 물이 이쪽 편이 될 수도 있다.`,
      ng:`손바닥을 물에 댔다. 내공을 흘렸다. 물이 떨었다. 그런데 그 떨림이 앞이 아니라 사방으로 퍼졌다.<br><br>복도 물이 다 떨었다. 교실 안 물도. 교실마다 물이 일어선다. 하나, 둘, 여섯. 다 이쪽을 본다.<br>일행 손을 잡고 계단까지 물을 헤쳤다. 일어선 것들이 천천히 따라왔다. 계단 위로는 안 올라왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-24, qi:-5 } },
    { l:'② 물을 헤치고 들어가 맞붙는다.', k:'break', dc:23,
      doom:{ title:'물로 선 것', what:'물로 된 팔에 끌어안겨 가라앉습니다', dc:18, sec:50,
        text:`물을 헤치고 들어갔다. 그것의 가슴께를 주먹으로 질렀다. 주먹이 그대로 들어갔다. 물이니까.<br><br>들어간 주먹을 물이 쥔다. 팔꿈치까지 삼킨다. 그것이 이쪽을 안는다. 물로 된 팔로. 차다. 안긴 채 그것이 무너진다. 이쪽을 데리고.<br>복도 물에 같이 잠겼다. 바닥으로 끌린다. 물이 몸에 꼭 맞게 감긴다. 숨이 빠져나간다.<br><br>주먹을 빼려는데 주먹이 물을 쥐고 있다. 물은 쥐어도 안 잡힌다.`,
        dieText:`복도 물이 잔잔해졌다.<br><br>조금 뒤에 물이 다시 일어섰다. 사람 키만큼. 어깨, 머리. 이번엔 주먹을 쥐고 있다.<br>그것이 교실 쪽으로 걸어간다. 물결 하나 일으키지 않고.` },
      ok:`헤치고 들어가되 지르지 않았다. 그것 가슴께에 주먹이 닿기 직전에 손을 펴서 물을 옆으로 밀었다.<br><br>물이 갈라진다. 그것이 반으로 쪼개져 양쪽으로 무너진다. 잡을 데가 없다. 물로 된 것은 치는 게 아니라 흩는 것이다.<br>무너진 물을 지나갔다. 뒤에서 물이 다시 모이는 소리가 났다. 계단을 오를 때까지 돌아보지 않았다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 발을 넓게 딛고 물살을 등지고 선다.', k:'steady', dc:22,
      ok:`발을 넓게 딛고 바닥에 박았다. 물살을 등졌다. 그것이 다가온다. 이쪽 등에 닿는다.<br><br>밀린다. 버텼다. 그것이 이쪽을 넘어 지나간다. 물이 등을 타고 넘는다. 머리 위로. 차다. 숨을 참았다.<br>그것이 이쪽 앞으로 넘어갔다. 그리고 계속 갔다. 이쪽을 바위로 알았다. 숨을 쉬었다. 등이 얼음처럼 차다.`,
      ng:`버텼는데 바닥이 미끄럽다. 물 밑 타일에 물때가 끼었다. 발이 밀린다.<br><br>그것이 이쪽을 넘어 지나가며 발목을 쓸었다. 넘어졌다. 물속에서 그것의 안쪽이 보였다. 아이들 얼굴이 여럿 눌려 있다. 다들 눈을 감았다.<br>일행이 끌어올렸다. 그 얼굴들이 눈꺼풀 안쪽에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 운기 속의 다른 숨',
  x:`다들 누웠다. 권사는 앉는다. 다리를 꼬고 손을 무릎에 놓는다. 숨을 아랫배로 내린다.<br><br>
    내공이 돈다. 배에서 등으로, 등에서 머리로, 다시 배로. 늘 같은 길이다.<br>
    오늘은 그 길에 다른 숨이 섞였다. 이쪽 숨이 돌 때 같이 돈다. 반 박자 늦게. 작고 차다.<br><br>
    누가 등 뒤에 붙어 앉아 같이 숨을 쉰다. 등에 닿는 것은 없는데.`,
  o:[
    { l:'① 내공을 쓴다 — 숨을 거꾸로 돌려 떼어 낸다.', k:'steady', dc:23, cost:{ qi:27 },
      ok:`내공을 멈췄다. 그리고 거꾸로 돌렸다. 머리에서 등으로, 등에서 배로. 다른 숨이 따라오다 엉킨다.<br><br>엉킨 숨이 등에서 떨어져 나간다. 등 뒤가 빈다. 한숨 같은 바람이 목덜미를 스쳤다.<br>다시 바르게 돌렸다. 이번엔 이쪽 숨 하나다. 거꾸로 돌린 길이 쑤신다. 그래도 제 숨이다.`,
      ng:`거꾸로 돌리는데 다른 숨은 엉키지 않았다. 같이 거꾸로 돈다. 이쪽보다 먼저.<br><br>내공이 가슴에서 막혔다. 숨이 거꾸로 올라온다. 기침이 터졌다. 입에서 차가운 김이 나왔다. 이쪽 숨이 아니다.<br>운기를 멈추고 누웠다. 밤새 등이 시렸다. 등 뒤에서 계속 누가 숨을 쉬었다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-22, spirit:-26, qi:-5 } },
    { l:'② 일어나 누운 동료들 숨을 하나씩 짚는다.', k:'heal', dc:22,
      ok:`운기를 멈추고 일어났다. 누운 동료들 곁을 돌며 가슴 위에 손을 대 보았다. 한 사람씩. 숨이 고르다.<br><br>마지막 동료 숨이 이상하다. 반 박자 늦다. 작고 차다. 아까 그 숨이다. 동료 가슴에 손바닥을 대고 따뜻한 기운을 조금 흘렸다. 차가운 숨이 동료 가슴에서 빠져나간다.<br>동료 숨이 제 박자로 돌아왔다. 동료는 깨지 않았다. 손바닥이 한참 차다.`,
      ng:`숨을 짚어 가는데 숨이 다 반 박자씩 늦다. 동료 모두가. 다른 숨을 하나씩 등에 업고 있다.<br><br>어느 것부터 떼야 할지 모른다. 손이 떨렸다. 떨리는 손이 동료 하나를 깨웠다. 동료가 눈을 떴다. 눈동자가 이쪽을 안 본다. 이쪽 등 뒤를 본다.<br>돌아봤다. 아무것도 없다. 동료는 다시 눈을 감았다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'분장실 — 거울 안쪽의 주먹',
  x:`분장실 전구 거울에 일행이 비친다. 이쪽도.<br><br>
    거울 속 이쪽이 주먹을 쥐고 있다. 이쪽은 손을 펴고 있다. 거울 속 주먹이 유리를 친다. 안쪽에서. 톡.<br>
    유리에 금이 간다. 이쪽 주먹 마디만 한 금. 거울 속 이쪽이 다시 주먹을 든다.<br><br>
    이쪽이 매일 아침 하는 일이다. 같은 자리를 백 번 친다. 돌이 지는 날까지.`,
  o:[
    { l:'① 같은 자리를 바깥에서 맞받아 친다.', k:'break', dc:23,
      ok:`거울 속 주먹이 들어오는 순간 같은 자리를 바깥에서 쳤다. 주먹과 주먹이 유리 한 장을 사이에 두고 만났다.<br><br>유리가 깨지지 않았다. 금이 거꾸로 닫혔다. 두 힘이 같으면 가운데는 버틴다. 거울 속 이쪽이 주먹을 쥔 채 멈췄다. 처음으로 이쪽과 같은 얼굴이다. 아프다는 얼굴.<br>손을 거뒀다. 거울 속 이쪽도 거뒀다. 마디가 둘 다 터졌다.`,
      ng:`맞받아 쳤는데 반 박자 늦었다. 거울 속 주먹이 먼저 닿았다. 금이 이쪽 주먹 쪽으로 번졌다.<br><br>유리는 안 깨졌는데 이쪽 마디가 갈라졌다. 금 모양 그대로. 피가 거울에 튄다. 거울 안쪽에.<br>거울 속 이쪽이 그 피를 손가락으로 찍어 맛본다. 웃는다. 거울을 등지고 나왔다. 마디가 금 모양으로 아물었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 전구를 하나씩 비틀어 끈다.', k:'fix', dc:22,
      ok:`거울 테두리 전구를 하나씩 비틀어 껐다. 거울이 어두워진다. 비친 것이 흐려진다.<br><br>마지막 전구를 끄자 거울에 아무것도 안 비친다. 주먹 소리도 멎었다. 비치지 않는 것은 칠 수 없다.<br>캄캄한 분장실을 더듬어 빠져나왔다. 손끝에 전구 열기가 남았다. 데었다. 그래도 됐다.`,
      ng:`전구를 비트는데 거울 속 이쪽이 같은 전구를 안쪽에서 비튼다. 반대로. 꺼진 전구가 다시 켜진다.<br><br>비틀고, 켜지고. 손가락이 덴다. 거울 속 이쪽은 안 덴다. 다시 주먹을 든다. 톡. 금이 하나 더.<br>그냥 돌아섰다. 등 뒤에서 금 가는 소리가 따라왔다. 분장실 문을 닫을 때까지.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'기숙사 — 점호 전의 마보',
  x:`밤 아홉 시 점호가 다가온다. 침대 옆에 서라고 벽에 적혀 있다. 차렷.<br><br>
    바닥 물이 발목까지다. 서 있으면 발목에 무엇이 와서 감긴다. 살짝. 서 있는지 확인하듯이.<br>
    서는 법은 제일 오래 배웠다. 차렷은 배운 적이 없다. 마보는 안다.<br><br>
    열쇠 소리가 복도 끝에서 가까워진다. 찰랑, 찰랑.`,
  o:[
    { l:'① 차렷 대신 마보로 선다.', k:'steady', dc:22,
      ok:`발을 어깨보다 넓게 딛고 무릎을 굽혔다. 허리를 세웠다. 마보다. 발목에 감기는 것이 와서 당긴다. 안 넘어간다.<br><br>문이 열리고 센다. 세는 손이 이쪽 앞에서 멈칫한다. 자세가 이상하다. 그래도 서 있다. 딸깍. 세어졌다.<br>열쇠 소리가 지나갔다. 발목에 감기던 것도 물러났다. 무릎이 떨린다. 오래 선 떨림이 아니라 오래 버틴 떨림이다.`,
      ng:`마보로 섰는데 문가의 것이 이쪽 자세를 오래 본다. 차렷이 아니다.<br><br>발목에 감긴 것이 한 번 세게 당긴다. 바르게 서라고. 무릎이 펴졌다. 다리가 모였다. 차렷이 됐다. 몸이 저절로.<br>점호가 끝날 때까지 차렷으로 서 있었다. 다리가 남의 것 같다. 풀어 보니 발목에 끈 자국. 실내화 끈 모양.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 문 옆에 붙어 열쇠 든 손목을 친다.', k:'break', dc:23,
      ok:`문 옆 벽에 붙었다. 문이 열리는 순간 열쇠 꾸러미를 든 손목을 손날로 쳤다.<br><br>손목은 안 보인다. 그런데 맞았다. 꾸러미가 물에 떨어진다. 복도에서 무엇이 꾸러미를 찾아 물을 더듬는다. 맞은 손이 아픈지 한쪽 손만 쓴다.<br>그 호실은 세지 않고 지나갔다. 손날이 저렸다. 맞은 손목은 아이 손목만큼 가늘었다.`,
      ng:`손날로 쳤는데 맞은 것은 손목이 아니라 열쇠 꾸러미였다. 쇠가 손날을 벴다.<br><br>찰랑. 꾸러미가 공중에서 흔들린다. 그 소리에 침대 밑 물이 일제히 출렁인다. 점호 시간에 문 옆에 붙은 학생이 하나 있다.<br>침대 밑에서 손들이 나와 이쪽 발목을 쥐고 침대 옆 자리로 데려다 세웠다. 반듯하게. 발목에 손자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'계단 — 발바닥으로 오는 울림',
  x:`계단을 내려간다. 신발을 벗었다. 맨발로 짚으면 발바닥이 더 많이 안다.<br><br>
    계단이 운다. 이쪽 발소리 말고 다른 울림이 있다. 계단 밑에서. 느리게. 쿵, 쉬고, 쿵.<br>
    계단 밑에 무엇이 있다. 크다. 이쪽 발소리에 맞춰 울림이 한 칸씩 따라 내려온다.<br><br>
    밑에서 계단을 받치고 있는 것인지 계단 밑을 기어가는 것인지 모른다.`,
  o:[
    { l:'① 울림이 올 때만 발을 디뎌 발소리를 묻는다.', k:'evade', dc:23, wake:1,
      ok:`밑의 울림을 발바닥으로 셌다. 쿵, 쉬고, 쿵. 쿵이 올 때 발을 디뎠다. 이쪽 발소리가 밑의 울림에 묻힌다.<br><br>밑의 것이 따라 내려오다 멈춘다. 발소리가 사라졌다. 이쪽이 어디 있는지 모른다. 쿵, 쉬고, 쿵. 혼자 운다.<br>일행에게도 박자를 손으로 알려 줬다. 다 같이 쿵에 맞춰 내려갔다.<br><br>발바닥은 땅을 짚는 데라고만 알았다. 발바닥이 듣는다. 듣는 발은 디딜 때를 고른다. 걸음이 소리를 숨기는 법을 알았다. 발목이 그 박자를 벌써 제 것으로 쓴다.`,
      ng:`쿵에 맞춰 디뎠는데 밑의 것이 박자를 바꿨다. 쉬는 데에 이쪽 발이 떨어졌다. 툭.<br><br>밑이 조용해진다. 그리고 바로 이쪽 발밑에서 쿵. 계단이 들썩인다. 발바닥으로 무엇이 밀어 올린다. 계단 판 하나가 들렸다.<br>뛰어내렸다. 아래층 바닥에 떨어져 발목을 접질렸다. 위에서 들린 계단 판이 천천히 제자리로 내려앉았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 울림이 오는 칸을 내려찍어 눌러 놓는다.', k:'break', dc:22,
      ok:`울림이 한 칸 앞 계단 밑으로 왔을 때 그 칸을 내려찍었다. 주먹으로. 판이 꺼지며 밑의 것을 눌렀다.<br><br>밑에서 무엇이 움찔했다. 울림이 끊겼다. 한참 조용하다가 아주 멀리서 쿵. 물러났다.<br>남은 계단을 내려갔다. 주먹 마디에 나무 가시가 박혔다. 뽑으니 가시가 아니라 머리카락 한 올이다.`,
      ng:`내려찍었는데 판이 꺼지지 않고 튀었다. 밑에서 마주 쳤다. 이쪽 주먹 힘 그대로.<br><br>손목이 꺾였다. 판이 들썩이며 틈이 났다. 틈 사이로 눈 하나가 이쪽을 본다. 크다. 계단 한 칸만 하다.<br>눈을 피해 뛰었다. 아래층에 닿을 때까지 발밑에서 쿵이 따라왔다. 손목이 부어올랐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 마디에 남은 찬 기운',
  x:`쉬는 틈에 주먹을 봤다. 아까 무엇을 친 마디다.<br><br>
    마디가 하얗다. 차다. 찬 기운이 뼛속에 남았다. 조금씩 손등으로, 손목으로 번진다. 얼음물이 스미듯.<br>
    친 것은 손에 남는다. 단단한 걸 치면 손이 단단해지고 뜨거운 걸 치면 손이 덴다. 이건 처음이다.<br><br>
    손목까지 왔다. 손가락이 굽혀지지 않는다.`,
  o:[
    { l:'① 내공을 쓴다 — 찬 기운을 손끝으로 몰아낸다.', k:'steady', dc:23, cost:{ qi:28 },
      ok:`숨을 아랫배에 모았다. 내공을 팔로 올려 손목에서 찬 기운을 밀었다. 손등으로, 마디로, 손끝으로.<br><br>손끝에 물방울이 맺힌다. 차갑다. 바닥에 떨어지자 얼음 조각이 됐다. 하나, 둘, 다섯. 손가락 수만큼.<br>손이 풀렸다. 주먹이 쥐어진다. 얼음 조각들이 바닥에서 녹지 않는다. 다섯 개가 작은 손가락 모양이다.`,
      ng:`밀어내는데 찬 기운이 거꾸로 올라온다. 내공을 타고. 팔꿈치까지 시리다.<br><br>내공을 멈췄다. 찬 기운이 어깨 밑에서 멈춘다. 이쪽 내공 길을 알았다. 거기 앉아 있다.<br>한참 팔을 주물렀다. 팔이 천천히 녹았다. 어깨 밑 한 점은 끝까지 차다.`,
      win:{ exp:20, dream:3, hp:6 }, lose:{ hp:-22, spirit:-24, qi:-5 } },
    { l:'② 불 가까이 손을 대고 천천히 녹인다.', k:'heal', dc:22,
      ok:`불 옆에 손을 댔다. 너무 가까이는 안 된다. 얼었던 손은 갑자기 데우면 터진다.<br><br>조금씩 녹였다. 손목, 손등, 마디. 하얗던 데가 붉어진다. 아프다. 아픈 건 살아난다는 뜻이다.<br>마디만 마지막까지 하얬다. 녹이고 녹이니 그것도 돌아왔다. 주먹을 쥐었다 폈다. 내일도 친다.`,
      ng:`녹이는 사이 찬 기운이 불 쪽으로 손을 뻗는다. 이쪽 손을 빌려서. 손가락이 저절로 불 속으로 들어간다.<br><br>데었다. 그래도 손가락이 안 빠진다. 불을 쥐려 한다. 차가운 것은 따뜻한 걸 쥐고 싶어 한다.<br>동료가 이쪽 팔을 잡아 뺐다. 손끝 셋이 데었다. 마디는 여전히 하얗다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 찬 주먹으로 돌벽을 백 번 친다.', k:'break', dc:23,
      ok:`벽 앞에 섰다. 찬 주먹으로 쳤다. 한 번. 열 번. 마흔 번째쯤 마디가 뜨거워졌다. 돌을 친 열이다.<br><br>찬 기운이 열에 밀려난다. 백 번째에 마디가 붉다. 벽에 주먹 자국이 백 개. 그중 처음 몇 개에만 서리가 꼈다.<br>주먹을 쥐어 봤다. 제 주먹이다. 친 것이 남긴 것은 더 쳐서 지운다. 권사가 아는 방법은 그것뿐이다.`,
      ng:`쳤다. 칠 때마다 벽에 서리가 낀다. 찬 기운이 벽으로 옮겨 간다. 그런데 벽에서 이쪽으로 돌아온다.<br><br>오십 번째에 벽이 하얗게 얼었다. 언 벽에 주먹이 붙었다. 떼려니 살갗이 같이 온다.<br>떼었다. 마디가 다 터졌다. 터진 데서 피가 안 난다. 얼었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 어깨를 누르는 손',
  x:`방청석에 앉았다. 서 있으면 바람잡이가 가리키니까.<br><br>
    뒷줄 빈 의자에서 손이 나와 이쪽 어깨에 얹힌다. 작은 손 둘. 꼭 누른다. 일어나지 말라는 듯이.<br>
    무대 쪽 스피커가 센다. 녹화 시작 일 분 전. 녹화가 시작되면 앉은 사람은 다 방청객이 된다. 방청객은 다음 회에도 온다.<br><br>
    어깨를 누르는 손이 조금씩 세진다.`,
  o:[
    { l:'① 어깨 위 손가락 마디를 젖혀 푼다.', k:'break', dc:23, wake:1,
      ok:`주먹을 풀었다. 손을 올려 어깨 위 작은 손을 잡았다. 제일 굵은 마디를 찾아 바깥으로 젖혔다.<br><br>쥐던 손이 펴진다. 쥐는 힘은 한 마디에서 나온다. 그 마디가 풀리면 다 풀린다. 다른 손도 그렇게 풀었다. 일어섰다. 뒷줄에서 쉿, 하는 소리가 났다.<br><br>주먹은 쥐는 것이었다. 남이 쥔 것을 푸는 데도 손이 쓰인다. 어디를 젖히면 쥔 손이 펴지는지 손가락이 알았다. 붙잡히는 것이 전처럼 무섭지 않다.`,
      ng:`엄지를 찾아 젖히려는데 엄지가 없다. 손가락이 넷뿐이다. 젖힐 데를 못 찾았다.<br><br>작은 손이 더 세게 누른다. 엉덩이가 의자에 눌러 붙는다. 일 분 전. 삼십 초 전.<br>일행이 이쪽 팔을 잡아 끌어올렸다. 어깨에서 손이 미끄러져 떨어졌다. 어깨에 손가락 넷 자국이 둘. 녹화는 이쪽 없이 시작됐다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 앉은 척 엉덩이를 띄우고 무릎으로 버틴다.', k:'steady', dc:22,
      ok:`숨을 아래로 내렸다. 누르는 손이 원하는 대로 앉아 있는 척했다. 다만 엉덩이를 아주 조금 들어 의자에 닿지 않게 했다. 무릎으로 버텼다.<br><br>녹화가 시작됐다. 박수. 방청석이 다 박수를 친다. 이쪽도 쳤다. 앉은 자세로 떠서.<br>녹화가 끝날 때까지 그렇게 떠 있었다. 앉지 않은 사람은 방청객이 아니다. 끝나고 일어서니 다리가 후들거린다.`,
      ng:`버텼는데 의자가 이쪽을 끌어당긴다. 앉으라고. 엉덩이가 닿았다. 따뜻하다. 누가 방금까지 앉아 있던 온기다.<br><br>녹화가 시작됐다. 손이 저절로 박수를 친다. 웃음이 저절로 나온다. 일행이 이쪽 뺨을 쳤다.<br>정신이 들었다. 녹화는 계속된다. 기어서 방청석을 빠져나왔다. 손바닥이 박수로 얼얼했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 돌아서서 뒷줄을 친다.', k:'break', dc:23,
      doom:{ title:'뒷줄의 친구들', what:'뒷줄 손들에게 의자 너머로 끌려갑니다', dc:18, sec:45,
        text:`몸을 틀어 뒷줄을 쳤다. 빈 의자 등받이가 부서진다. 손이 어깨에서 떨어졌다.<br><br>뒷줄 손들이 한꺼번에 나온다. 둘이 아니다. 뒷줄 전부. 그 뒷줄도. 작은 손들이 이쪽 옷깃을, 팔을, 머리카락을 쥔다.<br>뒤로 당긴다. 등받이 너머로. 뒷줄로, 그 뒷줄로. 방청석은 뒤로 갈수록 어둡다. 맨 뒷줄은 안 보인다.<br><br>주먹을 휘두르는데 맞는 손마다 하나씩 더 붙는다.`,
        dieText:`녹화가 시작됐다. 박수.<br><br>맨 뒷줄에 방청객이 하나 늘었다. 박수를 아주 세게 친다. 주먹을 쥔 채로.<br>다음 회에도 그 자리에 있었다. 그다음 회에도.` },
      ok:`몸을 틀어 등받이 너머로 손날을 그었다. 어깨 위 손목 둘을 한 번에. 손이 떨어졌다. 바로 일어나 통로로 뛰었다.<br><br>뒷줄에서 손들이 일제히 나온다. 이쪽이 앉았던 자리를 쥔다. 비었다. 손들이 빈 의자를 한참 쓰다듬다 들어갔다.<br>통로 끝에 섰다. 녹화가 시작됐다. 박수. 통로에 선 사람은 방청객이 아니다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'체육관 — 손가락 두 마디 공기',
  x:`체육관이 물에 잠겼다. 천장 철골 밑에만 공기가 한 줄 남았다. 어떤 데는 한 뼘, 어떤 데는 손가락 두 마디.<br><br>
    건너편까지 가려면 공기가 끊기는 데를 지나야 한다. 숨을 참고 열 번은 저어야 한다.<br>
    끊긴 자리 물속에 손이 떠 있다. 손바닥을 위로 하고. 잡아 주기를 기다린다.<br><br>
    숨은 오래 다뤄 왔다. 운기할 때는 한 숨을 백까지 늘인다.`,
  o:[
    { l:'① 내공을 쓴다 — 한 숨을 백으로 늘여 끊긴 데를 지난다.', k:'steady', dc:23, cost:{ qi:30 }, wake:1,
      ok:`철골 밑 공기에서 숨을 크게 들이쉬었다. 내공으로 그 숨을 아랫배에 눌러 담았다. 숨이 몸 안에서 천천히 돈다. 아주 느리게.<br><br>물속으로 들어갔다. 끊긴 자리를 저어 갔다. 떠 있는 손 위로. 손이 이쪽 그림자를 따라 돈다. 서두르지 않았다. 숨이 아직 반이나 남았다.<br>건너편 공기에 머리를 냈다. 숨을 내쉬었다. 길었다.<br><br>운기는 앉아서 하는 줄 알았다. 물속에서도 돈다. 숨 한 번을 늘이는 법이 움직이는 몸 안에서도 된다. 가슴이 그 박자를 잊지 않을 것이다.`,
      ng:`숨을 눌러 담았는데 물이 차서 내공이 얼었다. 숨이 갑자기 빨라진다. 열이 아니라 셋에서.<br><br>가슴이 터질 것 같다. 떠 있던 손이 그걸 안다. 이쪽 손목을 잡는다. 잡아 주려는 게 아니다. 잡히려는 거다.<br>뿌리치고 위로 차올랐다. 철골 밑 두 마디 공기에 코만 댔다. 물을 반 먹었다. 손목에 손자국.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-18, qi:-5 } },
    { l:'② 철골을 손끝으로 짚으며 옆으로 이어 간다.', k:'evade', dc:22,
      ok:`철골에 손끝을 걸었다. 돌을 짚어 온 손끝이다. 철골 이음매마다 손끝을 박으며 옆으로 갔다. 머리는 공기에.<br><br>공기가 끊긴 자리에서 숨을 들이쉬고 철골을 짚은 채 얼굴을 물에 담갔다. 손끝으로 당겨 갔다. 다섯 번. 떠 있는 손이 손끝 바로 밑에 있다. 짚지 않았다.<br>다음 공기에 머리를 냈다. 손끝 살갗이 다 벗겨졌다. 철골에 피가 점점이 찍혔다.`,
      ng:`손끝을 박다 철골 녹이 부서졌다. 손이 빠졌다. 물에 떨어졌다.<br><br>떠 있던 손이 이쪽 손을 잡는다. 반갑게. 아래로 당긴다. 바닥 쪽으로. 체육관 바닥에 그려진 원이 보인다.<br>일행이 철골에 매달려 이쪽 머리카락을 잡아 끌어올렸다. 두피가 아프다. 손바닥에 작은 손 자국이 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-24 } }
  ] },

{ at:'A', t:'문 — 손바닥 자국이 빼곡한 문',
  x:`문 하나가 손바닥 자국으로 빼곡하다. 안쪽에서 찍은 자국이다. 크기가 다 다르다. 작은 게 많다.<br><br>
    한가운데 빈 자리가 있다. 손바닥 하나 들어갈 만큼. 그 자리만 나뭇결이 깨끗하다.<br>
    크기를 대 보니 이쪽 손바닥에 꼭 맞을 것 같다. 굳은살 박인 데까지.<br><br>
    문 너머에서 누가 기다린다. 손바닥이 맞기를.`,
  o:[
    { l:'① 빈 자리를 장으로 치고 바로 거둔다.', k:'break', dc:23,
      ok:`빈 자리에 손바닥을 붙이지 않았다. 한 뼘 떨어져서 숨을 모으고 쳤다. 장이 닿는 순간 손을 거뒀다.<br><br>문이 안쪽으로 움푹 꺼졌다. 빈 자리에 이쪽 손바닥 자국이 찍혔다. 그런데 손은 이미 거기 없다. 문 너머가 손을 잡으려다 허공을 쥐었다.<br>문이 저절로 열렸다. 맞는 손바닥이 찍혔으니까. 안은 비었다. 손을 품에 넣고 지나갔다.`,
      ng:`쳤는데 거두는 게 늦었다. 손바닥이 문에 닿은 채 반 박자 머물렀다.<br><br>문 너머에서 손가락이 문을 뚫고 나와 이쪽 손가락 사이에 깍지를 꼈다. 나무가 물처럼 무르다. 꼭 쥔다.<br>당겨 뺐다. 손가락 사이 살이 찢어졌다. 문 빈 자리에 이쪽 손바닥 자국이 남았다. 피 묻은 채로. 문은 안 열렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 자국들 크기를 재어 문 너머가 무엇인지 짚는다.', k:'gaze', dc:22,
      ok:`손바닥 자국을 하나씩 손가락으로 쟀다. 작은 것이 아래에, 큰 것이 위에. 키 순서다. 줄을 선 것처럼.<br><br>맨 위 자국은 어른 손이다. 그 손은 손가락이 넷. 다른 손들을 위에서 누르는 자리다.<br>문 너머에 무엇이 있는지 알았다. 이 문은 열면 안 된다. 다른 길로 돌았다. 돌아서는데 문 너머에서 손바닥 하나가 문을 쓰다듬는 소리가 났다.`,
      ng:`재다가 손가락 하나가 자국에 닿았다. 자국이 따뜻하다. 방금 찍힌 것이다.<br><br>문 너머에서 그 자국에 손바닥을 마주 댄다. 문을 사이에 두고 이쪽 손가락에. 손끝이 저리다. 손가락이 문에 붙었다.<br>떼었다. 손끝 살갗이 문에 남았다. 지문 하나가 자국들 사이에 섞였다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'놀이 세트 — 작은 집',
  x:`놀이 세트에 작은 집이 있다. 아이 키만 하다. 지붕이 빨갛다. 다음 문으로 가려면 이 집을 지나야 한다.<br><br>
    안은 좁다. 팔을 뻗을 수 없다. 주먹을 지를 자리가 없다.<br>
    안쪽에서 엄마 목소리가 난다. 녹음이다. 어서 들어와, 밥 먹자. 작은 식탁에 플라스틱 그릇이 놓였다.<br><br>
    넓은 데서 싸우는 법을 배웠다. 지금은 무릎으로 기어야 한다.`,
  o:[
    { l:'① 팔꿈치와 어깨로 길을 내며 기어 지난다.', k:'break', dc:23,
      doom:{ title:'작은 집', what:'좁아지는 작은 집 안에 끼었습니다', dc:18, sec:45,
        text:`기어 들어갔다. 팔꿈치로 식탁을 밀어냈다. 그릇이 쏟아진다. 엄마 목소리가 멈췄다.<br><br>집이 좁아진다. 벽이 안으로 들어온다. 천장이 내려온다. 어서 들어와. 목소리가 다시 난다. 녹음이 아니다. 가깝다.<br>팔꿈치로 벽을 쳤다. 안 밀린다. 어깨가 끼었다. 무릎이 가슴에 붙었다. 아이 자세로 접힌다.<br><br>숨이 가슴 안에서 갈 데가 없다.`,
        dieText:`작은 집이 원래 크기로 돌아왔다. 빨간 지붕.<br><br>안쪽 작은 식탁에 누가 앉아 있다. 무릎을 가슴에 붙이고. 주먹을 쥐고. 플라스틱 그릇 앞에서.<br>엄마 목소리가 말한다. 잘 먹네. 녹음이다.` },
      ok:`기어 들어가며 팔꿈치를 몸에 붙였다. 지르지 않고 짧게 밀었다. 어깨로, 팔꿈치로. 좁은 데서 쓰는 짧은 힘.<br><br>벽이 안으로 들어오려다 이쪽 팔꿈치에 막힌다. 그 틈에 반대쪽 문으로 기어 나왔다. 엄마 목소리가 등 뒤에서 섭섭해한다. 밥 다 먹고 가지.<br>뒤를 보니 작은 집 문이 닫혀 있다. 안에서 그릇 놓는 소리가 났다. 하나 더 차리는 소리.`,
      win:{ exp:22, dream:3 } },
    { l:'② 집에 들어가지 않고 지붕을 짚고 넘는다.', k:'evade', dc:22,
      ok:`집에 들어가지 않았다. 지붕을 손으로 짚고 넘었다. 플라스틱 지붕이 휘청거린다. 가볍게 넘었다.<br><br>지붕 너머에 내려섰다. 집 창문에서 엄마 목소리가 난다. 어디 가니. 대답하지 않았다.<br>일행도 하나씩 지붕을 넘었다. 마지막 사람이 넘을 때 창문 안에서 작은 손이 나와 신발 끈을 당겼다. 끈만 풀렸다.`,
      ng:`지붕을 짚었는데 지붕이 꺼졌다. 플라스틱이 깨지며 집 안으로 떨어졌다.<br><br>작은 식탁 앞에 앉혀졌다. 그릇에 무엇이 담겼다. 젖은 모래다. 엄마 목소리가 말한다. 잘 먹겠습니다 해야지.<br>입을 꾹 다물고 기어 나왔다. 무릎이 깨졌다. 입가에 모래가 묻었다. 언제 묻었는지 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'③ 몸을 작게 접어 식탁 밑으로 조용히 지난다.', k:'hide', dc:23,
      ok:`숨을 가늘게 하고 몸을 접었다. 어깨를 안으로 말고 무릎을 모았다. 오래 단련한 몸이라 접히는 데까지 접힌다.<br><br>기어 들어가 식탁 밑으로 지났다. 엄마 목소리가 식탁 위에 대고 말한다. 어서 들어와. 식탁 밑은 안 본다.<br>반대쪽 문으로 나왔다. 몸을 펴는 데 뼈마디가 다 소리를 냈다. 아이 몸으로 접혔다 펴진 것 같다.`,
      ng:`접었는데 어깨가 안 접힌다. 넓다. 식탁 다리에 걸렸다. 식탁이 흔들려 그릇이 떨어진다.<br><br>엄마 목소리가 멈춘다. 식탁 밑을 들여다보는 기척. 그리고 손이 들어와 이쪽 머리를 쓰다듬는다. 거기 있었구나.<br>몸을 비틀어 빠져나왔다. 머리카락 몇 가닥이 그 손에 남았다. 집 안에서 머리 빗는 소리가 났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'조리실 — 서리 낀 저장고',
  x:`조리실은 물이 가슴까지다. 구석 저장고 문은 물 위로 나와 있다. 그런데 문이 하얗다. 서리다. 물 위인데 얼었다.<br><br>
    문틈으로 찬 바람이 나온다. 안에 무엇이 아직 차게 보관되어 있다. 생선 냄새가 난다. 상하지 않은 냄새다.<br>
    손잡이에 얼음이 꽉 끼었다. 당겨서는 안 열린다.<br><br>
    주먹은 얼음을 깬다. 다만 안에서 무엇이 문을 붙들고 있으면 얼음보다 질기다.`,
  o:[
    { l:'① 손잡이 얼음을 마디로 깨고 연다.', k:'break', dc:22,
      ok:`손잡이 둘레 얼음을 마디로 짧게 쳤다. 세 번. 얼음이 쩍 갈라진다. 손잡이를 당겼다. 열렸다.<br><br>안이 하얗다. 선반 위에 생선이 줄지어 얼어 있다. 민물고기다. 학교 연못에서 잡은 것 같다. 꼬리표에 날짜가 있다. 물이 들어오기 전날.<br>두 마리를 품에 넣고 문을 닫았다. 닫히기 직전에 안쪽 선반 끝에 작은 실내화 한 짝이 보였다. 얼어 있다.`,
      ng:`쳤는데 얼음이 아니라 문 안쪽에서 무엇이 마주 친다. 똑같이 세 번.<br><br>문이 안쪽에서 밀려 열렸다. 찬 바람이 쏟아져 얼굴을 덮는다. 눈썹에 서리가 앉는다. 숨을 쉬니 폐가 언다.<br>문을 발로 차서 닫았다. 한참 숨을 못 쉬었다. 주먹에 서리가 꼈다. 안쪽에서 친 자리 모양으로.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 문은 두고 물속 식탁 밑 상자를 더듬는다.', k:'sense', dc:22,
      ok:`저장고 문은 두었다. 물속 식탁 밑을 발로 더듬었다. 발끝에 나무 상자가 걸린다. 들어 올렸다.<br><br>밀랍으로 봉한 상자다. 안이 말랐다. 말린 고기 꾸러미가 들었다. 소풍 날 나눠 주려던 것 같다. 꾸러미마다 반 번호가 적혔다.<br>저장고 문에서 서리가 조금 녹는 소리가 났다. 그쪽을 안 연 것이 다행인지도 모른다.`,
      ng:`더듬는데 발끝에 걸린 것이 상자가 아니다. 무르다. 발을 뺐다. 그것이 발목을 따라 올라온다.<br><br>손이다. 물속에서 이쪽 다리를 짚고 올라온다. 무릎까지. 허벅지까지. 일행이 이쪽을 식탁 위로 끌어올렸다.<br>다리에 젖은 손자국이 줄줄이 났다. 위로 올라오는 방향으로.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A', t:'잠자리 — 깍지 낀 손',
  x:`자다가 깼다. 손이 따뜻하다. 누가 손을 잡고 있다.<br><br>
    옆 동료인 줄 알았다. 동료는 등을 돌리고 자고 있다. 두 손을 가슴에 모으고.<br>
    잡은 손은 작다. 손가락이 이쪽 손가락 사이로 깍지를 꼈다. 꼭. 놓지 않는다.<br><br>
    깍지를 낀 손은 주먹을 쥘 수가 없다.`,
  o:[
    { l:'① 깍지 낀 채 손가락 마디로 조여 먼저 풀게 한다.', k:'break', dc:23, wake:1,
      ok:`깍지를 풀려 하지 않았다. 오히려 이쪽 손가락을 조였다. 사이에 낀 작은 손가락들을 마디로 눌렀다.<br><br>깍지는 둘이 같이 쥐는 것이다. 한쪽이 더 세게 쥐면 다른 쪽이 아프다. 작은 손이 움찔한다. 그래도 버틴다. 조금 더 조였다. 작은 손이 먼저 풀었다.<br><br>주먹을 못 쥐면 쓸 손이 없는 줄 알았다. 펴진 손가락 하나하나가 다 주먹이다. 마디로 누르는 법을 손이 알았다. 손이 펴져 있어도 이쪽은 비어 있지 않다.`,
      ng:`조였는데 작은 손도 조인다. 같은 힘으로. 손가락뼈가 서로 갈린다. 소리가 난다.<br><br>아프다. 이쪽만 아프다. 작은 손은 아픈 걸 모른다. 결국 이쪽이 먼저 풀었다. 작은 손이 놓지 않고 따라온다.<br>새벽까지 손을 잡힌 채 누워 있었다. 해가 들 무렵 손이 사라졌다. 손가락 사이가 다 멍들었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 잡힌 채 일어나 앉아 잡힌 손까지 내공을 돌린다.', k:'steady', dc:22,
      ok:`손을 놔두고 일어나 앉았다. 숨을 아랫배로 내렸다. 운기하듯이. 잡힌 손까지 따뜻한 기운을 돌렸다.<br><br>그 기운이 손을 타고 작은 손으로 간다. 작은 손이 조금씩 풀린다. 다 데워지자 저절로 놓았다. 잡고 있던 게 추워서였는지도 모른다.<br>손을 거뒀다. 손바닥이 아직 따뜻하다. 남은 밤 앉아서 지냈다.`,
      ng:`일어나 앉으니 작은 손도 같이 일어난다. 손이 이쪽을 따라 올라온다. 팔도 없이.<br><br>운기를 하려는데 작은 손이 이쪽 숨을 같이 쉰다. 손바닥으로. 이쪽 내공이 손바닥에서 빠져나간다.<br>억지로 비틀어 뺐다. 엄지가 빠질 뻔했다. 손바닥이 차다. 내공이 한 바퀴 비었다.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 동료를 깨워 그 손을 같이 본다.', k:'bond', dc:22,
      ok:`잡힌 손 반대쪽 손으로 동료 어깨를 흔들었다. 동료가 돌아본다. 이쪽 손을 본다.<br><br>동료가 말없이 이쪽 잡힌 손 위에 제 손을 얹었다. 세 손이 됐다. 작은 손이 머뭇거린다. 손이 너무 많다. 하나씩 손가락을 빼고 사라졌다.<br>동료는 아무 말도 안 하고 다시 누웠다. 이쪽 손을 쥔 채. 그 손은 따뜻했다.`,
      ng:`동료를 깨웠다. 동료가 이쪽 잡힌 손을 본다. 그리고 이쪽 얼굴을 본다. 무슨 손? 아무것도 없는데.<br><br>내려다보니 정말 아무것도 없다. 이쪽 손이 허공에 깍지를 끼고 있다. 그런데 손가락 사이가 꽉 차 있다.<br>동료가 다시 누웠다. 허공을 쥔 채 남은 밤을 보냈다. 아침에 손가락 사이에 젖은 흙이 끼어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'통로 — 끌려가는 동료',
  x:`동료가 바닥에 엎어져 어둠 쪽으로 미끄러진다. 발목에 무엇이 감겼다. 소리가 안 나온다.<br><br>
    쓸 손이 둘이다. 주먹으로 쓸지 손으로 쓸지 고르는 것이 늘 먼저다.<br>
    당기는 쪽은 안 보인다. 다만 바닥이 울린다. 당길 때마다. 발바닥으로 그 울림이 온다.<br><br>
    동료 손이 바닥을 긁는다. 손톱이 하나 들렸다.`,
  o:[
    { l:'① 동료 허리를 안고 마보로 버틴다.', k:'steady', dc:23,
      doom:{ title:'뿌리째 뽑힌 발', what:'동료를 안은 채 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`동료 허리를 두 팔로 안았다. 발을 넓게 딛고 무릎을 굽혔다. 마보. 바닥에 뿌리를 내렸다.<br><br>당기는 힘이 온다. 버틴다. 다시 온다. 버틴다. 세 번째에 바닥이 이쪽 발밑에서 미끄러진다. 바닥 자체가 움직인다. 타일 한 장째 당겨진다.<br>뿌리를 내린 땅이 통째로 끌려간다. 동료를 안은 채 미끄러진다. 어둠 쪽으로.<br><br>발을 빼면 뿌리가 풀린다. 풀리면 더 빨리 간다.`,
        dieText:`통로 끝에서 일행이 타일 한 장을 찾았다.<br><br>타일 위에 발자국이 둘 찍혀 있다. 넓게 벌려 디딘 자국. 깊다. 버틴 자국이다.<br>발자국 앞으로 다른 발자국은 없다.` },
      ok:`동료 허리를 안고 마보로 섰다. 당기는 힘이 오는 박자를 발바닥으로 셌다. 당길 때 버티고, 쉴 때 한 걸음 물러났다.<br><br>당기고, 버티고. 쉬고, 물러나고. 다섯 번째에 당기는 쪽이 지쳤다. 발목의 것이 풀렸다. 동료와 같이 뒤로 넘어졌다.<br>동료가 숨을 몰아쉰다. 이쪽 무릎이 떨린다. 바닥에 이쪽 발자국이 다섯 쌍 찍혔다. 다 조금씩 뒤로.`,
      win:{ exp:23, dream:3 } },
    { l:'② 내공을 쓴다 — 바닥을 쳐 울림을 거꾸로 보낸다.', k:'break', dc:22, cost:{ qi:30 },
      ok:`바닥에 무릎을 꿇고 손바닥을 댔다. 당기는 울림이 오는 박자에 맞춰 내공을 바닥에 꽂았다. 울림을 거꾸로 보냈다.<br><br>바닥이 한 번 크게 울렸다. 그 울림이 어둠 쪽으로 달려간다. 어둠 속에서 무엇이 튕겨 나가는 소리. 동료 발목이 풀렸다.<br>동료를 끌어당겼다. 손바닥이 저리다. 바닥 타일이 이쪽 손바닥 자리부터 어둠 쪽으로 한 줄로 금이 갔다.`,
      ng:`내공을 꽂았는데 바닥이 울림을 삼켰다. 아무 일도 없다. 동료가 한 길 더 끌려갔다.<br><br>뛰어가 동료 손목을 잡았다. 맨손으로 버텼다. 손바닥이 바닥에 쓸려 벗겨졌다. 일행이 다 붙었다. 겨우 멈췄다.<br>동료 발목에 감겼던 것이 풀려 어둠으로 들어갔다. 긴 머리카락 한 타래다. 이쪽 손바닥에 피가 뱄다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18, qi:-5 } },
    { l:'③ 어둠으로 뛰어들어 감긴 데를 손날로 끊는다.', k:'break', dc:23,
      ok:`동료 다리를 따라 어둠으로 뛰어들었다. 발목에서 이어진 것을 손으로 더듬어 잡았다. 젖고 가늘다. 여러 가닥이다. 손날로 그었다.<br><br>끊어졌다. 당기던 쪽이 갑자기 가벼워져 어둠 속에서 넘어지는 소리가 났다. 작은 것이 엉덩방아를 찧는 소리.<br>동료를 업고 돌아왔다. 손날에 머리카락이 감겼다. 풀어도 한 가닥은 손가락에 남았다.`,
      ng:`뛰어들어 더듬었는데 잡히는 게 없다. 어둠 속은 손이 안 닿는 데가 더 많다.<br><br>그사이 이쪽 발목에도 무엇이 감겼다. 둘이 같이 당겨진다. 손날로 이쪽 발목 것을 그었다. 끊어졌다. 동료 것은 못 끊었다.<br>일행이 동료를 붙잡아 끌어냈다. 다들 숨이 턱까지 찼다. 이쪽 발목에 감긴 자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A1', t:'7층 복도 — 박수 칠 준비',
  x:`7층 복도다. 스피커가 센다. 생방송 일 분 전.<br><br>
    복도 끝에 스튜디오 문이 있다. 문 위에 빨간 등. 방송 중. 아직 꺼져 있다.<br>
    복도 양쪽 벽에 인형탈들이 줄지어 섰다. 손을 반쯤 벌렸다. 지나가는 사람에게 박수를 쳐 준다. 박수를 받은 사람은 출연자다.<br><br>
    이쪽 손은 주먹을 쥔다. 손뼉을 치는 손이 아니다.`,
  o:[
    { l:'① 탈들이 손을 모으기 전에 손목을 쳐 낸다.', k:'break', dc:23,
      ok:`걸으면서 양쪽 탈들 손목을 하나씩 손날로 쳤다. 박수를 치려고 모으는 손이 벌어진다. 짝이 안 난다.<br><br>탈들이 서로 맞지 않는 손을 쳐다본다. 박수 소리가 비어 있다. 복도 끝까지 그렇게 갔다. 손날이 털에 쓸려 화끈하다.<br>스튜디오 문 앞에 섰다. 빨간 등이 켜지지 않았다. 박수를 받지 않은 사람은 출연자가 아니다.`,
      ng:`손목을 쳤는데 탈 손목이 털 속에서 미끄러진다. 박수가 터진다. 짝. 짝. 짝.<br><br>이쪽을 향해 박수가 쏟아진다. 빨간 등이 켜진다. 방송 중. 몸이 저절로 스튜디오 문 쪽으로 돈다.<br>일행이 이쪽 팔을 잡아 벽으로 끌어붙였다. 박수가 지나갔다. 다음 사람을 기다린다. 등이 땀으로 젖었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 손이 모이는 박자를 보고 그 사이로 지난다.', k:'evade', dc:22,
      ok:`주먹을 꽉 쥐고 탈 손이 모이는 박자를 봤다. 하나가 모일 때 옆 것은 벌어진다. 그 사이를 지났다.<br><br>박수 소리가 이쪽 등 뒤에서 난다. 앞에서는 안 난다. 박수는 지나간 자리에 친다. 지나간 것에게는 소용이 없다.<br>복도 끝에 닿았다. 뒤를 보니 탈들이 빈 복도에 대고 박수를 친다. 아무도 없는데.`,
      ng:`지나가는데 탈 하나가 박수 대신 이쪽 주먹을 감싸 쥔다. 두 손으로. 축하하듯이.<br><br>주먹이 털 속에 잡혔다. 탈이 이쪽 주먹을 들어 올린다. 이긴 사람 팔을 들듯. 스피커가 외친다. 오늘의 친구!<br>팔을 비틀어 뺐다. 털이 손목에 엉켰다. 박수가 쏟아지는 사이로 뛰었다. 손목에 감긴 털이 오래 안 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A2', t:'수영장 — 다이빙대',
  x:`수영장 물이 천장 바로 밑까지 찼다. 다이빙대만 물 위로 나왔다. 그 끝에 서야 다음 통로가 보인다.<br><br>
    다이빙대 끝 판이 젖었다. 판 끝에 발가락 자국이 열 개. 뛰어내린 자리다. 수십 번 덧찍혔다.<br>
    밑에서 물이 부른다. 소리 없이. 물결이 동그랗게 밀려와 다이빙대 기둥을 친다. 뛰어 보라는 듯이.<br><br>
    통로 입구는 맞은편 벽 물속이다. 뛰어서 들어가야 한다.`,
  o:[
    { l:'① 판 끝에서 힘껏 뛰어 통로로 곧장 들어간다.', k:'evade', dc:23,
      doom:{ title:'다이빙대 아래', what:'수영장 바닥으로 끌려 가라앉습니다', dc:18, sec:45,
        text:`판 끝에 발가락을 맞추고 뛰었다. 몸이 물을 찢고 들어간다. 깊다.<br><br>통로 쪽으로 차려는데 발이 무엇을 찼다. 손이다. 손이 발을 잡는다. 또 하나. 다이빙대 밑에서 손들이 줄지어 기다리고 있었다. 뛰어든 아이를 받아 주려고.<br>받아서 내린다. 아래로. 바닥으로. 손에서 손으로. 다이빙대 밑 바닥에 작은 발자국 같은 것이 줄지어 찍혀 있다.<br><br>주먹을 쥐어 손을 치는데 물속에서는 주먹이 느리다.`,
        dieText:`다이빙대 끝 판에 발가락 자국이 열 개 더 찍혔다.<br><br>물결이 동그랗게 밀려와 기둥을 친다. 다음 사람을 부른다.<br>통로 입구 물속에 손 하나가 떠 있다. 주먹을 쥐고.` },
      ok:`뛰기 전에 다이빙대 밑을 봤다. 물이 기둥 둘레에서만 무겁다. 거기를 피해 판 옆에서 비스듬히 뛰었다.<br><br>물을 찢고 들어갔다. 다이빙대 밑에서 손들이 이쪽으로 뻗는다. 닿지 않는다. 비스듬히 뛴 만큼 멀다. 발차기 세 번에 통로 입구를 잡았다.<br>통로 안 공기에 머리를 냈다. 돌아보니 다이빙대 밑 손들이 아직 위를 향해 벌어져 있다. 똑바로 뛰어내릴 아이를 기다린다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 다이빙대 기둥을 타고 물속으로 내려간다.', k:'steady', dc:22,
      ok:`뛰지 않았다. 기둥을 손과 다리로 감고 천천히 내려갔다. 숨을 참고.<br><br>기둥 둘레 손들이 이쪽을 만진다. 뛰어든 게 아니라 내려오는 것이다. 받아 줄 수가 없다. 손들이 어리둥절해서 이쪽 옷자락만 쥐었다 놓는다.<br>바닥 가까이에서 통로 쪽으로 기둥을 차고 갔다. 숨이 다 됐을 때 통로에 닿았다. 옷이 여기저기 늘어났다.`,
      ng:`기둥을 타고 내려가는데 기둥이 미끄럽다. 물때가 끼었다. 손이 빠졌다.<br><br>떨어졌다. 손들이 받았다. 반갑게. 바닥으로 데려간다. 주먹을 쥐어 내리쳤다. 손 하나가 놓고 둘이 잡는다.<br>일행이 다이빙대에서 줄을 내려 끌어올렸다. 바닥에서 반쯤 올라왔을 때 손들이 놓아줬다. 숨이 끊기기 직전이었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 느려지는 심장',
  x:`귀를 막고 있으면 심장 소리가 들린다. 운기 때는 그 소리로 박자를 잰다.<br><br>
    오늘은 심장이 느리다. 쿵. 한참. 쿵. 점점 길어진다.<br>
    그 사이에 다른 소리가 있다. 손뼉 같은 소리. 짝. 심장 박자에 맞춰. 아니, 심장이 그 박자에 맞춰 간다.<br><br>
    짝이 느려지면 쿵도 느려진다.`,
  o:[
    { l:'① 심장 박자를 제 숨으로 다시 붙잡는다.', k:'steady', dc:23, wake:1,
      ok:`숨을 아랫배로 내렸다. 운기할 때의 숨으로. 들이쉬고 넷, 내쉬고 넷. 그 박자에 심장을 묶었다.<br><br>짝이 느려진다. 심장은 따라가지 않는다. 이쪽 숨 박자로 뛴다. 쿵, 쿵. 짝 소리가 박자를 놓치고 헤맨다. 한참 헤매다 그쳤다.<br><br>숨이 심장을 끌고 간다. 반대인 줄 알았다. 숨을 다루는 사람은 심장도 다룬다. 가슴 안 박자를 제 손에 쥐는 법을 숨이 알았다. 다른 박자가 이쪽 안으로 들어오지 못한다.`,
      ng:`숨으로 묶으려는데 숨도 같이 느려진다. 짝, 하고 쉬고, 들이쉬고. 숨까지 그 박자를 따라간다.<br><br>눈앞이 어두워진다. 몸이 무겁다. 동료가 이쪽 얼굴을 보고 놀라서 흔들었다. 입술이 파랗다고 했다.<br>동료가 가슴을 세게 쳤다. 심장이 놀라 빨리 뛰었다. 짝이 멈췄다. 한참 숨이 가빴다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-26 } },
    { l:'② 손뼉 소리 나는 데를 찾아 친다.', k:'break', dc:22,
      ok:`귀에서 손을 뗐다. 짝 소리가 어디서 나는지 들었다. 이쪽 등 뒤. 벽 쪽. 아주 가깝다.<br><br>돌아서며 손등으로 벽 앞 허공을 쳤다. 무엇이 맞았다. 작고 차다. 손뼉 치던 손이다. 짝 소리가 끊겼다. 심장이 저 혼자 빨라진다. 놀란 만큼.<br>손등에 차가운 손바닥 자국이 남았다. 두 개. 손뼉 치던 손 둘이다.`,
      ng:`쳤는데 허공이다. 짝 소리는 계속된다. 이번엔 가슴 안에서 난다.<br><br>손이 가슴을 친다. 이쪽 손이. 저절로. 짝, 쿵. 짝, 쿵. 이쪽 손이 이쪽 심장 박자를 잡는다. 느리게.<br>일행이 이쪽 두 손목을 붙잡았다. 손이 멈췄다. 가슴에 손바닥 자국이 붉게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'벽 — 안에서 치는 주먹',
  x:`벽 안쪽에서 소리가 난다. 퍽. 퍽. 일정하다. 주먹으로 벽을 치는 소리다.<br><br>
    그 소리를 안다. 매일 아침 이쪽이 내는 소리다. 같은 자리를 백 번. 박자까지 같다.<br>
    소리 나는 자리 벽에 금이 가 있다. 안쪽에서 바깥으로 불룩하다. 곧 뚫린다.<br><br>
    지금 마흔한 번째다. 이쪽이 세고 있었다.`,
  o:[
    { l:'① 같은 자리를 바깥에서 같이 쳐 준다.', k:'break', dc:22,
      ok:`금 간 자리 앞에 섰다. 안쪽 주먹이 칠 때 바깥에서도 쳤다. 같은 박자로. 퍽, 퍽.<br><br>예순 번째에 안쪽 주먹이 멈췄다. 이쪽도 멈췄다. 벽 너머에서 숨소리가 난다. 지친 숨. 이쪽 숨과 같다.<br>벽 너머에서 한 번 더 쳤다. 아주 약하게. 고맙다는 박자다. 그리고 조용해졌다. 금은 그 뒤로 더 벌어지지 않았다.`,
      ng:`같이 쳤다. 일흔 번째에 벽이 뚫렸다. 이쪽 주먹이 벽을 뚫고 들어갔다. 저쪽 주먹과 마주쳤다.<br><br>저쪽 주먹이 이쪽 주먹을 쥔다. 차다. 마디가 다 터져 있다. 백 번은 넘게 친 주먹이다. 당긴다. 벽 안으로.<br>뺐다. 팔이 벽 구멍에 긁혔다. 구멍 안이 캄캄하다. 거기서 다시 퍽. 이번엔 이쪽 얼굴 높이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 금 간 자리를 손바닥으로 막고 백까지 버틴다.', k:'steady', dc:23,
      ok:`금 간 자리에 손바닥을 대고 버텼다. 안쪽 주먹이 칠 때마다 손바닥이 울린다. 뼈까지 온다.<br><br>백 번째까지 버텼다. 안쪽 주먹이 멈췄다. 백 번 치면 오늘 몫은 끝이다. 권사는 그걸 안다. 저쪽도 안다.<br>손을 뗐다. 손바닥이 퉁퉁 부었다. 벽은 안 뚫렸다. 내일 아침에 다시 칠 것이다. 그때는 이쪽이 여기 없다.`,
      ng:`버텼는데 안쪽 주먹이 이쪽 손바닥 박자를 안다. 손바닥이 들썩일 때 친다. 정확히.<br><br>손바닥 뼈가 울려 손목까지 저리다. 일흔 번째에 손이 튕겨 나갔다. 벽에 금이 벌어졌다. 틈으로 눈 하나가 이쪽을 본다.<br>틈을 등지고 걸었다. 걸음마다 벽 안에서 퍽 소리가 따라왔다. 손목이 한참 저렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A', t:'마지막 방 — 닿아야 치는 것',
  x:`마지막 방 한가운데 무엇이 서 있다. 사람 셋 키다. 몸이 젖은 천으로 감겼다. 천 사이로 손이 여러 개 삐져나와 있다.<br><br>
    그것이 일행을 향해 걸어온다. 걸을 때마다 바닥이 언다.<br>
    무기를 든 사람은 멀리서 친다. 맨손은 닿아야 친다. 닿으면 언다.<br><br>
    가까이 가야 한다. 다른 수는 없다.`,
  o:[
    { l:'① 내공을 쓴다 — 몸에 내공을 두르고 들어가 한 점을 친다.', k:'break', dc:23, cost:{ qi:33 }, wake:1,
      ok:`숨을 끌어올려 온몸에 내공을 둘렀다. 살갗 위에 얇은 막처럼. 그것의 찬 기운이 막에서 멈춘다.<br><br>들어갔다. 천 사이 손들이 이쪽을 잡는다. 막에서 미끄러진다. 천이 겹친 한가운데를 봤다. 숨이 거기서 나온다. 거기를 쳤다. 한 점에 내공을 다 모아서.<br>천이 한꺼번에 풀렸다. 안에 든 것이 무너진다. 손들이 바닥에 떨어져 하나씩 녹는다.<br><br>내공은 몸 안에서 도는 것인 줄 알았다. 몸 바깥에도 두를 수 있다. 막 하나만큼. 찬 것에 닿아도 이쪽은 안 언다. 손이 이제 무엇에든 닿을 수 있다.`,
      ng:`내공을 둘렀는데 막이 얇다. 손 하나가 막을 뚫고 들어와 팔을 쥐었다. 거기서부터 언다.<br><br>그래도 쳤다. 한 점이 아니라 그 근처를. 그것이 비틀거린다. 무너지지는 않는다. 손들이 이쪽 몸을 감는다. 일행이 뒤에서 당겨 냈다.<br>팔이 하얗게 얼었다. 녹이는 데 오래 걸렸다. 그것은 다시 걸어온다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26, qi:-5 } },
    { l:'② 맨주먹으로 정면에서 지른다.', k:'break', dc:24,
      doom:{ title:'언 주먹', what:'닿은 데부터 얼어붙어 숨이 멎습니다', dc:19, sec:40,
        text:`정면으로 들어가 주먹을 질렀다. 그것의 가슴에 닿았다. 깊이 들어갔다.<br><br>주먹이 안 빠진다. 닿은 데부터 언다. 마디가, 손등이, 손목이. 하얗게. 천 사이 손들이 이쪽 어깨를, 목을 쥔다.<br>얼음이 팔꿈치를 넘어 어깨로 온다. 가슴으로. 숨이 얼어 들어간다. 뱉어지지 않는다.<br><br>주먹을 쥔 채로 굳는다. 지른 자세 그대로.`,
        dieText:`방 한가운데 얼음 기둥 하나가 서 있다.<br><br>안에 사람이 주먹을 지른 자세로 들어 있다. 마디가 하얗다. 주먹 앞에는 아무것도 없다. 그것은 떠났다.<br>권사의 주먹은 닿아야 친다. 닿은 채로 남았다.` },
      ok:`정면으로 들어가 주먹을 질렀다. 닿는 순간 바로 거뒀다. 닿은 시간이 숨 반 번도 안 된다.<br><br>얼 틈이 없다. 지르고 거두고, 지르고 거두고. 같은 자리를 빠르게. 그것의 가슴에 금이 간다. 얼음 깨지는 소리. 그것이 무릎을 꿇었다.<br>스무 번째에 무너졌다. 주먹 마디가 하얗게 얼었다가 붉게 돌아온다. 손등에 서리가 꼈다. 털어 냈다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 일행 앞에 서서 뻗어 오는 손들을 하나씩 쳐 낸다.', k:'steady', dc:23,
      ok:`일행 앞에 섰다. 그것이 다가온다. 천 사이 손들이 일행을 향해 뻗는다. 하나씩 손날로 쳐 냈다. 닿자마자 거두면서.<br><br>쳐 낸 손이 바닥에 떨어진다. 녹는다. 손이 줄어든다. 그것이 걸음을 멈췄다. 손이 없으면 데려갈 수가 없다.<br>그것이 물러났다. 손날이 얼어 감각이 없다. 감각이 없는 손으로 끝까지 섰다.`,
      ng:`쳐 냈다. 셋, 넷. 다섯째 손이 손날을 피해 이쪽 손목을 잡았다. 언다.<br><br>잡힌 손목을 비틀어 뺐다. 살갗이 얼음에 붙어 같이 떨어졌다. 그사이 다른 손이 일행 하나의 어깨를 쥐었다. 다들 붙어 떼어 냈다.<br>그것은 한 발 물러섰다. 이쪽 손목이 하얗다. 다시 온다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-18 } }
  ] }

]);

// ------------------------------------------
// 폭파공 · 자원 없음
// ------------------------------------------
kJob('blaster', 'A', [

{ at:'A', t:'복도 — 들리지 않으면 안 불린다',
  x:`복도 저편에서 이름이 불린다. 일행 이름이 하나씩. 이 동료 목소리로, 저 동료 목소리로.<br><br>
    불린 사람은 고개를 든다. 대답하려고 입술이 움직인다. 아직 아무도 대답하지 않았다.<br>
    폭파공 귀는 늘 조금 운다. 터뜨린 만큼 운다. 울리는 동안은 작은 소리가 안 들린다.<br><br>
    다음은 이쪽 이름 차례다.`,
  o:[
    { l:'① 손톱만 한 화약을 터뜨려 다 같이 귀를 먹는다.', k:'break', dc:22, wake:1,
      ok:`화약 한 꼬집을 돌 틈에 넣고 일행에게 손짓했다. 입을 벌려라. 귀는 막지 마라.<br><br>퍽. 작고 날카로운 소리. 복도가 한 번 하얗게 울렸다. 그다음은 웅웅 소리뿐이다. 다들 서로 입 모양만 본다. 이름이 불리는지 안 불리는지 아무도 모른다.<br>들리지 않으면 대답할 수 없다. 울림이 가라앉기 전에 복도를 다 지났다.<br><br>귀가 먹는 건 이 일의 값인 줄 알았다. 값이 방패가 될 때가 있다. 얼마를 넣으면 얼마 동안 먹는지 손이 쟀다. 들으면 안 되는 것을 안 듣게 하는 법. 화약으로 하는 일이 하나 늘었다.`,
      ng:`터뜨렸는데 화약이 덜 말랐다. 소리가 둔하다. 귀가 반만 먹었다.<br><br>반만 먹은 귀로 이름이 들어온다. 오히려 또렷하게. 다른 소리가 다 지워져서 그 목소리만 남았다.<br>입술이 저절로 움직였다. 네, 하고. 소리가 나기 전에 손바닥으로 입을 막았다. 손바닥에 입김이 차갑게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 발뒤꿈치로 바닥을 쳐 울림으로 거리를 잰다.', k:'sense', dc:22,
      ok:`발뒤꿈치로 바닥을 쳤다. 한 번. 울림이 저쪽으로 갔다가 돌아오는 박자를 셌다. 터뜨릴 자리를 고를 때 하는 버릇이다.<br><br>복도는 스무 걸음. 끝에 빈 방이 있다. 목소리는 그 방에서 나온다. 방이 텅 비어 소리가 크게 울린다. 소리만 크다. 거기 있는 것은 작다.<br>방문 앞을 지날 때 다들 귀를 막았다. 문틈으로 작은 그림자가 이쪽을 봤다. 입만 움직였다.`,
      ng:`쳤는데 울림이 안 돌아온다. 저쪽에서 누가 받았다. 발로.<br><br>쿵. 똑같은 세기로 저쪽에서 바닥을 친다. 쿵. 점점 가까이서. 이쪽 버릇을 따라 한다.<br>일행을 데리고 뛰었다. 등 뒤에서 바닥이 쿵쿵 울렸다. 이름이 그 박자에 실려 불렸다. 다들 귀를 막고 달렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 대답하려는 동료 입을 막고 끌고 지난다.', k:'bond', dc:23,
      doom:{ title:'불린 이름', what:'제 이름에 대답하고 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`동료 입을 손으로 막았다. 끌고 걸었다. 그때 이쪽 이름이 불렸다. 바로 귀 옆에서.<br><br>네. 대답이 나왔다. 이쪽 입에서. 동료 입을 막느라 제 입을 못 막았다.<br>대답한 것은 간다. 발이 저절로 돈다. 복도 끝 어둠으로. 동료가 이쪽 팔을 잡는다. 발이 동료 손을 끌고 간다.<br><br>귀가 우는 날은 괜찮았다. 오늘은 귀가 맑았다.`,
        dieText:`일행이 복도를 다 지났을 때 하나가 모자랐다.<br><br>복도 저편에서 다시 이름이 불린다. 이번엔 새 목소리가 하나 섞였다. 조금 쉰 목소리. 귀가 먹은 사람이 크게 말하는 목소리.<br>그 목소리가 일행 이름을 하나씩 부른다. 또박또박.` },
      ok:`동료 입을 손으로 막았다. 다른 손으로는 제 귀를 막았다. 자기 이름부터 안 들어야 한다.<br><br>이름이 불린다. 동료 이름. 동료 입술이 손바닥 안에서 움직인다. 소리는 안 나간다. 그대로 끌고 복도를 지났다.<br>복도를 나와 손을 뗐다. 동료가 숨을 몰아쉬며 이쪽을 본다. 하마터면 대답할 뻔했다고. 손바닥이 침으로 젖었다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A1', t:'중앙 계단 — 따라오는 박수',
  x:`중앙 계단을 오른다. 한 층 오를 때마다 아래층에서 박수가 터진다. 짝짝짝. 한 층씩 따라온다.<br><br>
    박수는 오늘의 친구를 맞는 소리다. 박수가 이쪽 층까지 따라붙으면 박수 속에 선 사람이 친구가 된다.<br>
    박수는 소리다. 소리는 소리로 덮는다. 화약 쓰는 사람의 셈이다.<br><br>
    계단참에 오래된 소화기 하나가 서 있다. 바늘이 빨간 칸에 있다.`,
  o:[
    { l:'① 소화기에 화약을 감아 아래층에서 터뜨린다.', k:'break', dc:23,
      ok:`소화기 꼭지에 화약을 감고 심지를 길게 뺐다. 아래층 계단참으로 굴려 보냈다. 불을 붙이고 위로 뛰었다.<br><br>쾅. 하얀 가루가 아래층을 채운다. 박수가 그 소리에 묻혔다. 한참 아무 소리도 안 났다. 그다음 박수가 다시 났다. 엉뚱한 층에서. 가루 속에서 박자를 잃었다.<br>한 층을 더 올랐다. 박수는 더 안 따라왔다. 귀가 운다. 이 정도는 괜찮다.`,
      ng:`굴려 보냈는데 소화기가 계단 중간에서 멈췄다. 심지는 타 들어간다. 너무 가깝다.<br><br>쾅. 가루가 이쪽 층까지 올라왔다. 숨을 쉬면 가루가 들어온다. 기침이 터진다. 기침 사이로 박수가 바로 옆에서 난다. 짝짝짝. 가루 속에서 하얀 장갑들이 손뼉을 친다.<br>눈을 감고 계단을 기어올랐다. 박수가 발목까지 따라오다 멈췄다. 목이 따갑다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 박수 박자를 세어 쉬는 틈에 한 층씩 오른다.', k:'sense', dc:22,
      ok:`박수를 셌다. 짝짝짝, 쉬고, 짝짝짝. 심지 타는 박자를 세듯이. 쉬는 틈은 숨 세 번.<br><br>쉬는 틈마다 한 층씩 올랐다. 박수는 이쪽이 떠난 층에서 친다. 언제나 한 층 늦다.<br>꼭대기에 닿았다. 아래에서 박수가 마지막으로 한 번 났다. 아무도 없는 층에서. 그리고 꺼졌다.`,
      ng:`세었는데 박자가 바뀌었다. 쉬는 틈이 숨 두 번으로 줄었다. 이쪽이 세는 걸 안다.<br><br>반쯤 오른 데서 박수가 따라붙었다. 바로 등 뒤에서. 짝짝짝. 스피커가 외친다. 오늘의—.<br>일행이 이쪽을 계단 위로 끌어올렸다. 외침이 끝나기 전에. 등 뒤로 박수가 몇 번 허공을 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'종탑 — 젖은 화약',
  x:`종탑 안이다. 공기까지 젖었다. 벽에서 물이 흐른다.<br><br>
    화약 주머니를 열었다. 눅눅하다. 손가락으로 비비니 뭉친다. 뭉친 화약은 안 터지거나 한꺼번에 터진다.<br>
    여기서부터 아래는 다 물이다. 마른 데는 이제 없다.<br><br>
    종줄이 물 밑에서 한 번 당겨진다. 종이 운다. 머리 위에서.`,
  o:[
    { l:'① 화약을 나눠 기름종이와 촛농으로 하나씩 봉한다.', k:'fix', dc:22, wake:1,
      ok:`화약을 손가락 마디만큼씩 나눴다. 기름종이로 싸고, 촛농을 녹여 이음매를 막았다. 열두 덩이.<br><br>하나를 물에 담가 봤다. 숨 스무 번. 꺼내서 뜯었다. 속이 보슬보슬하다. 마른 화약이다.<br><br>화약은 마른 데서 쓰는 것인 줄 알았다. 싸 두면 물속까지 데려간다. 손가락이 그 싸는 법을 금방 익혔다. 물이 있는 데도 이제 일하는 자리다.`,
      ng:`싸는데 손이 젖었다. 젖은 손으로 싼 화약은 안에서부터 젖는다.<br><br>열두 덩이 중 넷이 눅었다. 버렸다. 버리는 사이 종이 다시 울렸다. 종줄이 물 밑에서 길게 당겨진다.<br>종소리에 손이 떨려 촛농을 손등에 쏟았다. 데었다. 남은 화약이 반이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 종줄 옆 벽 틈에서 마른 바람을 찾는다.', k:'sense', dc:22,
      ok:`종줄이 물속으로 내려간다. 줄을 따라 수면을 봤다. 줄 옆 벽에 틈이 있다. 거기서 바람이 나온다. 마른 바람.<br><br>틈 안은 비둘기 들보다. 물이 안 닿는 데. 화약을 펼쳐 놓았다. 한참 지나니 보슬보슬해졌다.<br>들보 구석에 빗물 받는 통이 있다. 맑다. 물통도 채웠다. 종줄이 당겨질 때마다 들보가 조금씩 흔들렸다.`,
      ng:`종줄을 따라 보는데 줄이 한 번 세게 당겨진다. 수면이 출렁인다. 물이 들이친다.<br><br>화약 주머니가 젖었다. 다 젖었다. 줄을 당기던 것이 그걸 아는지 물 밑에서 거품이 웃듯 올라온다.<br>젖은 화약을 품에 넣고 하루를 걸었다. 몸에 검은 물이 들었다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 숨으로 재는 심지',
  x:`쉬는 동안 심지를 잰다. 한 뼘이 몇 숨에 타는지. 폭파공은 숨으로 시간을 잰다. 시계보다 낫다.<br><br>
    오늘 한 뼘이 열두 숨이다. 다시 쟀다. 열다섯 숨. 다시. 아홉 숨.<br>
    심지가 이상한 게 아니다. 숨이 이상하다. 세는 사이 누가 이쪽 숨에 제 숨을 섞는다. 귀 바로 뒤에서. 들이쉴 때 같이 들이쉬고 내쉴 때는 안 내쉰다.<br><br>
    숨으로 재면 이제 틀린다.`,
  o:[
    { l:'① 숨 대신 맥박으로 심지를 다시 잰다.', k:'steady', dc:22, wake:1,
      ok:`숨을 버렸다. 손가락을 목에 대고 맥을 짚었다. 쿵. 쿵. 심지에 불을 붙이고 맥을 셌다. 한 뼘에 스무 번.<br><br>다시 쟀다. 스무 번. 또 스무 번. 맞는다. 맥은 남이 못 섞는다. 귀 뒤의 숨이 한참 이쪽 숨을 흐트러뜨리다 그만뒀다.<br><br>숨으로 재는 법은 처음 배운 셈법이다. 숨을 뺏기면 셈도 뺏긴다. 몸 안에 셈이 하나 더 있다. 목에 댄 두 손가락이 시계가 됐다. 손이 그 셈을 금방 외웠다.`,
      ng:`맥을 짚었다. 그런데 맥도 흔들린다. 귀 뒤의 숨이 들이쉴 때마다 심장이 한 번 쉰다.<br><br>심지가 손가락 끝까지 타 들어왔다. 데었다. 셈을 놓쳤다. 손가락 끝에 물집이 잡혔다.<br>그 밤 심지는 다시 안 쟀다. 귀 뒤에서 숨이 밤새 같이 쉬었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 심지를 접고 화약 덩이를 줄 세우는 데 손을 바쁘게 둔다.', k:'fix', dc:22,
      ok:`심지를 접었다. 오늘은 안 잰다. 화약을 덩이별로 나눠 줄 세웠다. 손이 바쁘면 숨은 신경 쓰이지 않는다.<br><br>덩이를 세다 보니 귀 뒤의 숨이 점점 멀어진다. 이쪽이 안 들으니 섞을 데가 없다.<br>다 정리했을 때 숨은 사라졌다. 화약 덩이 하나가 줄에서 빠져 있다. 어디 갔는지 모른다.`,
      ng:`정리하는데 귀 뒤의 숨이 손 위로 내려온다. 화약 위에 숨이 닿는다. 차다. 화약이 눅는다. 숨 닿은 데만.<br><br>덩이 셋이 젖었다. 손으로 털자 젖은 데가 손가락 모양이다. 누가 만지작거린 자국.<br>젖은 덩이를 버렸다. 버린 자리에서 누가 그걸 줍는 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A1', t:'소품 창고 — 판자 해님',
  x:`소품 창고에 판자로 만든 해님이 서 있다. 사람 셋 키다. 노란 얼굴. 웃는 입이 얼굴보다 길다.<br><br>
    뒤에 받침목이 둘. 바퀴가 달렸다. 이쪽이 움직이면 해님이 아주 조금씩 돈다. 얼굴이 늘 이쪽을 보게.<br>
    창고 출구가 해님 바로 뒤다. 해님 얼굴을 등지고는 못 나간다.<br><br>
    서 있는 것을 보면 무엇이 그것을 세우는지 먼저 본다. 받침목 둘이다.`,
  o:[
    { l:'① 받침목 하나에 작은 화약을 대고 넘어뜨린다.', k:'break', dc:23,
      doom:{ title:'넘어진 해님', what:'판자 해님에 깔렸습니다', dc:18, sec:45,
        text:`받침목 밑동에 화약을 대고 심지를 짧게 끊었다. 불을 붙이고 물러섰다. 퍽. 받침목이 꺾인다.<br><br>해님이 기운다. 이쪽 반대로 넘어가야 한다. 그렇게 셈했다. 해님 얼굴이 넘어가며 돈다. 바퀴가 구른다. 이쪽을 보려고.<br>넘어지는 방향이 바뀌었다. 이쪽으로. 판자 그림자가 덮인다. 뛰었다. 늦었다.<br><br>판자가 등을 덮는다. 무겁다. 판자 앞면이 바닥을 향했다. 웃는 얼굴이 이쪽을 품었다.`,
        dieText:`해님이 다시 섰다. 누가 세웠는지 모른다.<br><br>받침목 하나가 새것이다. 사람 팔 굵기. 판자 뒤에 대어 있다. 옷소매가 감겨 있다.<br>해님이 웃는다. 얼굴이 조금 더 붉다.` },
      ok:`해님이 도는 방향을 먼저 봤다. 이쪽을 따라 돈다. 그럼 넘어질 때도 이쪽으로 온다. 그래서 일행을 해님 등 뒤로 돌려 세우고 반대쪽 받침목에 화약을 댔다.<br><br>퍽. 받침목이 꺾였다. 해님이 이쪽을 보려 돌며 넘어진다. 이쪽은 이미 등 뒤다. 판자가 빈 바닥을 덮었다. 쾅.<br>웃는 얼굴이 바닥에 엎어졌다. 출구가 열렸다. 판자 밑에서 바퀴가 한참 헛돌았다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 해님 얼굴을 마주 보며 돌아 뒷걸음으로 나간다.', k:'steady', dc:22,
      ok:`해님 얼굴을 마주 봤다. 웃는 입. 그려 넣은 눈. 눈을 떼지 않고 옆걸음으로 돌았다. 해님이 따라 돈다.<br><br>해님 등이 출구 쪽을 향했을 때 뒷걸음으로 나갔다. 마지막까지 얼굴을 보면서. 문을 닫는 순간 판자가 삐걱하고 기울었다. 쫓아오려다 받침목이 버텼다.<br>문 너머로 판자 긁히는 소리가 오래 났다.`,
      ng:`마주 보고 도는데 해님 입이 조금씩 벌어진다. 판자인데. 그려 넣은 입 선이 갈라진다.<br><br>갈라진 틈 안이 캄캄하다. 거기서 아이 웃음소리가 난다. 눈을 떼면 안 되는데 떼고 말았다. 그 순간 해님이 한 바퀴 휙 돌았다. 판자 모서리가 어깨를 쳤다.<br>쓰러진 채 기어 나왔다. 어깨에 노란 칠이 묻었다. 지워지지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } },
    { l:'③ 바퀴 밑에 쐐기를 박아 해님을 못 돌게 한다.', k:'fix', dc:22,
      ok:`화약 상자에서 나무 쐐기를 꺼냈다. 심지 감는 데 쓰는 것이다. 해님 바퀴 밑에 하나씩 박았다.<br><br>해님이 돌려다 멈춘다. 얼굴이 다른 데를 본 채 굳었다. 그 옆을 지났다. 웃는 얼굴이 벽만 보고 있다.<br>출구를 나서는데 등 뒤에서 판자가 바들바들 떨었다. 돌고 싶어서.`,
      ng:`쐐기를 박는데 바퀴가 이쪽 손가락 위로 굴렀다. 해님이 이쪽을 보려 했다.<br><br>손가락이 바퀴 밑에 깔렸다. 뼈가 운다. 해님 얼굴이 정수리 위에서 내려다본다. 웃는다.<br>일행이 판자를 밀어 손을 빼냈다. 손가락 두 개가 부었다. 심지를 감기가 어려워졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A2', t:'교실동 — 물에 잠긴 돌무더기',
  x:`교실동 복도가 무너진 천장에 막혔다. 물이 허리까지다. 돌무더기가 물 위로 반쯤 나왔다.<br><br>
    돌아가려면 교실을 지나야 한다. 교실 안에서 분필 소리가 난다. 수업 중이다.<br>
    돌무더기의 받침이 보인다. 물 밑 맨 아래 큰 돌 하나. 그걸 빼면 나머지가 물속으로 흩어진다.<br><br>
    다만 물속에서 화약은 안 터진다. 보통은.`,
  o:[
    { l:'① 봉한 화약을 물속 받침돌 밑에 넣고 터뜨린다.', k:'break', dc:23, wake:1,
      ok:`촛농으로 봉한 화약에 심지를 꿰어 대롱에 넣었다. 물속 받침돌 밑까지 밀어 넣었다. 대롱 끝은 물 위로. 불을 붙였다.<br><br>물속에서 둔하게 쿵. 물이 한 번 솟았다. 돌무더기가 천천히 물속으로 흩어진다. 길이 났다. 분필 소리가 멈췄다. 교실이 놀랐다. 그 틈에 지났다.<br><br>물속에서는 소리가 둔하다. 둔한 소리는 멀리 안 간다. 물이 소리를 먹어 준다. 물 밑에 화약을 두는 자리를 손이 알았다. 물은 이제 막힌 데가 아니다. 덮개다.`,
      ng:`대롱 이음매로 물이 샜다. 심지가 중간에서 꺼졌다. 다시 꾸미는 사이 교실 분필 소리가 멈췄다.<br><br>교실 뒷문이 열린다. 물이 출렁인다. 무엇이 복도로 나온다. 다시 꾸민 심지에 불을 붙이고 물러났다. 쿵. 돌이 흩어졌다. 물살이 이쪽을 넘어뜨렸다.<br>물을 먹고 일어났다. 길은 났다. 복도 물속에 작은 손자국이 줄지어 찍혔다. 이쪽을 따라온 자국.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 화약을 넉넉히 넣어 돌무더기째 날린다.', k:'break', dc:23,
      doom:{ title:'솟은 물', what:'흔들린 물 밑에서 손들에게 끌려갑니다', dc:18, sec:50,
        text:`화약을 넉넉히 넣었다. 확실히 날리려고. 쾅. 물이 천장까지 솟았다.<br><br>돌무더기는 날아갔다. 복도 물이 통째로 흔들린다. 교실마다 물이 일어선다. 깨운 것이다. 수업 중이던 것들을.<br>물이 가라앉으며 이쪽 다리를 감는다. 손이다. 여럿이. 떠든 사람을 데려간다. 교실 쪽으로. 물속으로.<br><br>귀가 먹어서 일행이 부르는 소리가 안 들린다.`,
        dieText:`교실 칠판에 이름이 하나 써졌다. 떠든 사람.<br><br>그 밑으로 줄이 그어졌다. 지운 줄이 아니라 데려갔다는 줄이다.<br>복도 돌무더기 자리는 깨끗하다. 길은 났다.` },
      ok:`넉넉히 넣으려다 반만 넣었다. 대신 돌무더기 위에 젖은 책상을 덮어 소리를 눌렀다.<br><br>쿵. 책상이 들썩였다. 돌무더기가 갈라졌다. 소리는 크지 않았다. 교실 분필 소리가 한 번 멈췄다가 다시 났다.<br>갈라진 틈으로 지났다. 책상이 물 위에 떴다. 책상 안에서 공책이 한 권 떠올랐다. 이름 칸이 비었다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 화약을 아끼고 교실 뒤로 조용히 지난다.', k:'hide', dc:22,
      ok:`화약을 아꼈다. 교실 뒷문으로 들어가 사물함 쪽 벽에 붙어 걸었다. 물 헤치는 소리를 줄이려 발을 끌었다.<br><br>분필 소리가 이어진다. 또각, 또각. 수업 중에 뒤로 지나가는 사람을 못 본 척한다. 앞문으로 나갔다.<br>나오고 나서 화약 주머니를 쓸어 봤다. 그대로다. 아낀 화약은 다음 문을 연다.`,
      ng:`지나는데 화약 주머니 끈이 책상 모서리에 걸렸다. 주머니가 물에 빠질 뻔했다. 잡느라 물을 크게 쳤다.<br><br>분필 소리가 멈춘다. 서른다섯 개 책상 쪽 물이 일제히 이쪽으로 출렁인다. 칠판에 글씨가 써진다. 떠든 사람.<br>앞문까지 뛰었다. 등 뒤로 차가운 물살이 따라왔다. 주머니는 건졌다. 반이 젖었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'계단 — 뒤에서 올라오는 것',
  x:`계단을 오른다. 아래에서 무엇이 올라온다. 젖은 발소리. 서두르지 않는다. 이쪽이 지칠 때까지 기다리는 걸음이다.<br><br>
    오래된 계단이다. 디딤판이 나무다. 받침보 하나가 썩었다. 거기를 끊으면 계단 반이 내려앉는다.<br>
    끊으면 다시 못 내려간다. 다른 길로 가야 한다.<br><br>
    발소리가 한 층 아래다.`,
  o:[
    { l:'① 받침보에 화약을 대고 심지에 불을 붙인다.', k:'break', dc:23,
      doom:{ title:'내려앉은 계단', what:'디딤판 틈으로 계단 밑 어둠에 끌려 내려갑니다', dc:18, sec:50,
        text:`받침보 밑에 화약을 대고 심지를 끌어 올렸다. 불을 붙였다. 심지가 탄다. 열 숨.<br><br>다섯 숨째에 디딤판 틈으로 손이 올라왔다. 이쪽 발목을 쥔다. 아래 것은 계단을 오르지 않았다. 계단 밑으로 왔다.<br>뿌리치는데 손이 둘, 셋. 심지는 계속 탄다. 여덟 숨. 아홉. 손들이 이쪽을 디딤판 틈으로 당긴다. 아래로.<br><br>열.`,
        dieText:`계단 반이 내려앉았다. 먼지가 오래 갔다.<br><br>무너진 자리 밑은 캄캄하다. 거기서 젖은 발소리가 났다. 하나가 아니라 둘.<br>그 뒤로 이 건물 어디서든 발소리가 둘씩 났다. 하나는 조금 절었다.` },
      ok:`심지를 붙이기 전에 디딤판 틈을 봤다. 틈마다 물기가 번진다. 아래 것은 계단 밑으로 오고 있다.<br><br>심지를 짧게 끊었다. 세 숨. 불을 붙이고 위로 뛰었다. 쾅. 계단 반이 내려앉았다. 밑에서 무엇이 같이 깔리는 소리.<br>위층에 엎드려 먼지를 피했다. 젖은 발소리가 끊겼다. 다른 길은 멀다. 그래도 길이다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 디딤판 세 장만 터뜨려 넘지 못할 틈을 낸다.', k:'fix', dc:22,
      ok:`받침보는 두고 디딤판 세 장만 작게 터뜨렸다. 계단 가운데가 빈다. 건너뛰기엔 넓고 기어오르기엔 미끄러운 틈.<br><br>아래 것이 틈 앞에서 멈췄다. 젖은 손으로 틈 가장자리를 더듬는다. 넘지 못한다.<br>계단은 남았다. 돌아갈 때 건널 판자 하나를 위층에 세워 두었다.`,
      ng:`세 장을 터뜨리려 했는데 한 장이 덜 터졌다. 반만 깨진 판이 틈에 걸쳐 다리가 됐다.<br><br>아래 것이 그 다리를 짚고 올라온다. 젖은 손이 위층 계단 모서리를 잡았다. 손가락이 넷.<br>남은 화약을 그 손 앞에 던졌다. 퍽. 손이 물러났다. 화약을 반 넘게 썼다. 귀가 한참 먹먹했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'③ 터뜨리지 않고 일행을 위층으로 서두르게 한다.', k:'evade', dc:22,
      ok:`화약을 아꼈다. 일행 등을 밀어 올렸다. 계단 끝까지 쉬지 않고.<br><br>발소리가 따라온다. 같은 빠르기로. 이쪽이 빨라져도 같이 빨라지지 않는다. 그대로다. 서두르지 않는 것은 언젠가 닿는다는 뜻이다.<br>위층 문을 닫고 빗장을 걸었다. 문 밑 틈으로 물이 조금 스며들다 멈췄다.`,
      ng:`서두르다 맨 뒤의 이쪽이 디딤판 썩은 데를 밟았다. 발이 빠졌다.<br><br>빠진 발을 밑에서 무엇이 잡았다. 차다. 끌어내리려 한다. 일행이 팔을 잡았다. 줄다리기가 됐다.<br>신발을 버리고 발을 뺐다. 맨발로 남은 계단을 올랐다. 발목에 손자국이 시퍼렇게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'문 — 안쪽에서 붙든 문고리',
  x:`잠긴 문이다. 문고리가 아주 조금씩 돈다. 저쪽에서 쥐고 있다. 이쪽이 돌리면 저쪽이 막는다.<br><br>
    문을 보면 경첩을 본다. 경첩은 이쪽에 있다. 화약 반 꼬집이면 경첩 둘이 날아간다.<br>
    경첩이 날아가면 문은 저쪽으로 넘어간다. 문고리를 쥔 것과 같이.<br><br>
    문 너머에서 아이가 웃는다. 숨바꼭질할 때처럼.`,
  o:[
    { l:'① 경첩 둘을 한 심지로 묶어 동시에 터뜨린다.', k:'break', dc:22,
      ok:`경첩마다 화약을 반 꼬집씩 대고 심지 하나로 묶었다. 동시에 터지게. 불을 붙이고 비켜섰다.<br><br>퍽. 경첩이 둘 다 날아갔다. 문이 저쪽으로 넘어간다. 문고리를 쥔 채로 무엇이 같이 넘어갔다. 웃음이 비명으로 바뀌었다가 끊겼다.<br>넘어진 문짝을 밟고 지났다. 문 밑에서 문고리가 한 번 더 돌았다.`,
      ng:`하나가 먼저 터졌다. 심지 길이가 달랐다. 문이 한쪽 경첩에 매달려 이쪽으로 휙 돌았다.<br><br>문짝이 어깨를 쳤다. 넘어졌다. 열린 틈으로 웃음소리가 쏟아져 나온다. 찾았다! 작은 손들이 이쪽 발목을 만진다.<br>남은 경첩이 마저 터지며 문이 쓰러졌다. 손들이 그 밑에 깔려 들어갔다. 어깨가 빠질 듯 아프다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 저쪽과 같이 돌리다 반대로 확 꺾는다.', k:'luck', dc:22,
      ok:`문고리를 잡고 저쪽과 같이 돌렸다. 저쪽이 돌리는 방향으로. 저쪽이 놀라 멈칫한다. 그 순간 반대로 확 돌렸다.<br><br>잠금이 풀렸다. 저쪽 손이 문고리에서 미끄러졌다. 문이 열렸다. 아무도 없다. 문고리가 젖어 있다. 작은 손 모양으로.<br>지나면서 문을 열어 둔 채 받쳐 두었다. 닫히면 다시 쥘 것이다.`,
      ng:`같이 돌렸는데 저쪽이 놀라지 않는다. 같이 돌리다가 같이 멈춘다. 놀이를 아는 손이다.<br><br>한참 그렇게 돌렸다. 손목이 저리다. 저쪽에서 키득거린다. 이쪽 손목이 지쳐 먼저 놓았다.<br>문은 안 열렸다. 문고리가 저 혼자 한 바퀴 돌고 멈췄다. 이겼다는 듯이.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'부조정실 — 이름을 부르는 인터컴',
  x:`부조정실 책상에 인터컴이 있다. 버튼 옆에 층마다 이름표. 분장실, 의상실, 스튜디오.<br><br>
    인터컴에서 지직 소리가 나더니 목소리가 나온다. 무대 감독이다. 오늘의 친구 스탠바이. 그리고 이쪽 이름.<br>
    스피커가 방송국 전체에 이어져 있다. 이쪽 이름이 층마다 울린다. 층마다 무엇이 고개를 든다.<br><br>
    인터컴 뒤로 굵은 전선이 벽 속으로 들어간다.`,
  o:[
    { l:'① 벽 속 전선 다발에 화약을 쑤셔 넣고 끊는다.', k:'break', dc:23,
      ok:`전선이 벽으로 들어가는 구멍에 화약을 쑤셔 넣었다. 짧은 심지. 불을 붙이고 책상 밑에 엎드렸다.<br><br>퍽. 불꽃이 튀고 인터컴이 꺼졌다. 이쪽 이름이 반쯤 불리다 끊겼다. 층마다 울리던 소리가 멎는다.<br>방송국이 잠깐 조용했다. 어디선가 무엇이 다시 고개를 내리는 소리. 부르다 만 이름은 아무도 찾으러 오지 않는다.`,
      ng:`터뜨렸는데 전선이 한 가닥 남았다. 그 가닥으로 소리가 더 크게 나온다. 지지직. 이쪽 이름이 늘어진다. 길게, 아주 길게.<br><br>층마다 늘어진 이름이 울린다. 계단 쪽에서 발소리가 올라온다. 여럿이.<br>남은 가닥을 손으로 뜯었다. 손바닥이 찌릿했다. 소리가 끊겼다. 발소리는 한참 계단에 머물다 내려갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 다른 층 버튼을 눌러 친구가 거기 있다고 알린다.', k:'luck', dc:22,
      ok:`인터컴 버튼 중 테이프 보관실을 눌렀다. 목소리를 낮춰 말했다. 오늘의 친구, 테이프 보관실에 있습니다.<br><br>지직. 무대 감독 목소리가 멈췄다. 그리고 따라 했다. 오늘의 친구, 테이프 보관실. 층마다 그 말이 울린다. 발소리가 그쪽으로 몰려간다.<br>반대쪽 계단으로 일행을 데리고 올라갔다. 목소리를 낮게 낸 목이 아직 떨린다.`,
      ng:`버튼을 눌렀는데 이쪽 목소리가 아니라 무대 감독 목소리가 나간다. 이쪽 입에서.<br><br>오늘의 친구, 부조정실. 이쪽 입이 이쪽 자리를 알렸다. 손으로 입을 막았다. 이미 나갔다.<br>계단으로 뛰었다. 등 뒤로 부조정실 문이 열리는 소리가 났다. 목이 한참 쉬어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'사감실 — 잠긴 열쇠함',
  x:`사감실 벽에 열쇠함이 있다. 쇠문이다. 자물쇠가 크다. 유리창 너머로 열쇠들이 호실 번호대로 걸린 게 보인다. 다음 층 문 열쇠도.<br><br>
    의자 등받이에 검은 카디건이 걸려 있다. 소매에서 물이 떨어진다. 막 벗어 둔 것처럼. 사감은 근처에 있다.<br>
    자물쇠는 화약 한 꼬집이면 된다. 다만 소리가 난다. 소리가 나면 사감이 돌아온다.<br><br>
    복도 끝에서 찰랑, 열쇠 소리가 아주 작게 났다.`,
  o:[
    { l:'① 카디건으로 자물쇠를 감싸 소리를 죽이고 터뜨린다.', k:'break', dc:23,
      ok:`카디건을 걷어 자물쇠에 몇 겹 감았다. 젖은 털실이 소리를 먹는다. 그 안에 화약을 넣고 불을 붙였다.<br><br>둔하게 퍽. 카디건이 한 번 부풀었다 가라앉았다. 자물쇠가 떨어졌다. 열쇠함을 열고 다음 층 열쇠만 뺐다.<br>카디건은 그을린 채 등받이에 다시 걸었다. 반듯하게. 사감은 제 옷이 탄 걸 알 것이다. 그때는 이쪽이 아래층에 있다.`,
      ng:`감쌌는데 카디건 소매가 이쪽 손목을 감았다. 저절로. 젖은 털실이 조인다.<br><br>화약이 터졌다. 소리는 작았다. 그런데 소매가 손목을 놓지 않는다. 복도 끝 열쇠 소리가 빨라진다. 찰랑찰랑.<br>열쇠를 쥐고 소매를 칼로 끊었다. 손목에 털실 자국이 감겨 남았다. 뛰는 내내 열쇠 소리가 따라왔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 터뜨리지 않고 경첩 핀을 밑에서 쳐 올린다.', k:'fix', dc:22,
      ok:`화약을 넣었다 뺐다. 열쇠함 경첩 핀을 봤다. 녹이 슬었지만 위로 뽑히는 핀이다. 심지 감는 쇠꼬챙이로 밑에서 쳐 올렸다.<br><br>핀 둘이 빠졌다. 쇠문이 자물쇠 쪽을 축으로 비스듬히 열린다. 손을 넣어 열쇠를 뺐다.<br>핀을 다시 꽂아 두었다. 문은 잠긴 그대로다. 열쇠만 하나 없다. 사감실 의자 밑 물이 고요하다.`,
      ng:`핀을 쳐 올리는데 쇠꼬챙이가 미끄러져 쇠문을 울렸다. 땡.<br><br>복도 끝 열쇠 소리가 멈췄다. 그리고 이쪽으로 온다. 서두르지 않는다. 사감실 유리에 김이 서린다.<br>핀 하나만 뽑힌 문을 비틀어 열쇠를 뺐다. 손등이 쇠에 찢겼다. 창문으로 나갔다. 유리에 손바닥 자국이 찍히는 걸 봤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 귀울림 속의 목소리',
  x:`쉬는 자리에서 귀를 문질렀다. 오늘 터뜨린 만큼 귀가 운다. 삐— 하는 소리가 머릿속에 깔린다.<br><br>
    폭파공은 이 소리와 산다. 오래 하면 귀가 늘 이렇다. 조용한 데서도 운다.<br>
    오늘은 그 울림 속에 말이 섞였다. 삐— 소리가 입 모양을 한다. 이쪽 이름을 천천히 늘인다.<br><br>
    울림은 귀 안쪽이다. 귀를 막아도 들린다.`,
  o:[
    { l:'① 작게 하나 더 터뜨려 옛 울림을 새 울림으로 덮는다.', k:'break', dc:22, wake:1,
      ok:`화약 반 꼬집을 돌 위에 놓고 터뜨렸다. 아주 작게. 귀 바로 옆에서. 새 울림이 머릿속을 하얗게 덮는다.<br><br>옛 울림이 새 울림 밑에 깔렸다. 말이 안 된다. 그냥 소리다. 새 울림이 가라앉을 때 말도 같이 가라앉았다.<br><br>울림은 쌓이기만 하는 줄 알았다. 새 울림으로 옛 울림을 덮을 수 있다. 귀 안의 소리를 손으로 고쳐 쓰는 법이다. 귀가 무엇으로 울지 이제 이쪽이 정한다.`,
      ng:`터뜨렸는데 새 울림이 옛 울림과 섞였다. 말이 두 겹이 됐다. 이름이 두 번씩 불린다. 메아리처럼.<br><br>머리가 쪼개질 듯 아프다. 귀를 막고 웅크렸다. 동료가 이쪽 어깨를 흔든다. 입 모양만 보인다. 동료 입도 이쪽 이름을 말한다. 같은 박자로.<br>한참 지나 울림이 가라앉았다. 동료는 아무 말도 안 했다고 했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 동료에게 손뼉을 쳐 달라 하고 그 박자만 붙든다.', k:'bond', dc:22,
      ok:`동료에게 손뼉을 쳐 달라고 했다. 일정하게. 짝, 짝. 그 소리만 들었다. 바깥 소리가 귀 안 울림보다 크면 머릿속이 바깥을 따라간다.<br><br>울림 속 말이 손뼉 박자에 밀려 흐트러진다. 한참 그러자 이름이 안 불린다. 그냥 삐— 소리다. 늘 듣던 소리.<br>동료 손바닥이 빨개졌다. 고맙다고 했다. 동료가 손을 털며 웃었다.`,
      ng:`동료가 손뼉을 쳤다. 그런데 손뼉 사이 쉬는 틈에 말이 들어온다. 이름이 그 틈에 맞춰 불린다.<br><br>손뼉이 빨라질수록 이름도 빨라진다. 동료가 멈췄다. 이름이 멈추지 않는다.<br>새벽까지 귀를 막고 누워 있었다. 귀 안에서 누가 이쪽을 다 부를 때까지.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'스튜디오 — 동산 세트의 벽',
  x:`스튜디오 한쪽에 방글 동산 세트가 있다. 합판에 언덕과 나무를 그렸다. 그 앞에 아이 키만 한 의자들이 줄지어 놓였다.<br><br>
    출구가 세트 뒤에 있다. 세트를 돌아가면 카메라 앞을 지나야 한다. 빨간 불이 켜진 카메라 앞을.<br>
    합판은 얇다. 화약 한 덩이면 사람 하나 지날 구멍이 난다.<br><br>
    그림 속 나무 뒤에 무엇이 그려져 있다. 아까는 없었다. 사람 모양. 이쪽 일행 수만큼.`,
  o:[
    { l:'① 합판 이음매를 따라 화약을 가늘게 깔아 문 모양으로 끊는다.', k:'break', dc:23, wake:1,
      ok:`합판 이음매를 따라 화약을 가늘게 깔았다. 한 줄로. 문 모양으로. 심지를 한 끝에 대고 불을 붙였다.<br><br>불이 화약 줄을 따라 달린다. 탁탁탁. 터지는 게 아니라 끊긴다. 합판이 문 모양으로 잘려 뒤로 넘어졌다. 소리가 작다. 카메라 빨간 불이 이쪽으로 돌지 않았다.<br><br>화약은 한 덩이로 터뜨리는 줄 알았다. 줄로 깔면 자른다. 터뜨리는 게 아니라 긋는 것이다. 손가락이 화약 줄 굵기를 쟀다. 얼마나 가늘면 소리 없이 잘리는지.`,
      ng:`줄로 깔았는데 한 군데가 끊겼다. 불이 거기서 멈췄다. 합판이 반만 잘렸다.<br><br>그림 속 사람 모양들이 잘린 틈으로 이쪽을 본다. 그림인데. 틈을 손으로 뜯었다. 합판 가시가 손바닥에 박혔다. 겨우 빠져나갔다.<br>세트 뒤 그림 속 사람 모양이 하나 줄었다. 이쪽 일행보다 하나 적게.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 그림 속 사람 모양을 칼끝으로 하나씩 긁어 지운다.', k:'gaze', dc:22,
      ok:`세트 앞으로 갔다. 그림 속 나무 뒤의 사람 모양을 칼끝으로 긁었다. 물감이 벗겨진다. 하나씩.<br><br>다 긁었다. 그림 속 동산에 아무도 없다. 카메라 빨간 불이 세트를 비춘다. 세트에 출연자가 없다. 빨간 불이 꺼졌다.<br>카메라 앞을 그냥 지나 출구로 갔다. 손톱 밑에 노란 물감이 꼈다.`,
      ng:`긁는데 그림 속 사람 모양 하나가 긁히지 않는다. 물감이 아니다. 합판 안쪽에서 비친다.<br><br>그 모양이 이쪽 손을 따라 움직인다. 칼끝을 피한다. 빨간 불이 이쪽 등을 비춘다. 모니터에 이쪽이 그림 앞에 서 있다. 그림 속 모양과 나란히.<br>뒷걸음질쳐 카메라 앞을 벗어났다. 세트 뒤에서 장갑 손짓이 아쉬운 듯 내려갔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 빈 의자마다 화약 덩이를 올려 카메라 눈을 그쪽으로 끈다.', k:'luck', dc:22,
      ok:`아이 의자마다 화약 덩이를 하나씩 올렸다. 심지는 안 꽂았다. 빨간 불이 의자들을 비춘다. 의자에 무엇이 앉았다. 카메라는 그렇게 본다.<br><br>모니터에 의자 줄이 나온다. 의자마다 작고 동그란 것. 장갑들이 그쪽으로 손짓한다. 이리 와. 화약은 안 온다.<br>그사이 세트를 돌아 출구로 갔다. 화약 덩이 몇 개를 두고 왔다. 아깝지 않다.`,
      ng:`올리는 사이 의자가 이쪽 손을 붙든다. 앉으라고. 작은 의자인데 손목을 쥐는 힘이 세다.<br><br>빨간 불이 이쪽으로 돈다. 모니터에 이쪽이 의자 앞에 허리를 숙이고 있다. 인사하는 자세로. 박수가 났다.<br>손을 비틀어 빼고 세트 뒤로 숨었다. 화약 덩이를 셋 잃었다. 의자 위에서 누가 가져갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'중앙 계단 — 마지막 공기',
  x:`본관 중앙 계단은 물이 턱까지다. 계단참 천장 밑에만 공기가 조금 남았다. 머리를 젖혀야 숨이 닿는다.<br><br>
    다음 층으로 내려가는 계단은 물속이다. 그 밑에 철창 문이 있다. 잠겼다. 녹이 슬었다.<br>
    물속에서 터뜨리면 공기가 흔들린다. 계단참 공기가 거품으로 빠져나갈 수 있다. 숨 쉴 데가 없어진다.<br><br>
    철창 너머 물속에서 손 여럿이 창살을 쥐고 있다. 문이 열리기를 기다리는 것처럼.`,
  o:[
    { l:'① 다 같이 숨을 크게 쉬게 하고 철창 경첩을 터뜨린다.', k:'break', dc:23,
      ok:`다들 숨을 크게 들이쉬게 했다. 봉한 화약을 철창 경첩에 대고 심지 대롱을 물 위로 뺐다. 불을 붙였다.<br><br>물속에서 쿵. 계단참 공기가 출렁였다. 거품이 반쯤 빠져나갔다. 남은 공기에 코만 댔다. 다들 버텼다.<br>철창이 기울었다. 창살을 쥐던 손들이 흩어졌다. 문이 열리길 기다린 게 아니었다. 막고 있었다. 이제 막을 게 없다. 손들이 물러난 길로 내려갔다.`,
      ng:`터뜨렸다. 공기가 거품이 되어 다 빠져나갔다. 천장 밑이 물로 찼다.<br><br>숨이 없다. 철창은 반쯤 열렸다. 그 틈으로 손들이 나온다. 이쪽으로. 반가워서.<br>위층으로 차고 올라 겨우 공기를 찾았다. 폐가 타는 것 같다. 기침에 물이 섞여 나왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-18 } },
    { l:'② 녹이 제일 심한 창살 하나를 비틀어 뽑는다.', k:'steady', dc:22,
      ok:`화약을 아꼈다. 숨을 쉬고 내려가 녹이 제일 심한 창살 하나를 잡았다. 비틀었다. 녹이 부서지며 창살이 빠졌다.<br><br>사람 하나 빠질 틈이다. 손들이 그 틈을 본다. 이쪽 손을 쥐려다 만다. 틈이 좁아 둘이 같이 못 지난다. 하나씩.<br>일행이 하나씩 빠져나갔다. 마지막 사람이 지나자 손들이 그 틈을 다시 쥐었다.`,
      ng:`비트는데 창살이 안 빠진다. 손들이 이쪽 손 위에 겹쳐 같이 쥔다. 도와주는 것처럼. 이쪽 손을 창살에 묶는 것처럼.<br><br>숨이 떨어졌다. 손을 빼려니 안 빠진다. 일행이 내려와 이쪽 허리를 당겼다. 손이 빠졌다. 손등이 창살에 긁혔다.<br>위로 올라와 숨을 쉬었다. 창살은 그대로다. 다시 내려가야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-22 } }
  ] },

{ at:'A', t:'잠자리 — 화약 주머니를 뒤지는 손',
  x:`자다가 깼다. 머리맡에서 부스럭 소리가 난다. 화약 주머니다.<br><br>
    무엇이 주머니 끈을 풀고 안을 뒤진다. 작은 손이다. 화약 덩이를 꺼내 만지작거린다. 굴려 본다. 심지를 당겨 본다. 장난감처럼.<br>
    화약 쓰는 사람은 잠든 동안에도 화약을 생각한다. 저 손이 부싯돌을 찾으면 끝이다.<br><br>
    부싯돌은 주머니 맨 밑에 있다. 손이 그쪽으로 내려간다.`,
  o:[
    { l:'① 눈을 감은 채 손을 넣어 부싯돌부터 쥔다.', k:'steady', dc:23, wake:1,
      ok:`눈을 뜨지 않았다. 잠든 척 몸을 뒤척이며 손을 주머니로 넣었다. 손끝이 기억하는 자리. 맨 밑 왼쪽. 부싯돌을 쥐었다.<br><br>작은 손이 이쪽 손에 닿았다. 멈춘다. 이쪽 손을 만져 본다. 부싯돌을 쥔 주먹을. 한참 만지다 놓고 갔다. 꺼낸 화약 덩이를 하나도 빠짐없이 주머니 옆에 줄 세워 두고.<br><br>주머니 안은 눈으로 보는 줄 알았다. 손끝이 다 안다. 어둠 속에서도 무엇이 어디 있는지. 손가락이 주머니 속 자리를 지도처럼 외웠다. 불이 없어도 일한다.`,
      ng:`손을 넣었는데 작은 손이 먼저 부싯돌을 쥐었다. 이쪽 손끝에 부싯돌 모서리가 닿다가 빠져나간다.<br><br>눈을 떴다. 머리맡에 아무도 없다. 주머니는 열려 있다. 부싯돌이 없다. 어디선가 딱, 딱. 부싯돌 치는 소리.<br>일행을 깨워 화약을 다 물에 담갔다. 소리가 멎을 때까지. 화약 반을 잃었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 벌떡 일어나 그 손을 쳐 낸다.', k:'break', dc:22,
      ok:`일어나며 주머니 쪽을 손등으로 쳤다. 작은 것이 맞아 굴렀다. 화약 덩이 몇 개가 흩어진다.<br><br>어둠 속에서 작은 발이 달아난다. 맨발이다. 구석에서 멈춰 이쪽을 본다. 꺼낸 심지 하나를 쥐고 있다.<br>쫓지 않았다. 흩어진 화약을 주웠다. 심지 하나가 모자란다. 그 밤 구석에서 심지를 당겼다 놓는 소리가 났다.`,
      ng:`쳤는데 손이 화약 덩이를 쳤다. 덩이가 굴러 모닥불 재 쪽으로 간다.<br><br>재에 불씨가 남아 있었다. 퍽. 작게 터졌다. 일행이 다 깼다. 재가 얼굴로 튄다. 눈이 따갑다.<br>재를 털고 보니 구석에서 작은 것이 손뼉을 친다. 재밌다는 듯이.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 짧은 심지 하나를 멀리 굴려 그쪽으로 꾀어낸다.', k:'luck', dc:22,
      ok:`주머니에서 쓸모없는 짧은 심지 하나를 꺼내 멀리 굴렸다. 작은 손이 그쪽으로 간다. 새 장난감이다.<br><br>그사이 주머니를 끌어당겨 품에 안았다. 끈을 두 번 묶었다. 어둠 속에서 짧은 심지를 굴리는 소리가 한참 났다. 즐겁게.<br>아침에 그 심지가 머리맡에 돌아와 있었다. 매듭이 하나 지어져 있다. 이쪽이 묶는 매듭이다.`,
      ng:`굴렸는데 작은 손이 안 간다. 주머니에서 손을 빼지 않는다. 장난감은 이미 있다.<br><br>오히려 주머니째 끌고 간다. 이쪽이 주머니 끈을 잡았다. 저쪽도 잡는다. 줄다리기. 끈이 끊어졌다.<br>주머니는 건졌다. 화약 덩이 넷이 없다. 어둠 속에서 넷을 굴리는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'통로 — 끌려가는 동료',
  x:`동료가 바닥을 긁으며 어둠 쪽으로 끌려간다. 발목에 무엇이 감겼다. 입이 벌어졌는데 소리가 안 나온다.<br><br>
    손에 든 게 화약이다. 크게 터뜨리면 동료까지 다친다. 작게 터뜨리면 안 놓을지도 모른다.<br>
    당기는 쪽까지 열 걸음. 점점 멀어진다.<br><br>
    화약을 쥔 손에 땀이 난다. 땀은 화약에 나쁘다.`,
  o:[
    { l:'① 당기는 쪽 앞 바닥에 화약을 던져 터뜨린다.', k:'break', dc:23,
      doom:{ title:'터진 바닥', what:'꺼진 바닥 밑으로 끌려 내려갑니다', dc:18, sec:50,
        text:`화약에 불을 붙여 동료 발목 너머로 던졌다. 쾅. 바닥이 터진다. 당기던 것이 놓았다. 동료가 굴러왔다.<br><br>그런데 바닥이 계속 꺼진다. 이쪽 발밑까지 금이 달려온다. 오래된 바닥이었다. 받침을 안 봤다.<br>발밑이 꺼졌다. 떨어지는데 밑에서 손들이 받는다. 놓친 것 대신 받은 것이다. 아래로. 아래층 어둠으로.<br><br>귀가 먹어서 동료가 부르는 소리가 안 들린다.`,
        dieText:`통로 바닥에 구멍이 났다. 둥글다.<br><br>동료가 구멍 가장자리에 엎드려 아래를 불렀다. 아래는 캄캄하다. 대답이 없다.<br>한참 뒤에 아래에서 퍽, 작은 소리가 났다. 화약 터지는 소리. 멀었다. 그다음은 없었다.` },
      ok:`던지기 전에 바닥을 봤다. 동료와 당기는 쪽 사이에 받침보가 지나가는 자리가 있다. 거기 바로 뒤에 던졌다. 쾅.<br><br>받침보 뒤쪽 바닥만 내려앉았다. 당기던 것이 구멍으로 떨어졌다. 동료 발목을 감던 것이 같이 끌려 들어가다 끊겼다. 동료가 이쪽으로 굴러왔다.<br>구멍 밑에서 무엇이 기어오르려다 미끄러지는 소리. 동료를 업고 그 자리를 떴다. 귀가 한참 울렸다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 터뜨리지 않고 심지 다발로 빛만 확 일으킨다.', k:'fix', dc:22, wake:1,
      ok:`화약을 터뜨리지 않고 심지 다발에만 불을 붙였다. 화약을 아주 조금 섞어서. 소리 없이 하얀 빛만 확 일었다.<br><br>어둠이 한순간 대낮이 됐다. 당기던 것이 비명을 지르며 손을 놓았다. 어둠에 사는 눈은 빛에 진다. 동료를 끌어당겼다.<br><br>화약은 소리와 힘인 줄 알았다. 빛만 뽑아낼 수 있다. 섞는 양을 손이 쟀다. 터지지 않고 번쩍이는 만큼. 부수지 않고 눈을 멀게 하는 법이 생겼다.`,
      ng:`불꽃을 일으켰는데 빛이 약하다. 심지가 젖었다. 당기던 것이 잠깐 멈칫했다가 다시 당긴다.<br><br>그 잠깐에 동료 손을 잡았다. 같이 끌려갔다. 일행이 다 붙어서 겨우 멈췄다. 동료 발목에 감긴 것을 칼로 끊었다.<br>손바닥이 심지 불에 데었다. 동료 발목이 퍼렇다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-20 } },
    { l:'③ 화약을 내려놓고 달려가 동료 손을 잡는다.', k:'bond', dc:23,
      ok:`화약을 바닥에 내려놓았다. 손이 비어야 잡는다. 달려가 동료 손목을 잡고 뒤로 몸을 눕혔다.<br><br>당기는 힘이 세다. 일행이 이쪽 허리를 잡았다. 줄이 됐다. 버텼다. 당기던 것이 줄 끝까지 다 당겨 보고는 놓았다.<br>돌아오니 내려놓은 화약 덩이가 하나도 없다. 어디로 굴러갔는지 모른다. 동료가 살았다. 화약보다 낫다.`,
      ng:`잡았는데 땀 찬 손이 미끄러졌다. 동료 손목이 빠져나간다. 다시 잡았다. 소매를 잡았다. 소매가 찢어진다.<br><br>동료가 한 길 더 끌려갔다. 일행이 뛰어가 동료 몸을 덮쳐 눌렀다. 겨우 멈췄다.<br>찢어진 소매 조각이 이쪽 손에 남았다. 손이 떨린다. 화약을 쥔 손보다 더.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'세탁실 — 돌아가는 통',
  x:`세탁실 큰 세탁기가 돌아간다. 둥근 유리문 안에서 인형탈이 돈다. 방글이 탈. 웃는 얼굴이 유리에 닿았다 떨어졌다 한다.<br><br>
    통이 멈추면 문이 열린다. 문 앞에 바구니가 있다. 빨래를 꺼내 바구니에 담으라고 적혀 있다. 꺼낸 빨래를 입으라고도.<br>
    세탁실 출구가 잠겼다. 세탁기가 다 돌면 열리는 문이다. 남은 시간 칸에 1분.<br><br>
    유리문 안 탈 소매에서 손이 하나 나와 유리를 두드린다.`,
  o:[
    { l:'① 세탁기 전선 들어가는 데를 터뜨려 통을 세운다.', k:'break', dc:22,
      ok:`세탁기 뒤 전선 들어가는 데에 화약 반 꼬집을 대고 터뜨렸다. 퍽. 불꽃. 통이 덜컹 멈췄다.<br><br>유리문이 안 열린다. 다 돌지 않았으니까. 탈이 유리에 얼굴을 붙인 채 멈췄다. 손이 유리를 두드리다 그친다.<br>출구 잠금이 풀렸다. 전기가 나가면 잠금도 나간다. 어느 건물이든 같다. 세탁실을 나왔다. 등 뒤로 유리 두드리는 소리가 한 번 더 났다.`,
      ng:`터뜨렸는데 통이 멈추지 않고 더 빨리 돈다. 탈 얼굴이 유리에 쾅쾅 부딪친다. 웃는 채로.<br><br>남은 시간 칸이 0이 됐다. 유리문이 열린다. 젖은 탈이 쏟아져 나와 이쪽 어깨에 걸린다. 무겁다. 소매가 이쪽 팔을 감는다. 입혀 주려고.<br>탈을 바닥에 패대기쳤다. 출구로 뛰었다. 몸에 젖은 털 냄새가 뱄다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 바구니를 치우고 세탁기 문에 등을 대고 막는다.', k:'steady', dc:23,
      ok:`바구니를 구석으로 차 버렸다. 빨래를 담을 데가 없다. 그리고 세탁기 문에 등을 대고 섰다.<br><br>통이 멈췄다. 문이 열리려 한다. 등으로 버텼다. 안에서 탈이 문을 민다. 한참. 담을 바구니도 없고 문도 안 열리면 빨래는 다시 돈다. 통이 다시 돌았다.<br>그 사이 출구가 한 번 열렸다. 다 돈 걸로 쳤다. 일행이 빠져나갔다. 이쪽이 마지막으로 등을 뗐다.`,
      ng:`버텼는데 문이 안쪽이 아니라 바깥쪽으로 열린다. 등이 밀렸다. 문이 열렸다.<br><br>젖은 탈이 쏟아져 등에 덮였다. 털 소매가 이쪽 팔에 끼워진다. 한쪽 팔이 탈 소매에 들어갔다. 따뜻하다. 꼭 맞는다.<br>칼로 소매를 찢고 팔을 뺐다. 팔에 털이 붙어 한동안 안 떨어졌다. 출구가 열려 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-20 } }
  ] },

{ at:'A2', t:'배수로 — 당기는 물',
  x:`체육관 밑 배수로다. 물이 한쪽으로 빠르게 빨려 간다. 쇠창살 덮개 너머로. 거기가 아래층으로 가는 길이다.<br><br>
    덮개가 녹슬어 붙었다. 물살이 덮개에 걸려 소용돌이친다. 소용돌이 가운데 물이 깊다.<br>
    덮개만 날리면 물과 같이 아래로 쓸려 간다. 쓸려 가는 것이 길이다. 다만 물살이 얼마나 센지 모른다.<br><br>
    소용돌이 속에서 머리카락이 한 줌씩 돌고 있다.`,
  o:[
    { l:'① 덮개를 터뜨리고 물살을 타고 내려간다.', k:'evade', dc:23,
      doom:{ title:'배수로', what:'물살에 빨려 배수관 깊이 끌려갑니다', dc:18, sec:45,
        text:`봉한 화약을 덮개 경첩에 대고 터뜨렸다. 쿵. 덮개가 날아갔다. 물이 한꺼번에 빨려 들어간다. 이쪽도.<br><br>물살이 세다. 배수관 벽에 몸이 부딪친다. 관이 갈라지는 데가 있다. 아래층으로 가는 관과 더 깊이 가는 관. 몸이 깊은 쪽으로 간다. 물살이 아니다. 손이 끌고 간다.<br>관 벽에 손을 짚었다. 미끄럽다. 머리카락이 얼굴에 감긴다. 숨이 없다.<br><br>귀가 먹은 데에 물이 찬다. 아무것도 안 들린다.`,
        dieText:`배수로 물이 다시 고였다. 덮개가 없어 물이 고르게 빠진다.<br><br>며칠 뒤 그 물에서 머리카락이 한 줌 더 돌았다. 짧은 머리카락. 그을음 냄새가 났다.<br>배수관 어딘가에서 퍽, 작은 소리가 한 번 났다고 했다.` },
      ok:`터뜨리기 전에 줄을 허리에 감아 일행이 잡게 했다. 덮개를 터뜨렸다. 쿵. 물이 빨려 들어간다. 이쪽도.<br><br>관이 갈라지는 데서 몸이 깊은 쪽으로 끌려간다. 줄이 팽팽해졌다. 일행이 잡았다. 그 사이 아래층 관으로 몸을 틀어 넣었다. 줄을 풀었다.<br>아래층 물 위로 쏟아져 나왔다. 숨이 터진다. 일행이 줄을 타고 하나씩 내려왔다. 줄 끝에 머리카락이 감겨 있었다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 창살 하나만 날려 물살을 약하게 만든다.', k:'fix', dc:22,
      ok:`덮개 전체가 아니라 창살 하나만 날렸다. 작게. 물이 그 구멍으로만 빠진다. 소용돌이가 약해졌다.<br><br>창살 하나 틈이면 사람이 머리부터 빠질 만하다. 물살이 약하니 발을 버틸 수 있다. 하나씩 천천히 아래로 내려갔다.<br>마지막 사람이 지날 때 소용돌이 가운데서 머리카락이 아쉽게 한 바퀴 돌았다.`,
      ng:`창살 하나를 날렸는데 녹슨 옆 창살까지 같이 날아갔다. 구멍이 커졌다. 물살이 확 세졌다.<br><br>발이 빨려 들어간다. 옆 창살을 붙들었다. 물살에 섞인 머리카락이 팔에 감긴다. 감기며 당긴다.<br>일행이 이쪽 팔을 잡아 끌어올렸다. 팔에 머리카락 자국이 칭칭 남았다. 다시 들어가야 한다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-22 } }
  ] },

{ at:'A', t:'벽 — 속이 빈 벽',
  x:`복도 벽을 손가락 마디로 두드려 봤다. 폭파공 버릇이다. 꽉 찬 데와 빈 데는 소리가 다르다.<br><br>
    여기는 빈 소리가 난다. 벽 너머에 공간이 있다. 좁다. 사람 하나 서 있을 만큼. 그런 빈 데가 복도를 따라 줄줄이 있다.<br>
    두드린 자리에서 안쪽이 두드린다. 똑. 똑. 대답하듯이.<br><br>
    빈 데마다 무엇이 서 있다.`,
  o:[
    { l:'① 두드려 빈 데와 찬 데를 짚어 지나갈 길을 잡는다.', k:'sense', dc:22, wake:1,
      ok:`마디로 두드리며 걸었다. 빈 소리, 빈 소리, 꽉 찬 소리. 꽉 찬 데는 기둥이다. 기둥 쪽으로 붙어 걸었다. 빈 데 앞에서는 벽에서 몸을 떼었다.<br><br>빈 데 안에서 무엇이 손을 내밀려다 만다. 이쪽이 벽에서 멀다. 기둥 앞에서는 손이 못 나온다.<br>복도를 다 지났다. 손가락 마디가 빨개졌다.<br><br>두드리는 건 터뜨릴 자리를 찾는 일이었다. 숨을 자리도 찾는다. 빈 소리 안에 무엇이 있는지까지 마디가 듣는다. 화약 없이도 벽을 읽는다.`,
      ng:`두드리는데 꽉 찬 소리가 갑자기 빈 소리로 바뀐다. 기둥 안이 빈다. 무엇이 기둥 안으로 옮겨 왔다.<br><br>기둥에 붙어 걷던 동료가 기둥에서 나온 손에 어깨를 잡혔다. 다들 떼어 냈다. 동료 어깨에 손자국.<br>그 뒤로는 두드릴 때마다 소리가 바뀌었다. 이쪽이 읽는 걸 안다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 가까운 빈 데 위쪽을 터뜨려 메워 버린다.', k:'break', dc:23,
      ok:`제일 가까운 빈 데 위쪽 벽에 구멍을 뚫고 화약을 넣었다. 터뜨렸다. 벽 윗부분이 무너져 빈 데를 메웠다.<br><br>안에서 두드리던 소리가 멎었다. 다른 빈 데들도 조용해졌다. 다들 숨을 죽인다. 화약이 무엇인지 안다.<br>조용해진 복도를 서둘러 지났다. 메운 자리 밑에서 손가락 하나가 돌 사이로 삐져나와 있었다.`,
      ng:`넣으려고 구멍을 뚫는데 구멍 안에서 눈이 이쪽을 본다. 바로 앞에서.<br><br>손이 굳었다. 그 사이 구멍에서 손가락이 나와 화약 덩이를 집어 갔다. 안으로. 어디선가 퍽. 벽 너머에서.<br>복도 전체 벽이 한꺼번에 두드려진다. 똑똑똑똑. 뛰어서 빠져나왔다. 귀가 아니라 가슴이 울렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A', t:'연기 — 아무도 없는 데 선 모양',
  x:`문 하나를 터뜨렸다. 연기가 복도에 찼다. 다들 기침을 하며 연기가 가라앉기를 기다린다.<br><br>
    연기 속에 모양이 하나 서 있다. 연기가 그 둘레로 비켜 흐른다. 사람 모양이다. 일행은 다 이쪽 옆에 있다.<br>
    연기는 바람을 보여 준다. 연기를 보면 바람길을 안다. 연기가 비켜 흐르는 데는 무엇이 막고 있다.<br><br>
    모양이 천천히 이쪽으로 걸어온다. 연기가 그 걸음을 따라 갈라진다.`,
  o:[
    { l:'① 연기 결을 읽어 그것이 보는 쪽 반대로 빠진다.', k:'gaze', dc:22,
      ok:`연기 결을 봤다. 모양 둘레로 흐르는 연기가 뒤에서 다시 모인다. 모양이 지나간 자리는 연기가 엷다. 앞쪽은 짙다. 앞을 본다는 뜻이다.<br><br>모양이 보는 쪽이 짙어진다. 그 반대로, 연기가 엷은 쪽으로 일행을 이끌었다. 모양이 이쪽을 지나쳐 갔다. 연기 짙은 쪽으로.<br>연기가 가라앉았다. 아무도 없다. 바닥 재에 발자국이 찍혀 있다. 작은 발.`,
      ng:`읽는데 연기가 바뀐다. 모양이 걸음을 멈추자 연기가 그 둘레로 소용돌이친다. 사방이 짙다.<br><br>모양이 이쪽 바로 앞에 섰다. 연기 속이라 얼굴이 없다. 숨을 쉰다. 연기가 그 입으로 빨려 들어간다. 이쪽 숨도.<br>기침을 하며 주저앉았다. 연기가 가라앉자 모양이 사라졌다. 폐가 한참 쓰렸다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 작게 하나 더 터뜨려 연기째 흩는다.', k:'break', dc:22,
      ok:`화약 반 꼬집을 모양 쪽으로 던져 터뜨렸다. 퍽. 연기가 한꺼번에 흩어진다. 바람이 사방으로 밀려간다.<br><br>모양이 같이 흩어졌다. 연기로 선 것은 연기와 같이 간다. 다시 모이려다 바람에 밀려 복도 끝으로 쓸려 갔다.<br>귀가 운다. 기침이 난다. 그래도 앞이 보인다.`,
      ng:`터뜨렸는데 연기가 더 짙어졌다. 새 연기가 보태졌다. 모양이 둘이 됐다. 셋.<br><br>연기마다 모양이 선다. 일행 수만큼. 누가 일행이고 누가 연기인지 모른다. 손을 뻗어 잡은 어깨가 차다.<br>다들 이름을 부르며 서로를 찾았다. 대답하는 목소리가 일행 수보다 많았다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A', t:'마지막 방 — 기둥 넷',
  x:`마지막 방은 넓다. 천장을 기둥 넷이 받친다. 방 한가운데에 무엇이 웅크리고 있다. 크다. 숨 쉴 때마다 천장 먼지가 떨어진다.<br><br>
    그것이 고개를 든다. 일행을 하나씩 본다. 다 셀 때까지 볼 것이다.<br>
    폭파공은 기둥을 본다. 넷 중 하나가 진짜로 무게를 진다. 나머지 셋은 기대 있을 뿐이다. 그 하나를 끊으면 천장이 한가운데로 내려앉는다.<br><br>
    화약은 남은 걸 다 모으면 한 번이다.`,
  o:[
    { l:'① 기둥마다 울림을 짚어 무게를 지는 하나를 찾는다.', k:'gaze', dc:23, wake:1,
      ok:`기둥을 하나씩 두드렸다. 소리를 들었다. 하나는 맑게 울리고, 하나는 둔하고, 하나는 떨리고, 하나는 아예 안 운다. 안 우는 기둥이 무게를 다 지고 있다.<br><br>그 기둥 밑동에 화약을 다 넣었다. 일행을 문가로 물렸다. 불을 붙였다. 쾅. 기둥이 꺾였다. 천장이 한가운데로 내려앉는다. 웅크린 것 위로. 그것이 다 세기 전에.<br>먼지가 가라앉았다. 방 가운데가 돌무덤이다. 밑에서 아무 소리도 안 났다.<br><br>터뜨리는 것보다 고르는 것이 먼저다. 이제 손이 건물 하나가 어디로 서 있는지 듣는다. 무게가 흐르는 길을 소리로 안다. 큰 것을 무너뜨리는 데 화약이 적게 든다.`,
      ng:`두드렸는데 소리가 다 비슷하다. 그것이 숨 쉴 때마다 기둥들이 같이 울린다. 고를 수가 없다.<br><br>하나를 골라 화약을 넣었다. 쾅. 기둥이 꺾였다. 천장이 반쯤 내려앉다 멈췄다. 다른 기둥이 받쳤다. 틀렸다.<br>그것이 먼지 속에서 일어섰다. 일행 쪽을 본다. 다들 문으로 뛰었다. 화약이 하나도 안 남았다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26 } },
    { l:'② 그것 바로 밑에 화약을 다 밀어 넣고 터뜨린다.', k:'break', dc:24,
      doom:{ title:'마지막 한 번', what:'내려앉은 천장 밑에 깔렸습니다', dc:19, sec:40,
        text:`그것이 다른 데를 보는 사이 기어가 그것 밑에 화약을 다 밀어 넣었다. 심지를 끌고 물러났다. 불을 붙였다.<br><br>쾅. 그것이 들썩였다. 그리고 방 전체가 들썩였다. 기둥들이 흔들린다. 천장에 금이 간다. 한가운데가 아니라 사방이.<br>문까지 스무 걸음. 귀가 먹어 아무것도 안 들린다. 먼지에 아무것도 안 보인다. 천장 조각이 어깨를 쳤다. 넘어졌다.<br><br>위에서 그림자가 내려온다. 넓다.`,
        dieText:`방이 다 내려앉았다. 문까지 돌로 찼다.<br><br>일행이 다른 길로 돌아 나왔다. 하나가 모자랐다.<br>돌무더기 틈에서 심지 끝 하나가 삐져나와 있다. 다 타고 남은 꼬투리.` },
      ok:`그것 밑에 화약을 다 밀어 넣되 심지를 아주 길게 끌었다. 문밖까지. 일행을 먼저 내보냈다. 문밖에서 불을 붙였다.<br><br>쾅. 방 안이 하얗게 들썩였다. 문틀이 흔들린다. 천장이 사방에서 내려앉는다. 문밖 이쪽까지는 안 왔다. 길게 끈 심지 덕이다.<br>먼지가 가라앉았다. 문 안쪽은 돌로 찼다. 그 밑에서 숨소리가 없다. 귀가 한참 아무것도 못 들었다. 들리지 않아도 됐다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 화약을 아끼고 기둥 그늘을 따라 일행을 문으로 옮긴다.', k:'hide', dc:23,
      ok:`터뜨리지 않았다. 그것이 일행을 세는 박자를 봤다. 한 명 볼 때마다 숨 한 번. 그것이 다른 쪽을 볼 때 일행을 하나씩 벽 쪽으로 옮겼다.<br><br>기둥 그늘을 따라갔다. 기둥 뒤에 있는 것은 셀 수 없다. 그것이 다 세려다 숫자가 모자라 다시 센다. 처음부터.<br>문을 빠져나왔다. 화약이 그대로다. 뒤에서 그것이 또 처음부터 세기 시작했다.`,
      ng:`옮기는데 이쪽 화약 주머니가 기둥에 부딪쳤다. 툭.<br><br>그것이 이쪽을 본다. 하나. 숨 한 번. 일행을 하나씩 더 본다. 둘, 셋. 다 세면 어떻게 되는지 아무도 모른다.<br>다 같이 문으로 뛰었다. 넷까지 세어졌다. 다섯째는 문을 넘었다. 그 뒤로 등이 한참 시렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-26 } }
  ] }

]);

// ------------------------------------------
// 대검사 · 무력
// ------------------------------------------
kJob('greatsword', 'A', [

{ at:'A', t:'복도 — 칼 길이만큼 떨어진 것',
  x:`대검사의 칼은 사람 키만 하다. 등에 메고 걸으면 칼끝이 뒤로 한 뼘 삐져나온다.<br><br>
    아까부터 뒤에 무엇이 따라온다. 거리가 늘 같다. 칼 길이만큼. 칼끝 바로 너머에서 멈춘다.<br>
    이쪽이 서면 서고 걸으면 걷는다. 칼이 닿는 거리를 안다. 그 한 치 밖에 있다.<br><br>
    칼을 뽑아 휘두르면 한 걸음이 더 나간다. 그 한 걸음이면 닿을지도 모른다.`,
  o:[
    { l:'① 돌아서며 한 걸음 내디뎌 크게 벤다.', k:'break', dc:23,
      ok:`돌아서는 힘을 칼에 실었다. 한 걸음 내디디며 크게 그었다. 칼 길이에 팔 길이에 한 걸음.<br><br>칼끝에 무엇이 걸렸다. 가볍다. 천 찢어지는 소리. 그것이 뒤로 물러났다. 처음으로 거리가 멀어졌다. 칼 두 개 길이. 세 개.<br>칼끝에 젖은 천 조각이 걸려 있다. 아이 옷소매다. 단추가 하나 달렸다. 떼어 바닥에 두고 걸었다. 그 뒤로는 안 따라왔다.`,
      ng:`돌아서며 그었다. 그것이 정확히 한 걸음 물러났다. 칼끝이 한 치 앞 허공을 지났다.<br><br>큰 칼은 지나간 다음이 길다. 칼이 다 돌기 전에 그것이 들어왔다. 칼 안쪽으로. 차가운 손이 이쪽 손목을 쥐었다. 칼자루를 같이 쥐었다.<br>뿌리치고 칼을 끌어당겼다. 손목에 손가락 자국. 그것은 다시 칼 길이만큼 물러나 섰다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 칼끝으로 바닥에 둥근 금을 긋고 그 안에 선다.', k:'steady', dc:22, wake:1,
      ok:`칼을 뽑아 칼끝을 바닥에 댔다. 일행 둘레로 한 바퀴. 돌바닥에 가는 금이 그어졌다. 칼 길이 둥근 금.<br><br>뒤의 것이 다가오다 금 앞에서 멈췄다. 칼이 닿는 거리를 아는 것은 칼이 그은 금도 안다. 금 밖에서 한참 서성이다 물러났다.<br>금 안에서 숨을 골랐다. 그리고 금을 하나씩 앞으로 그으며 걸었다.<br><br>칼은 휘둘러야 닿는 줄 알았다. 그어 놓으면 칼 길이가 거기 남는다. 칼이 없는 데에도 칼이 있다. 칼끝으로 그리는 법을 손목이 알았다. 휘두르지 않아도 지킨다.`,
      ng:`금을 긋는데 한 군데가 끊겼다. 바닥 돌 틈이다. 칼끝이 틈을 건너뛰었다.<br><br>그것이 정확히 그 틈으로 들어왔다. 금 안으로. 일행 하나의 등에 손을 얹었다. 차가운 손.<br>칼자루로 쳐 냈다. 그것이 틈으로 빠져나갔다. 동료 등에 손자국이 남았다. 끊긴 금을 다시 이었다. 손이 떨렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 무력을 쓴다 — 칼을 멘 채 몸을 돌려 칼집 끝으로 쓴다.', k:'break', dc:23, cost:{ might:28 },
      ok:`칼을 뽑지 않았다. 등에 멘 채 무력을 허리에 몰아 몸을 확 돌렸다. 칼집 끝이 원을 그리며 뒤를 쓸었다.<br><br>칼집이 무엇을 쳤다. 그것이 벽까지 밀려났다. 뽑아서 벨 줄 알았던 것이 칼집에 맞았다. 셈하지 못한 데서 왔다.<br>그것이 벽에서 일어나 더 멀리 물러섰다. 칼 길이 둘. 다시 걸었다. 허리가 시큰하다.`,
      ng:`돌았는데 칼집이 벽에 걸렸다. 복도가 좁다. 몸이 칼에 걸려 반만 돌았다.<br><br>그사이 그것이 다가왔다. 칼 길이 안으로. 처음으로. 이쪽 귀에 대고 숨을 쉰다. 칼이 너무 길어 안쪽은 못 친다.<br>칼을 벽에서 빼내는 사이 그것이 물러났다. 귀가 얼었다. 허리가 삐끗했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, might:-5 } }
  ] },

{ at:'A1', t:'세트 뒤 — 천장에서 내려온 줄',
  x:`세트 뒤는 천장이 높다. 맨 위 철골에서 줄이 수십 가닥 내려온다. 무대 배경을 올리고 내리는 줄이다.<br><br>
    줄 끝이 바닥까지 늘어졌다. 지나가는 사람 손목에 저절로 감긴다. 한 바퀴. 손목에 감긴 줄은 위로 당겨진다. 천천히.<br>
    일행 하나의 손목에 벌써 감겼다. 팔이 위로 들린다. 인형극 인형처럼.<br><br>
    줄은 많다. 칼은 하나다. 대신 칼이 길다.`,
  o:[
    { l:'① 칼을 비스듬히 눕혀 여러 가닥을 한 번에 긋는다.', k:'break', dc:23, wake:1,
      ok:`칼을 낮게 잡고 비스듬히 올려 그었다. 한 번. 칼 길이만큼의 줄이 한꺼번에 끊긴다. 탁탁탁탁.<br><br>동료 팔이 툭 떨어졌다. 끊긴 줄들이 위로 빨려 올라간다. 철골에서 무엇이 줄을 감다 말고 멈췄다. 한 번에 너무 많이 끊겼다.<br><br>칼은 하나를 베는 것인 줄 알았다. 길게 그으면 칼 길이 안의 것이 다 끊긴다. 줄이 많을수록 큰 칼이 낫다. 칼을 얼마나 눕히면 몇 가닥이 걸리는지 손이 쟀다. 한 번에 여럿을 끊는 법.`,
      ng:`그었는데 줄이 칼에 감겼다. 끊기기 전에 휘감겼다. 줄이 칼을 위로 당긴다.<br><br>칼을 놓지 않았다. 칼과 같이 몸이 들린다. 발끝이 바닥에서 뜬다. 일행이 다리를 잡아 끌어내렸다. 칼을 비틀어 줄을 풀었다.<br>칼날에 줄 자국이 남았다. 철골에서 무엇이 아쉽게 줄을 흔들었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 동료 손목 줄부터 손으로 잡고 끊으려 한다.', k:'bond', dc:23,
      doom:{ title:'세트 뒤의 줄', what:'줄에 감겨 천장 철골로 끌려 올라갑니다', dc:18, sec:45,
        text:`동료 손목 줄을 잡고 칼로 끊으려 했다. 그 순간 이쪽 손목에도 줄이 감겼다. 두 바퀴.<br><br>줄이 당겨진다. 위로. 칼이 무겁다. 칼을 쥔 팔은 아래로, 줄에 감긴 팔은 위로. 몸이 찢어질 것 같다. 칼을 놓으면 가볍게 올라간다. 칼을 놓지 않았다.<br>줄이 더 감긴다. 허리에, 목에. 몸이 들린다. 칼과 같이. 철골 쪽 어둠이 가까워진다.<br><br>위에서 무엇이 줄을 감는다. 끽, 끽. 도르래 소리.`,
        dieText:`다음 공연 무대에 새 배경이 내려왔다.<br><br>동산 그림 옆에 사람 모양 판이 하나 매달렸다. 줄 넷에. 큰 칼을 든 모양이다.<br>줄이 당겨질 때마다 칼 든 팔이 올라갔다 내려갔다 한다. 박수가 나온다.` },
      ok:`동료 손목 줄을 쥐는 대신 줄 위쪽, 동료 머리 위 한 뼘을 칼끝으로 그었다. 손이 줄에 닿지 않게.<br><br>줄이 끊겼다. 동료가 바닥에 주저앉았다. 이쪽 손목으로 오던 줄들이 칼끝을 피해 비켜 간다. 칼 길이 안에는 들어오지 않는다.<br>칼을 높이 든 채 세트 뒤를 빠져나왔다. 동료 손목에 줄 자국이 빨갛게 감겼다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 칼을 등에 붙이고 손을 감춘 채 줄 사이를 낮게 지난다.', k:'hide', dc:22,
      ok:`칼을 등에 바짝 붙여 맸다. 몸을 낮춰 줄 사이로 갔다. 줄은 손목을 찾는다. 손을 겨드랑이에 넣었다.<br><br>줄 끝이 이쪽 어깨를, 등의 칼을 더듬는다. 칼에는 손목이 없다. 감길 데를 못 찾는다.<br>세트 뒤를 빠져나왔다. 칼집에 줄 끝이 여러 번 감겼다 풀린 자국이 있었다.`,
      ng:`몸을 낮췄는데 등의 칼이 높다. 칼끝이 줄을 건드렸다. 줄이 칼끝에 감긴다.<br><br>칼이 위로 당겨진다. 등에 멘 끈이 어깨를 조인다. 몸이 뒤로 젖혀진다. 끈을 풀면 칼이 간다. 안 풀었다.<br>일행이 줄을 잘라 줬다. 어깨에 끈 자국이 피멍으로 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A2', t:'나선 계단 — 물속으로 가져가는 칼',
  x:`나선 계단이 물속으로 이어진다. 다음 층까지 잠수해야 한다. 숨을 참고 스무 칸.<br><br>
    칼이 문제다. 사람 키만 한 쇠다. 들고 헤엄칠 수 없다. 물은 무거운 것을 바닥으로 데려간다.<br>
    대검사는 칼을 안 버린다. 버리고 가면 그 칼은 여기 남는다. 이 학교는 남은 것을 모은다.<br><br>
    물속 계단참마다 물이 무겁다. 무엇이 앉아 있다.`,
  o:[
    { l:'① 무력을 쓴다 — 칼을 등에 메고 무게째 버티며 헤엄친다.', k:'evade', dc:23, cost:{ might:30 },
      ok:`칼을 등에 단단히 맸다. 무력을 팔다리에 몰았다. 물에 들어갔다. 칼 무게에 몸이 가라앉는다. 그만큼 세게 저었다.<br><br>계단참 무거운 물이 이쪽을 훑는다. 칼이 등에 있어 등 뒤로는 못 붙는다. 앞으로 저었다. 스무 칸.<br>다음 층 공기에 머리를 냈다. 팔다리가 떨린다. 칼은 등에 있다. 물이 뚝뚝 떨어진다.`,
      ng:`무력을 몰았는데 물이 차서 팔이 굳는다. 칼 무게가 이긴다. 가라앉는다.<br><br>계단참에 발이 닿았다. 무거운 물이 이쪽을 둘러싼다. 손이 칼자루를 쥔다. 이쪽 칼을. 가져가려고.<br>칼자루를 이쪽도 쥐고 계단을 차올랐다. 일행이 위에서 머리채를 잡아 끌어냈다. 칼은 지켰다. 물을 많이 먹었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-18, might:-5 } },
    { l:'② 헤엄치지 않는다 — 칼 무게로 가라앉아 계단을 걸어 내려간다.', k:'steady', dc:23, wake:1,
      ok:`칼을 두 손에 쥐고 숨을 크게 쉬었다. 그대로 물에 들어갔다. 칼 무게에 몸이 바닥까지 가라앉는다. 계단을 걸었다. 물속을.<br><br>헤엄치지 않으니 숨이 덜 든다. 칼을 앞에 세우고 한 칸씩 내려갔다. 계단참 무거운 물 앞에서 칼날을 앞으로 돌렸다. 칼날이 물을 가르며 길을 낸다. 무거운 물이 비켰다.<br><br>칼 무게는 짐인 줄 알았다. 물속에서는 닻이다. 가라앉는 것이 걷는 것이 된다. 칼이 무거운 만큼 땅을 디딘다. 손이 칼 무게를 처음으로 고맙게 쥐었다.`,
      ng:`가라앉아 걷는데 계단참에서 발이 미끄러졌다. 물때가 꼈다. 칼 무게에 몸이 계단 아래로 굴렀다.<br><br>무거운 물 한가운데로 떨어졌다. 손들이 이쪽 팔을, 칼을 만진다. 반가워서. 칼을 끌어안고 일어나 다시 걸었다. 숨이 반밖에 안 남았다.<br>다음 층 계단을 다 올라 머리를 냈을 때 눈앞이 하얬다. 한참 숨만 쉬었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-22 } },
    { l:'③ 칼을 밧줄에 묶어 먼저 내려보내고 뒤따른다.', k:'fix', dc:23,
      doom:{ title:'내려보낸 칼', what:'칼을 당기는 손들에게 물 밑으로 끌려갑니다', dc:18, sec:50,
        text:`칼을 밧줄에 묶어 물속 계단으로 내려보냈다. 줄 끝을 손목에 감고 뒤따라 잠수했다.<br><br>줄이 팽팽해진다. 칼이 먼저 계단참에 닿았다. 계단참의 것들이 칼을 쥐었다. 당긴다. 아래로. 줄이 손목을 끌고 간다.<br>손목 줄을 풀려는데 매듭이 물에 불었다. 안 풀린다. 칼이 아래로 가고, 줄이 따라가고, 이쪽이 따라간다. 계단 아래로, 그 아래로.<br><br>칼을 놓을 수가 없다. 칼이 이쪽을 놓지 않는다.`,
        dieText:`나선 계단 맨 밑 물속 계단참에 칼 한 자루가 서 있다.<br><br>사람 키만 하다. 칼자루에 밧줄이 감겨 있다. 줄 끝이 위로 뻗어 물 위로 나와 있다. 끝에 고리가 지어져 있다. 손목 굵기만 한.<br>지나가는 사람마다 그 줄을 잡아 보고 싶어 했다.` },
      ok:`칼을 밧줄에 묶어 먼저 내려보냈다. 줄 끝을 손목이 아니라 손에 쥐었다. 언제든 놓을 수 있게.<br><br>칼이 계단참에 닿았다. 무거운 물이 칼을 쥔다. 줄이 당겨진다. 놓았다. 칼을 쥔 것들이 칼만 들고 아래로 내려간다. 그사이 그 계단참을 지났다.<br>다음 층에서 줄 끝을 다시 잡아 당겼다. 저쪽이 놓을 때까지 기다렸다. 한참. 칼이 올라왔다. 칼자루에 작은 손자국이 줄줄이 찍혀 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 우는 칼',
  x:`쉬는 자리에 칼을 눕혀 두었다. 밤이 깊어지자 칼이 운다. 우우우. 아주 낮게.<br><br>
    큰 칼은 바람이 지나가면 운다. 오늘은 바람이 없다. 그런데 운다.<br>
    우는 소리에 높낮이가 있다. 누가 칼날을 손가락으로 쓸면 이런 소리가 난다. 칼끝부터 자루 쪽으로.<br><br>
    누운 칼 위에는 아무것도 없다. 소리만 자루 쪽으로 다가온다.`,
  o:[
    { l:'① 칼자루를 쥐고 울림을 세다가 닿기 직전에 칼을 세운다.', k:'steady', dc:22, wake:1,
      ok:`칼자루를 쥐었다. 손바닥으로 울림이 온다. 그 울림이 다가오는 박자를 쥔 손으로 셌다. 자루에 닿기 직전에 칼을 세웠다.<br><br>칼날을 쓸던 것이 미끄러져 떨어졌다. 울음이 뚝 끊겼다. 바닥에서 작은 것이 엉덩방아를 찧는 소리.<br>세운 칼에 기대어 남은 밤을 보냈다.<br><br>칼 우는 소리는 바람 탓인 줄 알았다. 칼이 운다는 건 무엇이 칼에 닿았다는 뜻이다. 손바닥이 칼의 울음을 읽는 법을 알았다. 칼끝 어디에 무엇이 닿았는지 쥔 손이 안다.`,
      ng:`쥐는 순간 울림이 손바닥으로 건너왔다. 칼을 쓸던 것이 이쪽 손등을 쓴다. 칼끝부터 자루로, 자루에서 손등으로.<br><br>칼을 세웠다. 손등에 붙은 것은 안 떨어진다. 팔을 타고 오른다. 어깨까지. 귀 옆에서 우우우.<br>칼을 바닥에 내리쳐 울음을 깼다. 그것이 놀라 떨어졌다. 귀가 한참 웅웅거렸다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 칼 위에 겉옷을 덮어 울음을 죽인다.', k:'fix', dc:22,
      ok:`겉옷을 벗어 칼 위에 덮었다. 칼끝부터 자루까지. 천이 울림을 먹는다. 소리가 작아진다.<br><br>천 밑에서 무엇이 칼을 쓸다 천에 걸려 멈춘다. 천을 들추려는 기척. 그 위에 손을 얹었다. 기척이 물러났다.<br>아침에 천을 걷었다. 칼날에 작은 손가락 자국이 한 줄로 찍혀 있다. 칼끝에서 한가운데까지.`,
      ng:`천을 덮었는데 울음이 천 밑에서 더 크게 들린다. 천이 북 가죽처럼 떨린다.<br><br>일행이 다 깼다. 천 밑에서 무엇이 칼을 두드린다. 똑똑똑. 장난치듯이.<br>천을 걷고 칼을 끌어안았다. 울음이 가슴으로 왔다. 갈비뼈가 운다. 새벽까지 그랬다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'분장실 — 자라는 가발',
  x:`분장실 선반에 가발 머리 모형이 줄지어 있다. 얼굴 없는 하얀 머리통에 가발이 씌워졌다.<br><br>
    가발 머리카락이 자란다. 선반 끝으로 흘러내리고 바닥으로 번진다. 지나가는 사람 발목을 찾는다.<br>
    긴 칼은 땅에 가까운 것을 베기 어렵다. 허리를 숙이면 칼끝이 바닥을 친다.<br><br>
    머리카락이 칼끝에 먼저 닿았다. 감긴다.`,
  o:[
    { l:'① 칼을 거꾸로 쥐고 날을 눕혀 바닥을 쓸 듯 끈다.', k:'break', dc:22,
      ok:`칼을 거꾸로 쥐었다. 날을 바닥에 눕혀 끌었다. 쓰레질하듯이. 머리카락이 칼날에 걸려 끊긴다.<br><br>끊긴 머리카락이 바닥에서 꿈틀대다 멈춘다. 선반의 가발 머리통들이 조금씩 고개를 숙인다. 아래를 본다. 제 머리카락이 끊기는 걸.<br>분장실을 지났다. 칼날에 머리카락이 한 줌 감겼다. 털어 냈다. 한 가닥은 끝내 안 떨어졌다.`,
      ng:`끌었는데 머리카락이 칼날에 감기기만 한다. 끊기지 않는다. 칼날이 머리카락에 먹혔다.<br><br>칼이 무거워진다. 머리카락이 칼을 끌고 선반 쪽으로 간다. 칼을 놓지 않으니 이쪽도 끌려간다. 선반 위 가발 머리통이 이쪽을 내려다본다.<br>일행이 칼에 감긴 머리카락을 손으로 뜯어 줬다. 다들 손바닥이 베였다. 칼은 건졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 뿌리를 친다 — 칼끝으로 가발 머리통을 하나씩 떨어뜨린다.', k:'gaze', dc:22,
      ok:`머리카락을 베지 않았다. 뿌리를 봤다. 가발 머리통이다. 칼끝으로 선반 위 머리통을 하나씩 밀어 떨어뜨렸다.<br><br>바닥에 떨어진 머리통에서 가발이 벗겨진다. 벗겨진 가발은 그냥 머리카락이다. 자라던 것이 멈춘다. 쓰고 있어야 자란다.<br>다 떨어뜨렸다. 하얀 머리통들이 바닥에 굴렀다. 얼굴이 없는데 다들 이쪽을 향해 멈췄다.`,
      ng:`칼끝으로 미는데 머리통이 안 떨어진다. 선반에 붙었다. 칼끝이 머리통을 찌르자 안에서 무엇이 터지는 소리.<br><br>터진 데서 머리카락이 한꺼번에 쏟아진다. 칼을 타고 손으로 온다. 손목에 감긴다. 조인다.<br>칼을 흔들어 털어 냈다. 손목에 머리카락 자국이 칭칭 남았다. 가렵다. 긁으면 더 조인다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'교실동 — 떠다니는 의자',
  x:`교실동 복도 물 위로 의자들이 떠다닌다. 나무로 된 학생 의자. 물살도 없는데 이쪽으로 온다.<br><br>
    의자가 다리에 닿으면 무릎 뒤를 친다. 앉으라는 듯이. 몇 번 맞으면 무릎이 꺾인다. 물속에서 앉으면 머리가 잠긴다.<br>
    의자가 수십 개다. 다 이쪽을 향해 등받이를 돌렸다.<br><br>
    칼 넓은 면은 노만 하다. 사람 키만 한 노.`,
  o:[
    { l:'① 무력을 쓴다 — 칼 넓은 면으로 물을 밀어 의자를 쓸어낸다.', k:'break', dc:23, cost:{ might:27 },
      ok:`칼을 옆으로 눕혀 넓은 면을 물에 댔다. 무력을 허리에 몰아 크게 밀었다. 물이 칼 넓이만큼 밀려간다.<br><br>의자들이 물결에 밀려 복도 양쪽으로 흩어진다. 다시 오려다 다음 물결에 또 밀린다. 그렇게 다섯 번 밀며 복도를 지났다.<br>뒤를 보니 의자들이 복도 한가운데 줄지어 섰다. 등받이를 이쪽으로. 교실처럼.`,
      ng:`밀었는데 의자 하나가 칼 넓은 면에 붙었다. 칼이 의자를 미는 게 아니라 의자가 칼을 민다.<br><br>무력이 빠지는 사이 의자들이 다리 뒤로 몰려왔다. 무릎 뒤를 친다. 꺾였다. 앉았다. 물이 턱까지 온다.<br>칼을 짚고 일어났다. 일행이 의자를 걷어찼다. 무릎 뒤가 멍투성이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, might:-5 } },
    { l:'② 칼끝을 물 바닥에 박고 칼에 등을 기대 선다.', k:'luck', dc:22,
      ok:`칼을 등 뒤에 세워 물 바닥에 칼끝을 박았다. 칼에 등을 기댔다. 서 있는데 등받이에 앉은 자세다.<br><br>의자들이 다가와 이쪽 다리 뒤에서 멈춘다. 이미 앉아 있다. 칼에 기대 앉은 사람에게는 의자가 필요 없다. 의자들이 한참 머뭇거리다 다른 데로 떠갔다.<br>칼을 뽑아 걸었다. 의자가 다가오면 다시 박고 기댔다. 느렸다. 그래도 한 번도 안 앉았다.`,
      ng:`기댔는데 칼끝이 물 바닥 타일에서 미끄러졌다. 칼이 기울며 몸이 뒤로 넘어간다.<br><br>의자가 기다렸다는 듯 엉덩이 밑에 들어왔다. 앉았다. 물이 입까지 찬다. 의자가 이쪽을 꼭 받친다. 안 일어서진다.<br>일행이 팔을 끌어 일으켰다. 의자가 한참 따라오다 교실 문 앞에 멈췄다. 제자리로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A', t:'좁은 통로 — 휘두를 수 없는 칼',
  x:`통로가 좁다. 어깨가 양쪽 벽에 닿는다. 칼을 등에서 뽑을 자리가 없다. 칼을 손에 든 채 앞으로 내밀고 기어간다.<br><br>
    앞에서 무엇이 온다. 같은 통로로. 기어 오는 소리. 손톱이 돌을 긁는다.<br>
    휘두를 수 없다. 칼끝이 앞을 향해 있을 뿐이다.<br><br>
    기어 오는 것과 칼끝 사이가 줄어든다.`,
  o:[
    { l:'① 휘두르지 않고 칼끝에 무게를 실어 천천히 밀어 넣는다.', k:'break', dc:23, wake:1,
      ok:`칼을 쥔 손에 힘을 빼지 않았다. 무게를 칼끝에 다 실었다. 그리고 밀었다. 천천히. 한 치씩.<br><br>칼끝이 무엇에 닿았다. 무르다. 밀었다. 칼이 휘지 않고 들어간다. 기어 오던 소리가 멈췄다. 손톱 긁는 소리가 뒤로 물러간다. 칼에 밀려서.<br>통로를 다 빠져나왔다. 칼끝 한 뼘이 젖어 있다.<br><br>큰 칼은 휘두르는 것이라고 다들 생각한다. 휘두를 자리가 없으면 민다. 무게가 칼끝에 모이면 휘두른 것만큼 들어간다. 팔이 그 미는 힘을 처음 냈다. 좁은 데서도 이 칼이 쓰인다.`,
      ng:`밀었는데 칼끝이 돌 틈에 걸렸다. 칼이 멈췄다. 기어 오는 것은 안 멈춘다.<br><br>칼날 위로 무엇이 기어온다. 칼등을 타고. 손이 칼자루를 쥔 이쪽 손에 닿는다. 차다. 손가락을 하나씩 만진다.<br>칼을 비틀어 빼며 뒤로 기었다. 그것이 칼등에서 떨어졌다. 통로를 거꾸로 기어 나왔다. 손등이 얼었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 칼을 세로로 눕혀 날을 위로 세우고 그 뒤에 엎드린다.', k:'steady', dc:22,
      ok:`칼을 통로 바닥에 세로로 눕혀 날을 위로 세웠다. 그 뒤에 엎드렸다.<br><br>기어 오던 것이 칼날 앞에서 멈췄다. 넘어오려면 날 위를 지나야 한다. 한참 날 끝을 손가락으로 더듬다가 돌아갔다.<br>칼을 다시 들고 기었다. 날에 손가락 자국이 남았다. 작은 손가락. 베인 자국은 없다.`,
      ng:`눕혔는데 날을 세우기 전에 그것이 왔다. 칼 위로 기어올랐다. 칼등 쪽으로.<br><br>칼 위를 기어 이쪽 머리 위로 온다. 숨이 정수리에 닿는다. 엎드린 채 굳었다. 그것이 이쪽 등을 넘어 뒤로 갔다. 무겁지 않았다.<br>한참 뒤에 일어났다. 등에 젖은 자국이 길게 났다. 뒤에 있던 일행이 소리를 질렀다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A', t:'문 — 칼 소리를 흉내 내는 문',
  x:`닫힌 문 너머에서 쇳소리가 난다. 스릉. 칼 뽑는 소리다. 큰 칼.<br><br>
    이쪽 칼은 등에 있다. 뽑지 않았다. 문 너머에서 다시 스릉. 이쪽 칼 소리와 똑같다.<br>
    문 너머에 칼을 든 무엇이 있다. 아니면 칼 소리만 아는 무엇이 있다.<br><br>
    문을 열어야 지나간다.`,
  o:[
    { l:'① 칼을 뽑아 문째 내리친다.', k:'break', dc:23,
      ok:`칼을 뽑았다. 스릉. 문 너머가 조용해졌다. 진짜 칼 소리를 처음 들은 것처럼. 그대로 문을 내리쳤다.<br><br>문이 반으로 갈라졌다. 너머에 아무도 없다. 바닥에 쇠붙이가 하나 떨어져 있다. 칼집 쇠고리다. 오래 녹슬었다. 누가 그걸 문에 긁으며 칼 소리를 냈다.<br>갈라진 문을 지났다. 쇠고리는 두고 갔다. 뒤에서 그걸 다시 줍는 소리가 났다.`,
      ng:`내리쳤는데 문이 안 갈라진다. 칼이 문에 박혔다. 문 너머에서 박힌 칼끝을 무엇이 잡았다.<br><br>당긴다. 문 너머로. 칼을 놓지 않았다. 문에 어깨가 부딪친다. 다시. 다시. 문짝이 이쪽 어깨를 친다.<br>일행이 같이 칼자루를 잡아 뽑았다. 칼끝에 작은 이가 하나 나갔다. 문 너머에서 이 나간 조각을 씹는 소리.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 칼을 뽑지 않고 문 너머 소리가 지칠 때까지 기다린다.', k:'steady', dc:22,
      ok:`칼을 뽑지 않았다. 문 앞에 섰다. 문 너머에서 스릉, 스릉. 이쪽이 뽑기를 기다린다.<br><br>한참 뒤에 소리가 지쳤다. 스릉이 느려진다. 그러다 끊겼다. 문 밑 틈으로 녹 가루가 조금 흘러나왔다.<br>문을 열었다. 아무도 없다. 칼을 뽑지 않고 지나갔다. 뽑지 않은 칼은 흉내 낼 소리가 없다.`,
      ng:`기다리는데 소리가 바뀐다. 스릉 다음에 휘익. 칼 휘두르는 소리. 그리고 문에 쿵. 문 너머에서 문을 벤다.<br><br>문짝 한가운데 금이 간다. 이쪽 쪽으로 불룩하다. 금 사이로 쇳조각이 비친다.<br>물러섰다. 문이 반으로 갈라지며 무엇이 쏟아져 나왔다. 녹 가루. 얼굴에 덮였다. 눈이 한참 따가웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A1', t:'방청석 — 맨 앞줄',
  x:`방청석 맨 앞줄에 빈자리가 다섯 개 있다. 이쪽 일행 수다. 의자 위에 이름표가 놓였다.<br><br>
    무대가 바로 앞이다. 무대 가장자리와 맨 앞줄 사이가 한 걸음. 녹화가 시작되면 맨 앞줄은 무대로 불려 올라간다.<br>
    지나가려면 맨 앞줄을 따라 걸어야 한다. 무대 끝에 하얀 장갑들이 줄지어 나와 있다. 손이 닿는 거리다.<br><br>
    큰 칼은 길다. 무대와 이쪽 사이에 눕히면 꼭 맞는다.`,
  o:[
    { l:'① 칼을 무대 쪽으로 들고 뻗는 장갑을 쳐 내며 지난다.', k:'break', dc:23,
      doom:{ title:'무대 위로', what:'하얀 장갑들에게 무대 위로 끌려 올라갑니다', dc:18, sec:45,
        text:`칼을 뽑아 무대 쪽으로 겨누고 걸었다. 장갑이 뻗으면 쳐 냈다. 하나, 둘.<br><br>셋째 장갑이 칼날을 쥐었다. 장갑이라 베이지 않는다. 다른 장갑들이 칼을 쥔다. 넷, 다섯. 칼을 당긴다. 무대 위로.<br>칼을 놓지 않았다. 놓지 못했다. 칼과 같이 몸이 무대 끝에 걸쳐진다. 장갑들이 소매를, 허리띠를 쥔다. 박수가 터진다.<br><br>무대 조명이 이쪽 얼굴에 떨어진다. 하얗다. 따뜻하다.`,
        dieText:`녹화가 시작됐다. 무대 가운데에 오늘의 친구가 서 있다.<br><br>큰 칼을 들고 있다. 스펀지 칼이다. 노랗다. 친구가 칼을 흔든다. 박수가 쏟아진다.<br>맨 앞줄 이름표 하나가 뒤집혔다. 뒷면에 출연 완료.` },
      ok:`칼을 뽑되 날이 아니라 넓은 면을 무대 쪽으로 들었다. 장갑이 뻗으면 넓은 면으로 밀었다. 베지 않고 밀었다. 장갑은 칼날을 쥐어도 넓은 면은 못 쥔다. 미끄럽다.<br><br>장갑들이 밀려난다. 다시 뻗는다. 다시 민다. 맨 앞줄 끝까지 그렇게 걸었다. 팔이 저리다.<br>끝에 닿았다. 장갑들이 무대 끝에서 손을 흔든다. 안녕. 다음에 또.`,
      win:{ exp:23, dream:3 } },
    { l:'② 무력을 쓴다 — 칼을 무대 끝에 가로로 박아 쇠 담을 친다.', k:'steady', dc:23, cost:{ might:28 },
      ok:`칼을 뽑아 무대 가장자리를 따라 가로로 눕혔다. 무력을 실어 무대 끝 판에 박았다. 칼 길이만큼 쇠 담이 생겼다.<br><br>장갑들이 담 너머로 손을 뻗는다. 칼 위로는 넘지 않는다. 쇠는 무대가 아니다. 담 뒤로 일행을 하나씩 지나게 했다.<br>마지막 사람이 지나자 칼을 뽑았다. 무대 판에 칼 자국이 길게 남았다. 다음 회에도 남아 있을 것이다.`,
      ng:`박는데 무대 판이 무르다. 칼이 너무 깊이 박혔다. 판 밑에서 무엇이 칼끝을 쥔다.<br><br>칼을 뽑으려는 사이 장갑 하나가 담 너머로 이쪽 손목을 쥐었다. 무력을 다 써서 칼째 뽑으며 손목을 뺐다.<br>일행은 다 지났다. 이쪽 손목에 장갑 실밥이 박혔다. 손가락 넷 자국.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-20, might:-5 } },
    { l:'③ 칼끝으로 이름표를 뒤집어 놓고 지난다.', k:'luck', dc:22,
      ok:`맨 앞줄 의자마다 칼끝을 내밀어 이름표를 뒤집었다. 뒷면은 비었다. 이름 없는 자리.<br><br>장갑들이 이쪽을 향해 손을 뻗다 멈춘다. 이름표가 없다. 누구를 부를지 모른다. 손이 허공에서 머뭇거린다.<br>그사이 맨 앞줄을 따라 지났다. 등 뒤에서 장갑들이 뒤집힌 이름표를 다시 뒤집는 소리가 났다. 하나씩. 늦었다.`,
      ng:`뒤집는데 칼끝에 이름표가 꽂혔다. 이쪽 이름표다.<br><br>장갑들이 칼끝을 본다. 이름표가 달린 칼. 손이 칼끝으로 뻗는다. 칼을 당긴다. 이쪽은 칼을 놓지 않는다.<br>일행이 이름표를 손으로 떼어 바닥에 던졌다. 칼이 풀렸다. 이름표는 의자 위로 저절로 돌아갔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'양호실 — 커튼 친 침대',
  x:`양호실은 물이 턱까지다. 침대마다 커튼이 쳐져 있다. 하얀 천이 물에 반쯤 잠겨 흔들린다.<br><br>
    커튼 안쪽마다 누가 누워 있다. 실루엣이 비친다. 숨소리가 고르다. 아픈 아이들이다.<br>
    건너편 문으로 가려면 침대 사이를 지나야 한다. 커튼이 지나가는 사람 팔에 감긴다. 들어와 누우라고.<br><br>
    칼로 커튼을 걷으면 안을 보게 된다.`,
  o:[
    { l:'① 칼끝으로 천장 레일의 커튼 고리만 끊는다.', k:'break', dc:23, wake:1,
      ok:`커튼을 베지 않았다. 칼끝을 올려 천장 레일의 고리만 하나씩 끊었다. 커튼이 통째로 물 위에 내려앉는다. 침대를 덮는다.<br><br>덮인 침대 안 실루엣이 그대로 잔다. 커튼이 걷힌 게 아니라 이불이 된 것이다. 감길 커튼이 없다. 침대 사이로 지났다.<br><br>칼은 무엇을 베는 것이었다. 무엇을 매단 데를 끊으면 그것이 내려앉는다. 베지 않고 떨어뜨리는 칼이 있다. 칼끝이 고리 하나 굵기만 한 데를 골랐다. 큰 칼끝이 그만큼 작게 움직였다.`,
      ng:`고리를 끊는데 칼끝이 커튼 천에 닿았다. 천이 찢어지며 안이 보였다.<br><br>침대에 누운 것이 고개를 돌려 이쪽을 본다. 눈을 감은 채로. 일어난다. 커튼 사이로 손이 나와 칼끝을 쥔다. 아프다고.<br>칼을 빼며 물러났다. 다른 커튼들 안에서도 실루엣이 일어나 앉았다. 문까지 뛰듯이 헤쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 무력을 쓴다 — 칼을 머리 위로 들고 커튼에 안 닿게 지난다.', k:'evade', dc:22, cost:{ might:26 },
      ok:`칼을 머리 위로 들었다. 물에 안 닿게. 커튼에 안 닿게. 무력으로 팔을 버텼다. 침대 사이를 몸을 옆으로 틀어 지났다.<br><br>커튼이 팔을 찾는다. 팔이 머리 위에 있다. 커튼 끝이 이쪽 옆구리를 스친다. 감길 데를 못 찾는다.<br>건너편 문에 닿았다. 팔이 떨려 칼이 내려올 뻔했다. 버텼다. 문을 나서고서야 내렸다.`,
      ng:`버티는데 팔이 떨린다. 칼끝이 기울어 커튼 하나를 건드렸다. 커튼이 칼끝을 감는다.<br><br>칼이 커튼 안으로 당겨진다. 침대 쪽으로. 칼을 쥔 팔도. 커튼 안에서 차가운 손이 이쪽 팔꿈치를 쥔다. 누우라고.<br>무력을 다 써서 칼째 뽑았다. 커튼이 찢어졌다. 안을 안 보려고 눈을 감았다. 팔꿈치에 손자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, might:-5 } },
    { l:'③ 칼끝으로 약품장 맨 윗칸을 열어 약초를 챙긴다.', k:'heal', dc:22,
      ok:`약품장 맨 윗칸이 물 밖이다. 칼끝으로 문을 걸어 열었다. 안에 말린 약초 꾸러미와 붕대가 있다. 젖지 않았다.<br><br>챙겨 품에 넣었다. 커튼 쪽에서 숨소리가 조금 빨라진다. 약 냄새를 맡았다. 아픈 아이들은 약 냄새를 안다.<br>약초 한 줌을 가까운 침대 커튼 앞 물 위에 띄워 두었다. 숨소리가 다시 고르게 됐다. 그사이 지났다.`,
      ng:`칼끝으로 문을 걸다가 약품장이 통째로 기울었다. 약병들이 물에 쏟아진다. 깨진다.<br><br>커튼마다 실루엣이 일어나 앉는다. 약 쏟는 소리에. 양호 선생이 쓰던 소리다. 커튼이 일제히 이쪽으로 열린다.<br>약초 꾸러미 하나만 쥐고 문으로 헤쳤다. 등 뒤로 커튼 끝들이 쫓아왔다. 손목에 감겼다 풀렸다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'잠자리 — 칼을 사이에 둔 밤',
  x:`잠자리에 누웠다. 칼을 옆에 눕혔다. 대검사는 칼과 나란히 잔다. 칼이 몸 한쪽을 지킨다.<br><br>
    한밤에 칼 너머에서 무엇이 눕는다. 작다. 칼을 사이에 두고 이쪽과 나란히. 칼을 끌어안는 기척.<br>
    칼이 차가워진다. 칼 너머의 것이 칼 온기를 가져간다. 칼이 식으면 이쪽으로 온기를 찾아올 것이다.<br><br>
    칼이 다 식었다.`,
  o:[
    { l:'① 넘어오기 전에 칼자루를 쥐고 칼을 세운다.', k:'steady', dc:22,
      ok:`칼이 다 식은 순간 칼자루를 쥐고 세웠다. 칼을 안고 있던 것이 칼과 같이 들렸다가 미끄러져 떨어졌다.<br><br>세운 칼 너머에서 작은 것이 바닥에 앉는다. 칼을 올려다본다. 끌어안을 데가 없어졌다. 한참 그러다 칼날에 기대 잠들었다. 칼이 그것을 막았다.<br>남은 밤을 앉아서 보냈다. 세운 칼을 사이에 두고. 새벽에 칼 너머가 비었다.`,
      ng:`세우려는데 칼이 무겁다. 칼 너머의 것이 칼을 꼭 안고 있다. 같이 들린다. 칼과 같이 이쪽으로 넘어온다.<br><br>작은 것이 이쪽 가슴 위에 떨어졌다. 차다. 칼 대신 이쪽을 안는다. 숨이 막힌다.<br>일행이 깨서 이쪽 가슴을 털었다. 아무것도 없다. 가슴에 얼음 자국이 동그랗게 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 칼은 그대로 두고 돌아누워 동료 등에 붙는다.', k:'bond', dc:22,
      ok:`칼을 그대로 두었다. 칼 너머의 것이 칼을 안게 두었다. 몸을 돌려 동료 등에 붙었다. 사람 온기는 사람 쪽에.<br><br>칼 너머의 것이 칼을 안고 잠든다. 식은 칼은 아무것도 넘겨주지 않는다. 이쪽으로 오지 않았다.<br>아침에 칼을 들었다. 칼이 젖어 있다. 손자국이 칼 한가운데 꼭 안긴 모양으로 남았다. 닦지 않았다.`,
      ng:`등을 돌렸는데 칼 너머의 것이 칼을 넘어온다. 식은 칼보다 따뜻한 쪽으로.<br><br>이쪽 등에 붙는다. 이쪽과 동료 사이에 끼어든다. 차다. 등뼈 사이로 냉기가 스민다. 동료가 춥다며 깼다.<br>둘이 같이 일어나 앉았다. 둘 사이 바닥에 물이 고여 있다. 작은 사람 모양으로.`,
      win:{ exp:18, dream:2, hp:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'무대 옆 — 카메라 크레인',
  x:`무대 옆에 카메라 크레인이 서 있다. 긴 팔 끝에 카메라. 팔이 천천히 돈다. 무대 위를 훑고, 방청석을 훑고.<br><br>
    렌즈가 지나간 자리 사람은 모니터에 뜬다. 뜨면 장갑들이 손짓한다. 크레인 팔이 이쪽으로 돌아온다.<br>
    크레인 팔은 쇳줄로 받쳐져 있다. 쇳줄 하나를 끊으면 팔이 내려앉는다. 어느 쪽으로 내려앉을지는 모른다.<br><br>
    긴 칼은 긴 것을 끊는 데 맞다.`,
  o:[
    { l:'① 크레인 받침 쇳줄을 끊는다.', k:'break', dc:23,
      doom:{ title:'내려앉은 크레인', what:'크레인 팔에 깔렸습니다', dc:18, sec:45,
        text:`크레인 받침 쇳줄 하나를 칼로 쳤다. 탕. 끊어졌다. 팔이 기운다.<br><br>무대 쪽으로 기울 줄 알았다. 팔 끝 카메라가 이쪽을 본다. 렌즈가 이쪽을 향한 채 내려온다. 무게가 렌즈 쪽으로 쏠린다. 이쪽으로.<br>칼을 들어 받았다. 큰 칼로도 크레인 팔은 못 받는다. 칼이 휘었다. 무릎이 꺾였다. 팔이 등을 누른다.<br><br>모니터에 이쪽 얼굴이 크게 뜬다. 바로 앞에서 찍었다.`,
        dieText:`모니터에 얼굴 하나가 아주 크게 떠 있다. 화면을 꽉 채웠다.<br><br>눈을 뜬 채다. 움직이지 않는다. 장갑들이 그 화면을 향해 손짓한다. 이리 와.<br>크레인 팔 밑에서 휜 칼끝이 삐져나와 있다.` },
      ok:`쇳줄을 끊기 전에 크레인 팔의 무게가 어디로 쏠리는지 봤다. 카메라 쪽이다. 카메라가 이쪽을 볼 때 끊으면 이쪽으로 온다. 카메라가 무대를 볼 때를 기다렸다.<br><br>탕. 끊었다. 팔이 무대 쪽으로 내려앉았다. 카메라가 무대 바닥에 처박혔다. 렌즈가 깨졌다. 모니터들이 한꺼번에 하얗게 지직거린다.<br>장갑들이 손짓할 화면을 잃었다. 그사이 무대 옆을 지났다. 끊긴 쇳줄이 뱀처럼 바닥에서 떨었다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 무력을 쓴다 — 칼을 크레인 팔 밑동에 끼워 돌지 못하게 막는다.', k:'steady', dc:23, cost:{ might:30 },
      ok:`크레인 팔이 이쪽으로 돌아올 때 칼을 세워 팔 밑동에 끼웠다. 무력을 어깨에 몰아 버텼다. 팔이 칼에 걸려 멈췄다.<br><br>렌즈가 이쪽 반 바퀴 앞에서 멈췄다. 이쪽을 못 본다. 크레인 모터가 운다. 웅웅. 칼이 떨린다. 버텼다. 그 사이 일행이 무대 옆을 다 지났다.<br>칼을 빼고 뛰었다. 팔이 휙 돌아 빈자리를 훑었다. 어깨가 빠질 것 같다.`,
      ng:`끼웠는데 크레인 힘이 세다. 칼째 밀린다. 렌즈가 천천히 이쪽으로 돈다. 반 바퀴, 사분의 일.<br><br>렌즈가 이쪽 옆얼굴을 잡았다. 모니터에 반쪽 얼굴이 뜬다. 장갑 하나가 손짓하다 만다. 반쪽이라 부르지 못한다.<br>칼을 빼고 렌즈 밖으로 굴렀다. 무력이 다 빠졌다. 칼날에 크레인 쇠가 갈린 자국이 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18, might:-5 } },
    { l:'③ 렌즈가 올 때마다 칼 넓은 면 뒤로 얼굴을 숨긴다.', k:'hide', dc:22,
      ok:`렌즈가 이쪽으로 올 때 칼을 들어 넓은 면으로 얼굴 앞을 가렸다. 칼 뒤에 몸을 붙였다.<br><br>렌즈가 칼을 찍는다. 모니터에 쇠만 뜬다. 쇠는 친구가 아니다. 렌즈가 지나갔다. 그 사이 몇 걸음. 다시 오면 다시 가렸다.<br>무대 옆을 다 지났다. 팔이 저리다. 칼 넓은 면이 무대 조명에 오래 데워져 따뜻했다.`,
      ng:`가렸는데 칼 넓은 면에 이쪽 얼굴이 비쳤다. 렌즈가 그 비친 얼굴을 찍는다. 모니터에 칼이 뜨고, 칼 속에 얼굴이 뜬다.<br><br>장갑들이 손짓한다. 칼 속 얼굴에게. 발이 저절로 무대 쪽으로 반 걸음 나간다.<br>칼을 옆으로 틀어 얼굴을 지웠다. 반 걸음을 되돌아오는 데 온몸이 젖었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'매점 — 높은 진열장',
  x:`매점은 물이 가슴까지다. 벽 높은 데 진열장 맨 윗칸만 물 밖이다. 거기 단지 몇 개가 남았다. 뚜껑이 밀랍으로 봉해졌다.<br><br>
    손이 안 닿는다. 사다리는 없다. 진열장을 타고 오르면 물속 아랫칸에서 손이 나온다. 아까 일행 하나가 발을 디뎠다가 발목을 잡혔다.<br>
    칼은 사람 키만 하다. 칼끝이 닿는다.<br><br>
    계산대에 외상 장부가 펼쳐져 있다. 마지막 줄에 이쪽 이름. 꿀 한 단지.`,
  o:[
    { l:'① 칼끝으로 단지 손잡이를 걸어 내린다.', k:'fix', dc:22,
      ok:`칼을 들어 칼끝을 단지 손잡이 고리에 걸었다. 천천히 기울였다. 단지가 칼날을 타고 미끄러져 내려온다. 손에 받았다.<br><br>밀랍을 깼다. 꿀이다. 굳었지만 달다. 다들 손가락으로 한 번씩 찍어 먹었다.<br>계산대 장부를 봤다. 이쪽 이름 옆에 동그라미가 쳐졌다. 갚았다는 표시인지 외상이 늘었다는 표시인지 모른다.`,
      ng:`걸었는데 칼끝이 미끄러져 단지가 떨어졌다. 물에 빠졌다. 가라앉는다.<br><br>물속에서 손이 단지를 받았다. 그리고 진열장 아랫칸에 도로 올려놓았다. 물속 칸에. 단지 옆에 이쪽 이름이 적힌 쪽지가 붙었다.<br>칼끝을 물속에 넣어 건지려다 그만뒀다. 칼끝을 누가 쥐려 했다. 칼을 빼다 손목이 시큰했다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, mind:-20 } },
    { l:'② 장부의 이쪽 이름 줄을 칼끝으로 그어 지운다.', k:'gaze', dc:22,
      ok:`계산대로 가서 장부를 봤다. 칼끝으로 이쪽 이름 줄을 그었다. 종이가 찢어질 만큼 깊게.<br><br>진열장 맨 윗칸 단지 하나가 저절로 뚜껑이 열렸다. 외상이 없으면 살 수 있다. 칼끝으로 단지를 걸어 내렸다. 아무도 물속에서 손을 내밀지 않았다.<br>단지 안에 말린 고기가 들었다. 기름종이에 싸였다. 매점 주인이 아껴 둔 것 같다.`,
      ng:`그었는데 이쪽 이름이 지워지지 않는다. 그은 줄 옆에 글씨가 새로 써진다. 외상 한 줄 더.<br><br>장부가 저절로 넘어간다. 다음 장도, 그다음 장도 이쪽 이름이다. 외상이 끝없이 늘어난다.<br>장부를 덮었다. 손이 떨렸다. 물속에서 셈하는 주판알 소리가 났다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 칼날에 비친 뒤',
  x:`복도를 걷는다. 칼을 뽑아 들었다. 칼날이 넓다. 손거울보다 넓다.<br><br>
    칼날을 비스듬히 들면 뒤가 비친다. 걸으며 무심히 봤다. 일행이 비친다. 그 뒤로 복도. 그 끝에 무엇이 서 있다.<br>
    돌아보면 아무것도 없다. 칼날에는 있다. 한 걸음씩 가까워진다.<br><br>
    칼날 속 그것이 손을 든다. 이쪽 어깨를 향해.`,
  o:[
    { l:'① 칼날 속 거리를 재어 돌아보지 않고 등 뒤를 찌른다.', k:'break', dc:23, wake:1,
      ok:`칼날을 비스듬히 든 채 걸었다. 칼날 속 그것이 한 걸음, 또 한 걸음. 어깨에 손이 닿기 한 뼘 전. 칼을 거꾸로 돌려 등 뒤를 찔렀다. 돌아보지 않고.<br><br>무엇이 칼끝에 걸렸다. 칼날 속 그것이 뒤로 휘청 물러난다. 돌아보니 아무것도 없다. 칼끝이 젖었다.<br><br>칼날은 베는 데라고만 알았다. 넓은 칼날은 눈이 된다. 앞을 보면서 뒤를 본다. 비친 거리를 손이 실제 거리로 바꾸는 법을 알았다. 등 뒤도 칼 길이 안이다.`,
      ng:`찔렀는데 칼날 속 거리와 실제 거리가 달랐다. 칼날은 휘었다. 거리도 휘었다.<br><br>칼끝이 허공을 지났다. 그 사이 차가운 손이 이쪽 어깨에 얹혔다. 칼날 속에서도. 무겁다. 어깨가 내려앉는다.<br>어깨를 털고 돌아섰다. 아무것도 없다. 어깨에 손 모양 서리가 앉았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 칼날을 내리고 맨 뒤에서 칼끝을 바닥에 끌며 걷는다.', k:'bond', dc:22,
      ok:`칼날을 내렸다. 일행을 앞세우고 이쪽이 맨 뒤에 붙었다. 칼을 등 뒤로 늘어뜨렸다. 칼끝이 바닥을 긁는다.<br><br>긁는 소리가 등 뒤를 지킨다. 그것이 그 소리를 넘어오지 않았다. 칼끝 긁히는 자리까지가 이쪽 자리다.<br>복도가 끝났다. 칼끝이 닳았다. 돌가루가 칼끝에 하얗게 묻었다.`,
      ng:`내렸는데 안 보이니 더 무섭다. 등 뒤가 차다. 어디까지 왔는지 모른다.<br><br>앞에 걷던 동료가 갑자기 멈춰 이쪽을 본다. 이쪽 어깨 너머를. 얼굴이 하얗다. 아무 말도 못 한다.<br>돌아봤다. 아무것도 없다. 동료가 한참 뒤에야 말했다. 그것이 이쪽 어깨에 턱을 얹고 있었다고.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-26 } },
    { l:'③ 칼날을 돌려 그것에게 그것을 비춰 보인다.', k:'gaze', dc:23,
      ok:`칼날을 돌려 그것 쪽으로 넓은 면을 세웠다. 칼날 속 그것이 칼날에 비친 제 얼굴을 본다.<br><br>멈췄다. 손을 내린다. 칼날 속 얼굴을 오래 본다. 얼굴이 없는 얼굴이다. 그것이 뒷걸음질 친다. 제 얼굴을 처음 본 것처럼.<br>칼날 속에서 그것이 사라졌다. 칼을 내렸다. 칼날 한가운데에 손바닥 자국이 하나 남아 있다. 안쪽에서 댄 것처럼.`,
      ng:`세웠는데 칼날 속 그것이 칼날을 들여다보다 웃는다. 제 얼굴이 마음에 든다.<br><br>칼날 속에서 손을 뻗는다. 칼날 안쪽에서. 이쪽 손이 칼날에 닿아 있다. 칼날 속 손이 그 손을 마주 잡는다. 차다.<br>칼을 놓을 뻔했다. 쥔 손을 비틀어 칼날을 돌렸다. 손이 떨어졌다. 칼자루가 한참 차가웠다.`,
      win:{ exp:20, dream:3, mind:6 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'통로 — 끌려가는 동료',
  x:`동료가 어둠 쪽으로 끌려간다. 발목을 잡혔다. 손톱으로 바닥을 긁는다.<br><br>
    칼이 길다. 칼끝이 동료 발목 너머까지 닿는다. 당기는 것을 벨 수 있다. 다만 어둠 속이다. 무엇을 벨지 안 보인다.<br>
    동료 다리까지 벨 수도 있다.<br><br>
    동료 손이 이쪽으로 뻗는다.`,
  o:[
    { l:'① 칼을 동료 앞에 가로로 던져 붙잡을 막대를 만든다.', k:'bond', dc:23,
      doom:{ title:'가로놓인 칼', what:'칼을 붙든 채 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`칼을 뽑아 동료 앞 바닥에 가로로 내던졌다. 동료가 칼자루를 붙잡았다. 이쪽은 칼끝 쪽을 붙잡았다. 칼 하나에 둘이 매달렸다.<br><br>당기는 힘이 둘을 같이 끈다. 칼이 바닥을 긁으며 미끄러진다. 쇳소리. 칼끝을 쥔 손바닥이 베인다. 놓지 않았다. 대검사는 칼을 놓지 않는다.<br>칼과 둘이 같이 어둠으로 끌려간다. 동료가 칼자루를 놓았다. 이쪽만 남았다. 칼끝을 쥔 채.<br><br>당기는 것이 이번엔 칼을 당긴다. 칼과 같이 이쪽을.`,
        dieText:`동료는 통로 입구에 쓰러져 있었다. 발목에 손자국이 남았다.<br><br>통로 안쪽 바닥에 쇠 긁힌 자국이 한 줄 길게 났다. 어둠 끝까지.<br>그 끝에서 이따금 칼 끄는 소리가 난다. 스르릉. 멀리서.` },
      ok:`칼을 뽑아 동료 앞 바닥에 가로로 내던졌다. 동료가 칼자루를 붙잡았다. 이쪽은 칼등을 발로 밟았다. 칼이 통로 양쪽 벽에 걸렸다. 사람 키만 한 칼이 통로 너비에 꼭 맞았다.<br><br>당기는 힘이 동료를 끈다. 칼이 벽에 걸려 안 따라간다. 동료가 칼을 붙들고 버틴다. 당기던 것이 놓았다.<br>동료를 끌어냈다. 칼을 벽에서 빼는 데 한참 걸렸다. 양쪽 벽에 칼 자국이 깊게 패었다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 무력을 쓴다 — 동료 발목 너머를 낮게 길게 긋는다.', k:'break', dc:22, cost:{ might:30 },
      ok:`동료 발목 너머 한 뼘을 겨눴다. 무력을 팔에 몰았다. 낮게, 바닥을 스치듯 길게 그었다.<br><br>칼이 무엇을 끊었다. 질기다. 여러 가닥. 당기던 힘이 툭 끊겼다. 동료가 제자리에 엎어졌다. 발목은 멀쩡하다.<br>칼날에 긴 머리카락이 한 다발 감겨 나왔다. 끝이 젖었다. 털어 냈다. 동료가 칼날을 보고 한참 말이 없었다.`,
      ng:`그었는데 칼이 너무 낮았다. 바닥 돌을 쳤다. 불꽃이 튀었다. 칼이 튕겨 올랐다.<br><br>그 사이 동료가 한 길 더 끌려갔다. 일행이 뛰어가 동료를 붙잡았다. 겨우 멈췄다. 손에 무력이 하나도 안 남았다.<br>칼날에 이가 나갔다. 동료 발목에 손자국이 넷.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18, might:-5 } },
    { l:'③ 칼을 내려놓고 두 손으로 동료를 잡는다.', k:'steady', dc:23,
      ok:`칼을 내려놓았다. 처음으로. 두 손으로 동료 손목을 잡았다. 뒤로 몸을 눕혔다.<br><br>당기는 힘이 세다. 버텼다. 일행이 허리를 잡았다. 당기던 것이 줄 끝까지 다 당겨 보고는 놓았다.<br>돌아와 칼을 들었다. 칼이 그대로 있다. 손잡이가 조금 따뜻하다. 누가 잠깐 쥐어 본 것처럼.`,
      ng:`칼을 내려놓는 데 반 박자 망설였다. 그 반 박자에 동료가 한 길 더 갔다.<br><br>뛰어가 잡았다. 같이 끌린다. 일행이 덮쳐 셋이 겨우 멈췄다. 동료 손목이 퍼렇다.<br>돌아오니 칼이 한 뼘 옮겨져 있다. 어둠 쪽으로. 아무도 안 만졌는데.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A1', t:'놀이 세트 — 미끄럼틀 탑',
  x:`놀이 세트 끝에 미끄럼틀 탑이 있다. 위층으로 가는 길이 탑 꼭대기 문이다. 계단은 아이 발 너비다.<br><br>
    미끄럼틀로 무엇이 내려온다. 계속. 쉬익. 쉬익. 내려와서 바닥에 닿으면 다시 계단으로 올라간다. 안 보인다. 미끄럼틀이 반질반질 닳았다.<br>
    계단을 오르는 사이 미끄럼틀로 내려오는 것과 엇갈린다. 엇갈릴 때 손을 잡는다. 같이 타자고.<br><br>
    칼이 너무 길어 좁은 계단에서 뽑을 수 없다.`,
  o:[
    { l:'① 칼을 칼집째 미끄럼틀에 가로질러 걸고 오른다.', k:'fix', dc:23,
      doom:{ title:'같이 타자', what:'미끄럼틀로 손을 잡힌 채 끌려 내려갑니다', dc:18, sec:45,
        text:`칼을 칼집째 미끄럼틀 중간에 가로질러 걸었다. 내려오는 것이 걸리게. 그리고 계단을 올랐다.<br><br>쉬익. 내려오던 것이 칼에 걸렸다. 탁. 멈췄다. 그리고 칼을 넘어왔다. 칼을 붙잡고 넘었다. 칼집이 미끄럼틀에서 빠져 같이 내려간다. 칼집 끈이 이쪽 어깨에 걸려 있다.<br>끈이 당겨진다. 이쪽이 계단에서 미끄럼틀로 끌려 들어간다. 작은 손이 이쪽 손을 잡는다. 같이 타자. 쉬익.<br><br>내려간다. 바닥에 닿지 않는다. 미끄럼틀이 끝나지 않는다.`,
        dieText:`미끄럼틀로 무엇이 계속 내려온다. 쉬익. 쉬익.<br><br>소리가 하나 더 늘었다. 쉬익, 쿵. 무거운 것이 같이 내려오는 소리. 칼집이 미끄럼틀에 부딪히는 소리.<br>탑 꼭대기 문 앞에 칼집 끈만 걸려 있다.` },
      ok:`칼을 칼집째 미끄럼틀 중간에 가로질러 걸고 칼집 끈을 어깨에서 풀었다. 이쪽과 칼이 이어지지 않게.<br><br>쉬익. 내려오던 것이 칼에 걸려 멈췄다. 칼을 넘으려 붙잡는다. 칼이 무겁다. 끌어내리지 못한다. 거기 매달려 버둥거린다.<br>그 사이 꼭대기까지 올랐다. 위에서 칼집 끈을 당겨 칼을 끌어올렸다. 칼집에 작은 손자국이 줄줄이 찍혀 있었다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 내려오는 박자를 세어 엇갈리지 않게 오른다.', k:'sense', dc:22,
      ok:`미끄럼틀 소리를 셌다. 쉬익, 쿵, 계단 오르는 발소리 넷, 다시 쉬익. 계단을 오르는 동안은 미끄럼틀이 빈다.<br><br>내려오는 소리가 바닥에 닿는 순간 계단을 올랐다. 그것이 계단 밑에서 오르기 시작할 때 이쪽은 이미 꼭대기다.<br>꼭대기 문으로 들어갔다. 등 뒤에서 미끄럼틀 쉬익 소리가 한 번 났다. 아쉬운 소리였다.`,
      ng:`셌는데 소리가 둘이다. 내려오는 것이 하나가 아니다. 엇갈리는 박자가 맞지 않는다.<br><br>계단 중간에서 작은 손이 이쪽 손목을 잡았다. 같이 타자. 미끄럼틀로 당긴다. 난간을 쥐고 버텼다. 칼이 등에서 계단에 걸려 덜컹거린다.<br>손이 놓았다. 다른 손이 또 잡을 것 같다. 꼭대기까지 기어올랐다. 손목에 작은 손자국.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-26 } }
  ] },

{ at:'A2', t:'강당 — 무대 커튼',
  x:`강당 무대에 커튼이 드리워져 있다. 두껍다. 물을 먹어 무겁다. 커튼 뒤가 마지막으로 가야 할 데다.<br><br>
    커튼이 숨을 쉰다. 부풀었다 가라앉는다. 뒤에 무엇이 많이 서 있다. 줄을 서서.<br>
    커튼을 걷으면 그것들과 마주 본다. 걷지 않으면 못 지난다.<br><br>
    칼이 길다. 커튼 꼭대기까지 닿는다.`,
  o:[
    { l:'① 커튼 매단 굵은 줄을 높이 쳐서 커튼째 떨어뜨린다.', k:'break', dc:23, wake:1,
      ok:`칼을 높이 들었다. 커튼을 매단 굵은 줄을 겨눴다. 한 번에 쳤다. 줄이 끊겼다.<br><br>커튼이 통째로 무너져 내렸다. 물 먹은 천이 앞으로 쏟아지며 뒤에 선 것들을 덮었다. 천 밑에서 무엇이 꿈틀댄다. 줄 선 모양 그대로. 천이 무거워 못 일어난다.<br>무너진 커튼 위를 밟지 않고 가장자리로 지났다.<br><br>걷는 것과 떨어뜨리는 것은 다르다. 걷으면 마주 보고, 떨어뜨리면 덮는다. 칼이 닿는 높이를 몸이 다시 쟀다. 큰 칼은 위에 있는 것을 끊으려고 길다.`,
      ng:`줄을 쳤는데 줄이 너무 굵다. 칼이 반쯤 박혔다. 커튼이 한쪽만 내려앉는다.<br><br>기운 커튼 틈으로 줄 선 것들이 보였다. 다 이쪽을 본다. 젖은 얼굴들. 맨 앞 것이 손을 든다. 출석이요.<br>칼을 비틀어 뽑았다. 줄이 마저 끊겼다. 커튼이 다 내려앉았다. 그 얼굴들이 눈꺼풀 안쪽에 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 칼끝으로 커튼 자락을 들어 기어 지난다.', k:'hide', dc:23,
      ok:`커튼 아래 자락을 칼끝으로 살짝 들었다. 사람 하나 기어갈 틈. 엎드려 기어 들어갔다.<br><br>커튼 뒤에서 줄 선 것들의 발이 보인다. 젖은 실내화. 다 커튼 쪽을 향해 섰다. 발 사이로 기었다. 위를 보지 않았다.<br>줄 끝까지 기어 나왔다. 일어섰을 때 등 뒤에서 커튼이 크게 한 번 부풀었다 가라앉았다.`,
      ng:`기어 들어가는데 칼끝이 커튼 자락을 놓쳤다. 커튼이 등 위로 덮였다. 무겁다. 물이 스민다.<br><br>커튼 밑에 깔렸다. 줄 선 것들의 발이 이쪽 둘레로 모인다. 내려다본다. 커튼 위로 손이 얹힌다. 토닥, 토닥.<br>칼로 커튼을 그어 찢고 빠져나왔다. 숨이 막혔었다. 등에 젖은 천 자국이 남았다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 칼날에 핀 녹',
  x:`쉬는 틈에 칼을 닦았다. 칼날에 녹이 슬었다. 오늘 하루 만에.<br><br>
    녹 모양이 이상하다. 점점이 둥글다. 손가락 끝 크기. 다섯 개씩. 칼날을 따라 줄지어.<br>
    누가 칼날을 손가락으로 짚으며 따라왔다. 칼끝에서 자루 쪽으로. 맨 마지막 자국은 자루 바로 위다.<br><br>
    칼을 쥐는 손 바로 위.`,
  o:[
    { l:'① 숫돌로 자국을 하나씩 갈아 지운다.', k:'fix', dc:22, wake:1,
      ok:`숫돌을 꺼냈다. 칼끝부터 녹을 갈아 냈다. 손가락 자국 하나씩. 돌이 지나간 자리에 쇠가 다시 하얗다.<br><br>마지막 자국을 갈 때 숫돌이 무엇에 걸렸다. 자국이 안 지워진다. 더 힘을 줬다. 쇠가 울었다. 지워졌다.<br><br>칼을 가는 건 날을 세우는 일인 줄 알았다. 칼에 묻은 것을 지우는 일이기도 하다. 숫돌이 무엇을 지워야 하는지 손이 안다. 갈고 나니 칼이 가볍다. 무엇이 같이 갈려 나갔다.`,
      ng:`가는데 녹이 숫돌에 묻어난다. 숫돌에 손가락 자국이 찍힌다. 숫돌을 잡은 이쪽 손가락으로 옮겨 온다.<br><br>손가락 끝이 녹슨 듯 거칠어진다. 감각이 없다. 칼자루를 쥐었는데 쥔 느낌이 안 든다.<br>손가락을 불에 쬐었다. 감각이 한참 뒤에 돌아왔다. 칼날의 자국은 그대로다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 칼집에 넣고 입구를 천으로 묶어 덮는다.', k:'steady', dc:22,
      ok:`칼을 칼집에 넣었다. 자루 바로 위 자국까지 칼집이 덮는다. 칼집 입구를 천으로 단단히 묶었다.<br><br>밤새 칼집 안에서 무엇이 칼날을 짚는 소리가 났다. 똑, 똑. 자루 쪽으로 오다 칼집 입구에서 멈춘다. 더는 못 온다.<br>아침에 칼을 뽑았다. 녹이 칼집 입구에서 끝나 있다. 자루는 깨끗하다.`,
      ng:`칼집에 넣는데 칼이 끝까지 안 들어간다. 무엇이 칼집 안에서 칼끝을 밀어낸다.<br><br>억지로 밀어 넣었다. 칼집 안에서 무엇이 눌리는 소리. 울음 같은 소리. 손이 떨렸다. 칼집 끝이 젖어 온다.<br>칼을 다시 뽑았다. 칼끝에 물이 떨어진다. 녹 자국이 하나 늘었다. 자루 위, 이쪽 손가락 사이에.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'계단참 — 허리를 굽히고 내려오는 것',
  x:`계단참에서 위를 봤다. 위층에서 무엇이 내려온다. 키가 크다. 계단 천장에 머리가 닿는다. 허리를 굽히고 내려온다.<br><br>
    계단은 좁다. 칼을 위로 들면 천장에 닿는다. 옆으로 들면 벽에 닿는다.<br>
    내려오는 것과 이쪽 사이에 계단 열 칸. 그것이 한 칸 내려올 때마다 계단참 공기가 찬다.<br><br>
    칼끝을 위로 겨누면 비스듬히 계단을 따라 꼭 맞는다.`,
  o:[
    { l:'① 칼자루를 바닥에 대고 칼끝을 계단 따라 겨눠 버틴다.', k:'steady', dc:23,
      ok:`칼자루를 계단참 바닥에 대고 칼끝을 계단 위로 비스듬히 겨눴다. 칼이 계단 기울기에 꼭 맞는다. 사람 키만 한 창이 됐다.<br><br>그것이 내려온다. 칼끝 앞에서 멈춘다. 굽힌 허리를 더 굽혀 칼끝을 들여다본다. 한참. 그리고 돌아서 올라갔다.<br>칼을 거뒀다. 계단 천장에 그것의 머리가 긁은 자국이 길게 남았다.`,
      ng:`겨눴는데 그것이 멈추지 않는다. 칼끝을 손으로 쥐었다. 손바닥이 베이지 않는다. 칼끝을 쥔 채 내려온다. 칼이 이쪽으로 밀린다.<br><br>칼자루가 배를 누른다. 계단참 벽에 등이 닿았다. 그것의 얼굴이 칼 길이만큼 앞에 있다. 얼굴이 없다.<br>칼을 비틀어 손에서 뺐다. 그것이 놓았다. 칼을 끌고 아래층으로 뛰었다. 배에 자루 자국이 시퍼렇다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 칼을 거두고 물러나 다른 계단을 찾는다.', k:'evade', dc:22,
      ok:`칼을 거뒀다. 이 계단에서는 칼이 다 못 산다. 아래층으로 물러나 복도를 돌았다. 다른 계단이 있다.<br><br>그 계단으로 올라가는데 위층 복도 저편에서 그것이 이쪽 계단을 내려다보고 있다. 허리를 굽힌 채. 이쪽이 다른 계단으로 갈 줄 안 것처럼.<br>다시 물러날 수는 없다. 칼을 뽑아 들고 올라갔다. 그것은 다가오지 않았다. 보기만 했다.`,
      ng:`물러나는데 계단참 밑 칸에서 발이 미끄러졌다. 칼이 등에서 계단에 걸리며 몸이 굴렀다.<br><br>아래층 바닥에 떨어졌다. 칼이 등을 눌렀다. 위에서 그것이 계단참까지 내려와 내려다본다. 허리를 굽혀.<br>칼을 끌고 기어 도망쳤다. 등이 칼 모양으로 멍들었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A', t:'마지막 방 — 한 바퀴 긋는 칼',
  x:`마지막 방은 높고 넓다. 큰 칼을 마음껏 휘두를 수 있는 데는 여기가 처음이다.<br><br>
    방 한가운데 무엇이 서 있다. 사람 셋 키. 몸에서 줄이 수백 가닥 뻗어 나왔다. 벽으로, 천장으로, 바닥으로. 줄 끝마다 사람 모양이 매달려 흔들린다. 다 이쪽을 본다.<br>
    줄 하나가 일행 하나의 발목으로 뻗는다.<br><br>
    대검사의 칼은 휘두를 자리를 기다려 왔다.`,
  o:[
    { l:'① 무력을 쓴다 — 크게 한 바퀴 돌아 둘레의 줄을 한꺼번에 긋는다.', k:'break', dc:23, cost:{ might:34 }, wake:1,
      ok:`일행을 칼 길이 안쪽으로 모았다. 무력을 발끝에서 어깨까지 끌어올렸다. 칼을 낮게 잡고 크게 한 바퀴 돌았다.<br><br>칼 길이 둘레의 줄이 한꺼번에 끊긴다. 탁탁탁탁. 수십 가닥. 매달린 것들이 떨어진다. 일행 발목으로 오던 줄도. 한가운데 것이 비틀거린다. 줄이 몸이었다.<br>한 바퀴 더 돌았다. 남은 줄이 끊겼다. 그것이 무너졌다.<br><br>칼을 크게 휘두르면 빈틈이 생기는 줄 알았다. 다 돌면 빈틈이 없다. 칼 길이가 둥글게 몸을 감싼다. 휘두르는 칼이 지키는 칼이 됐다. 몸이 그 원을 기억한다.`,
      ng:`돌았는데 반 바퀴에서 줄 다발이 칼을 감았다. 칼이 멈췄다. 몸이 칼에 끌려 휘청인다.<br><br>멈춘 칼 뒤쪽으로 줄이 들어온다. 이쪽 발목에, 동료 허리에. 칼을 비틀어 감긴 줄을 끊었다. 반 바퀴만 끊겼다.<br>일행을 데리고 문 쪽으로 물러났다. 그것은 그대로 섰다. 줄이 다시 자란다. 발목에 줄 자국이 감겼다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-26, might:-5 } },
    { l:'② 한가운데 것에게 곧장 들어가 내리친다.', k:'break', dc:24,
      doom:{ title:'한 번', what:'줄에 온몸이 감겨 숨이 막힙니다', dc:19, sec:40,
        text:`곧장 들어갔다. 줄 사이로. 칼을 머리 위로 들어 한가운데 것의 정수리를 내리쳤다.<br><br>칼이 박혔다. 깊이. 그것이 멈췄다. 그리고 수백 가닥 줄이 한꺼번에 이쪽으로 온다. 박힌 칼을 따라. 칼에, 손에, 팔에, 목에. 감긴다.<br>칼을 놓으면 줄이 칼만 감는다. 칼을 놓지 않았다. 줄이 조인다. 숨이 줄 사이로 빠져나가지 못한다.<br><br>칼을 쥔 채로 묶인다. 내리친 자세 그대로.`,
        dieText:`방 한가운데 줄로 감긴 덩이 하나가 서 있다. 사람 모양이다.<br><br>두 팔을 머리 위로 들고 있다. 그 손에서 큰 칼이 아래로 뻗어 바닥에 박혔다.<br>줄 끝에 매달린 사람 모양이 하나 늘었다. 큰 칼을 든 모양이다.` },
      ok:`곧장 들어가되 칼을 머리 위로 들지 않았다. 줄 사이를 지나며 칼을 몸에 붙여 들었다. 줄이 칼에 닿을 때마다 끊겼다. 길이 났다.<br><br>한가운데 것 앞에서 칼을 들었다. 한 번 내리쳤다. 정수리에서 발끝까지. 줄이 일제히 힘을 잃는다. 매달린 것들이 떨어진다.<br>칼을 뽑았다. 그것이 반으로 갈라져 무너졌다. 칼에 줄이 한 가닥도 안 감겼다.`,
      win:{ exp:25, dream:4 } },
    { l:'③ 칼 넓은 면을 앞세워 일행을 가리고 문으로 물러난다.', k:'steady', dc:23,
      ok:`칼을 옆으로 눕혀 넓은 면을 앞세웠다. 일행을 칼 뒤에 모았다. 줄이 뻗어 오면 넓은 면에 맞고 미끄러졌다.<br><br>한 걸음씩 물러났다. 줄이 칼을 감으려다 넓은 면에서 미끄러진다. 날이 아니라 면이다. 감을 데가 없다.<br>문을 나왔다. 칼 넓은 면에 줄 자국이 수십 줄 그어졌다. 그것은 쫓아오지 않았다.`,
      ng:`넓은 면을 앞세웠는데 줄이 칼 위아래로 돌아 들어온다. 칼은 넓어도 사람보다 좁다.<br><br>줄이 일행 하나의 팔을 감았다. 칼로 끊었다. 다른 줄이 이쪽 발목을 감았다. 칼을 내려 끊었다. 그 사이 앞이 비었다.<br>뒷걸음으로 문까지 겨우 왔다. 팔다리에 줄 자국이 수십 개 났다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-18 } }
  ] }

]);
